INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C1','kor',4,2,'u5',2,'이 단원에서 배울 두 가지 — 온라인 대화 예절을 지키며 대화하기 · 읽는 이를 생각하며 편지 쓰기 — 둘 다 상대를 살피는 일에서 시작',ARRAY['[4국01-04][4국03-04]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C2','kor',4,2,'u5',2,'같은 마음, 다른 방법 — 편지는 천천히 써서 오래 남고 메시지는 떨어져 있어도 빠르게 닿음 — 어느 쪽도 가짜 마음이 아니고 예절이 필요 없는 방법도 아님',ARRAY['[4국01-04]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C3','kor',4,2,'u5',2,'마음을 전하는 여러 방법 — 만나서 말하기 · 전화 · 손 편지 · 온라인 대화 · 영상 대화 — 마음속으로만 생각하거나 남에게 대신 말해 달라고만 하는 것은 전하는 일이 아님',ARRAY['[4국01-04]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C4','kor',4,2,'u5',2,'더 좋은 방법은 없음 — 방법마다 잘하는 일이 달라서 고를 것은 「어느 것이 더 좋은가」가 아니라 「지금 이 상황에 무엇이 알맞은가」',ARRAY['[4국01-04]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C5','kor',4,2,'u5',2,'상황과 방법 잇기 — 상대가 어디에 있는지 · 얼마나 급한지 · 오래 간직할 마음인지를 보고 방법을 고름',ARRAY['[4국01-04]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C6','kor',4,2,'u5',2,'가장 먼저 생각할 것 — 방법을 고르기 전에 상대가 지금 어떤 상황인지, 어떤 마음일지를 먼저 살핌 — 가장 빠른 것 · 내가 편한 것 ✗',ARRAY['[4국01-04]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C7','kor',4,2,'u5',2,'온라인 대화의 뜻 — 인터넷이나 스마트폰 같은 디지털 기기로 주고받는 대화 — 글로도, 목소리로도, 얼굴을 보면서도 함',ARRAY['[4국01-04]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C8','kor',4,2,'u5',2,'온라인 대화의 종류 — 온라인 대화방 · 쪽지와 전자 우편 · 온라인 게시판(댓글) · 영상 통화 · 영상 회의',ARRAY['[4국01-04]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C9','kor',4,2,'u5',2,'온라인 대화 가려내기 — 디지털 기기로 상대와 말이 오가면 온라인 대화 — 혼자 공책에 적거나 혼자 자료를 찾아 읽는 일은 아님',ARRAY['[4국01-04]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C10','kor',4,2,'u5',2,'온라인 대화의 세 가지 특성 — 디지털 기기가 있어야 시작함 · 떨어진 곳에서도 주고받음 · 대화 상대가 누구인지 알기 어려울 때가 있음',ARRAY['[4국01-04]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C11','kor',4,2,'u5',2,'기본 성질이지 규칙이 아님 — 영상 회의는 정해진 같은 시간에 모여야 하고 우리 반 대화방은 누가 말하는지 다 앎 — 어떤 온라인 대화인지에 따라 달라짐',ARRAY['[4국01-04]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C12','kor',4,2,'u5',2,'직접 대화와 같은 점 — 화면이 사이에 있을 뿐 사람과 사람이 뜻을 주고받는 일 — 존중과 배려 · 주제에 맞는 말은 똑같이 필요',ARRAY['[4국01-04]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C13','kor',4,2,'u5',2,'좋은 점과 조심할 점 — 멀리·늦은 시간에도 전함 · 얼굴 보고 하기 어려운 말도 꺼냄 / 개인 정보가 새어 나감 · 남의 사진이나 글을 함부로 옮기면 피해',ARRAY['[4국01-04]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C14','kor',4,2,'u5',2,'온라인 대화를 보는 알맞은 생각 — 조심할 점이 있으니 아예 안 쓰기 ✗ · 편리하니 무엇이든 괜찮다 ✗ — 조심할 점을 알고 예절을 지키며 씀',ARRAY['[4국01-04]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C16','kor',4,2,'u5',3,'주제와 관련 없는 그림말 되풀이 — 모인 까닭(주제)과 상관없는 말이나 그림말을 되풀이하면 대화는 오가도 정해지는 것이 없음',ARRAY['[4국01-04]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C17','kor',4,2,'u5',3,'확인하지 않은 이야기 퍼뜨리기 — 사실인지 확인하지 않은 이야기를 여러 사람이 읽는 곳에 쓰면 그 글에 나온 사람이 크게 다칠 수 있음 — 「아마 맞을걸」도 확인이 아님',ARRAY['[4국01-04]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C18','kor',4,2,'u5',3,'문제가 더 잘 생기는 까닭 — 얼굴을 마주 보지 않아 내 말이 어떻게 닿는지 안 보임 · 이름이 드러나지 않을 때가 있어 평소에 안 할 말도 쉽게 함 — 기기가 나쁜 것이 아님',ARRAY['[4국01-04]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C19','kor',4,2,'u5',3,'온라인 대화가 더 알맞은 때 — 멀리 이사 간 친구에게 소식 전하기 · 아파서 못 온 날 숙제 묻기 · 쑥스러워 못 하던 말 꺼내기 — 문제 상황을 보았다고 나쁜 것이 되지 않음',ARRAY['[4국01-04]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C20','kor',4,2,'u5',3,'온라인 대화 예절 다섯 가지 — 주제와 관련 없는 말·그림말 되풀이 ✗ · 부르기 전에 먼저 묻기 · 올리기 전에 사실 확인 · 보이지 않아도 존중 · 남의 사진·영상은 허락 없이 ✗',ARRAY['[4국01-04]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C21','kor',4,2,'u5',3,'사진·영상은 허락을 받고 — 남의 사진이나 영상을 올리기 전에 찍힌 사람에게 먼저 물어봄 — 재미있어할 것 같아도 마찬가지',ARRAY['[4국01-04]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C22','kor',4,2,'u5',3,'대화방에 부를 때는 먼저 묻기 — 상대가 그 대화방에 들어올지 먼저 물어보고 부름 — 묻지 않고 자꾸 초대하지 않음',ARRAY['[4국01-04]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C23','kor',4,2,'u5',3,'뜻을 알기 어려운 말 — 줄인 말·그림말을 상대가 모르면 대화에서 밀려남 — 쓰던 말을 그대로 쓰지 않고 알아들을 수 있는 말로',ARRAY['[4국01-04]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C24','kor',4,2,'u5',3,'토의할 때 지킬 것 — 말차례를 지킴 · 다른 사람의 의견을 존중하며 들음 · 주제와 관련 있는 이야기 — 토의는 이기는 일이 아니라 함께 정하는 일',ARRAY['[4국01-04]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C25','kor',4,2,'u5',3,'의견이 알맞은지 따지는 기준 — 실제로 할 수 있는 의견인가 · 좋은 점이 불편한 점보다 큰가 — 「좋은 말 같으니까」나 지킬 수 없는 극단(아무 말도 안 하기·아예 안 쓰기) ✗',ARRAY['[4국01-04]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C26','kor',4,2,'u5',5,'온라인 대화가 편리한 때 — 멀리 떨어져 만나기 어려울 때 · 사진이나 자료를 주고받을 때 · 서로 시간이 맞지 않을 때 · 여러 사람에게 한꺼번에 알릴 때',ARRAY['[4국01-04]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C28','kor',4,2,'u5',5,'온라인 대화 계획 네 칸 — 대화 상대(누구와) · 온라인으로 하는 까닭(왜) · 대화 방식(대화방·쪽지·전자 우편·영상 통화) · 대화 주제(무엇을)',ARRAY['[4국01-04]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C29','kor',4,2,'u5',5,'온라인에서도 높임 표현 — 같은 내용도 누구에게 하느냐에 따라 말이 달라짐 — 웃어른께는 화면에서도 높임 표현(「~해 주시겠어요?」·「뵐 수 있을까요?」)',ARRAY['[4국01-04][4국04-04]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C30','kor',4,2,'u5',5,'모르는 사람이 말을 걸 때 — 이름·사는 곳·학교·사진을 알려 주지 않음 · 만나자고 해도 따르지 않음 · 어른께 바로 알림 — 예절이 아니라 나를 지키는 일',ARRAY['[4국01-04]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C31','kor',4,2,'u5',5,'대화하는 동안 지킬 것 — 정한 주제에 맞는 말 · 상대의 말에 답하기 · 먼저 나갈 때 양해 구하기 · 뜻을 모를 말은 풀어서 쓰기',ARRAY['[4국01-04]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C32','kor',4,2,'u5',5,'상대가 못 알아들었을 때 — 못 알아들은 것은 상대 잘못이 아님 — 뜻이 통하도록 풀어서 다시 말함(똑같이 다시 보내기 · 「그것도 모르냐」 ✗)',ARRAY['[4국01-04]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C33','kor',4,2,'u5',5,'점검표의 쓸모 — 「예 / 아니요」 표는 잘한 것처럼 보이려고 채우는 표가 아니라 「아니요」 줄을 찾아 그 줄로 돌아가 고치려고 채우는 표 — 점수가 없음',ARRAY['[4국01-04]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C34','kor',4,2,'u5',5,'다짐은 하나를 지키기 — 오늘 배운 것 가운데 한 가지만 골라 이번 주에 꼭 지킬 일로 — 많이 정하기보다 하나를 지키는 것이 나음',ARRAY['[4국01-04]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C35','kor',4,2,'u5',7,'편지는 아주 오래된 방법 — 종이가 생기기 훨씬 전부터 흙판·나무판·가죽에 글을 적어 보냄 — 기기가 없던 때에도 마음은 오갔음',ARRAY['[4국03-04]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C36','kor',4,2,'u5',7,'편지로 전하면 좋은 점 — 시간이 들어 정성이 담김 · 천천히 정리하고 고쳐 쓸 수 있음 · 글로 남아 오래 간직 · 쑥스러운 말도 씀 — 언제나 빠르다·언제나 더 좋다 ✗',ARRAY['[4국03-04]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C38','kor',4,2,'u5',7,'편지의 짜임 일곱 — 받는 사람 · 첫인사 · 전하고 싶은 말 · 끝인사 · 쓴 날짜 · 쓴 사람 · 추신',ARRAY['[4국03-04]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C39','kor',4,2,'u5',7,'추신은 보탤 말이 있을 때만 — 다 쓴 뒤에 보탤 말이 생겼을 때만 「추신」으로 덧붙임 — 꼭 써야 하는 칸이 아님',ARRAY['[4국03-04]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C40','kor',4,2,'u5',7,'읽는 이에 맞춘 높임 표현 — 웃어른께는 부르는 말(「~께」) · 문장 끝(「~습니다」) · 이름 뒤(「올림·드림」) 세 곳 모두 높임 / 친구에게는 「~에게 · 씀」',ARRAY['[4국03-04][4국04-04]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C41','kor',4,2,'u5',7,'높임은 상대에 맞추는 것 — 높임은 마음의 크기가 아니라 상대에 맞추는 것 — 친구에게 높임말을 쓰지 않는다고 마음이 작은 것이 아님',ARRAY['[4국03-04][4국04-04]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C42','kor',4,2,'u5',7,'모자란 편지의 빈 곳 — 웃어른께 높임을 맞추지 않음 · 무엇이 고마웠는지 알 수 없음 · 첫인사·끝인사·쓴 날짜가 없음 — 길이나 글씨가 흠의 중심이 아님',ARRAY['[4국03-04]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C43','kor',4,2,'u5',7,'「읽는 이를 생각한다」의 뜻 — 전하려는 마음은 그대로 두고 읽는 이의 상황을 살펴 표현을 고름 — 좋아할 말만 골라 쓰기 ✗ · 떠오르는 대로 쓰기 ✗',ARRAY['[4국03-04]']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C44','kor',4,2,'u5',9,'편지 쓰기 전 계획 넷 — 마음을 전할 사람 · 있었던 일 · 전하고 싶은 마음 · 마음을 나타내는 표현',ARRAY['[4국03-04]']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C45','kor',4,2,'u5',9,'편지로 전하기 좋은 일 — 그 사람과 나 사이에 마음이 오간 일(대신 해 준 일 · 이사 가는 이웃 · 동생이 처음 해낸 일) — 급식 반찬 · 날씨 바람은 편지 글감이 되기 어려움',ARRAY['[4국03-04]']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C46','kor',4,2,'u5',9,'마음의 다섯 갈래 — 감사(도움 받음) · 사과(내가 잘못) · 축하(좋은 일) · 위로(힘든 일을 겪는 중) · 응원(무언가를 앞둠)',ARRAY['[4국03-04]']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C47','kor',4,2,'u5',9,'처음 · 가운데 · 끝 — 처음 — 부르는 말·안부·날씨 / 가운데 — 쓴 까닭·있었던 일·그때의 마음·헤아리는 말 / 끝 — 바라는 점·끝인사·쓴 날짜·쓴 사람',ARRAY['[4국03-04]']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C48','kor',4,2,'u5',9,'구체적으로 ≠ 길게 — 무슨 일이 있었는지 읽는 사람이 알 수 있게 쓰는 것 — 더 긴 문장이나 「아주아주·정말정말」 되풀이가 구체적인 것이 아님',ARRAY['[4국03-04]']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C49','kor',4,2,'u5',9,'솔직함과 배려 — 내 마음을 솔직하게 쓰되 상대의 지금 처지를 살핌(다친 친구에게 신나게 뛰어논 이야기 ✗) — 둘 중 하나를 고르는 것이 아님',ARRAY['[4국03-04]']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C50','kor',4,2,'u5',9,'다 쓰고 소리 내어 읽기 — 다 쓴 편지를 소리 내어 천천히 읽으면 쓸 때 안 보이던 곳이 보임 — 점검표는 고쳐 쓸 곳을 찾으려고 채움(점수 없음)',ARRAY['[4국03-04]']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C51','kor',4,2,'u5',9,'편지봉투 쓰는 법 — 보내는 사람은 왼쪽 위 · 받는 사람은 오른쪽 아래 · 우편 번호 다섯 자리 · 웃어른이면 「귀하·님께」, 친구면 「에게·앞」',ARRAY['[4국03-04]']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C52','kor',4,2,'u5',9,'편지는 닿아야 편지 — 다 쓴 편지는 직접 건네거나 우체통에 넣거나 학급에서 모아 함께 나눔 — 써 두기만 하면 마음이 전해지지 않음',ARRAY['[4국03-04]']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C53','kor',4,2,'u5',11,'실천 활동 셋 — 온라인 대화 예절 알리기(표어) · 비밀 친구에게 편지 쓰기 · 매체 견주기 놀이 — 만드는 일은 교실에서, 화면에서는 가려낼 기준을 정함',ARRAY['[4국01-04][4국03-04]']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C54','kor',4,2,'u5',11,'표어다운 것 — 짧은 한 줄 · 한 가지만 · 읽으면 바로 알 수 있는 말 · 무엇을 하자는 것인지가 들어 있음 — 설명처럼 길게 · 「아예 하지 말자」 ✗',ARRAY['[4국01-04][4국03-04]']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C55','kor',4,2,'u5',11,'알리는 방법 정하기 — 언제 · 어디서 · 누구에게 · 어떻게 — 온 학교에 오래 알리려면 여러 사람이 여러 날 볼 수 있는 곳(알림판)',ARRAY['[4국01-04][4국03-04]']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C56','kor',4,2,'u5',11,'비밀 친구 편지 — 이름을 밝히지 않고 정한 기간 동안 씀 · 둘만 겪은 특별한 일은 내가 누구인지 드러나니 쓰지 않고 친구의 좋은 점을 칭찬 · 「○○에게 … 씀」',ARRAY['[4국01-04][4국03-04]']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C57','kor',4,2,'u5',11,'매체마다 잘하는 일 — 매체 견주기 놀이는 이기고 지는 놀이가 아님 — 온라인 대화방은 더 빠르고 편지는 더 오래 남는 것처럼 잘하는 일이 다름',ARRAY['[4국01-04][4국03-04]']::text[],57) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C58','kor',4,2,'u5',11,'겹받침 ㄺ의 소리 — 보통 [ㄱ]만 소리 남(읽다[익따] · 굵다[국따] · 늙다[늑따]) — 뒤에 ㄱ이 오면 [ㄹ](읽고[일꼬] · 굵게[굴께] · 늙고[늘꼬])',ARRAY['[4국04-05](차시 머리 표기) · 겹받침 ㄺ·ㄼ 발음(번호 확인 필요)']::text[],58) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C60','kor',4,2,'u5',11,'온라인에서 다시 쓰면 좋은 말 — 뜻을 알기 어렵게 줄인 말 · 주제와 관련 없는 그림말만 보내기 · 사정을 말하지 않고 툭 던지는 말 — 상대가 알아듣고 서운하지 않게 다시 씀',ARRAY['[4국01-04][4국04-05]']::text[],60) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C61','kor',4,2,'u5',7,'「석원이의 편지」 내용 알기 — 석원이가 할머니께 고구마를 보내 주신 데 대한 감사와 독후감 쓰기 대회 우수상의 기쁨을 전하고 생신 때 찾아뵙겠다고 함(『국어』 239~240쪽 · 받는 사람부터 추신까지 짜임과 높임 표현의 본보기)',ARRAY['[4국03-04]']::text[],61) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C62','kor',4,2,'u5',7,'편지를 읽고 읽는 사람·목적·마음 파악하기 — 누구에게 무엇 때문에 썼는지, 어떤 마음을 어떤 표현으로 드러냈는지 찾음(현승이의 편지 · 정조·안창호·이황의 편지 — 평가 자료 2)',ARRAY['[4국03-04]']::text[],62) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C63','kor',4,2,'u5',3,'토의 순서 — 토의 주제 정하기 → 의견 마련하기 → 의견 모으기 → 의견 결정하기 → 토의 평가하기(온라인 대화 예절 토의 · 토의·토론 학습 모형)',ARRAY['[4국01-04]']::text[],63) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C64','kor',4,2,'u5',11,'겹받침 ㄼ 낱말 바르게 쓰기 — 밟다 · 짧디짧다 · 넓이 · 떫다 · 여덟 · 얇음 · 엷다(『국어』 251쪽 글씨 쓰기)',ARRAY['기초 다지기(글씨 쓰기 — 성취기준 번호 없음)']::text[],64) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C65','kor',4,2,'u5',3,'공익 광고 두 편 — 바르고 고운 말 — ‘윗글이 맑아야 아랫글이 맑다’ · ‘당신이 쓴 악성 댓글 말로 해 보시겠습니까?’: 얼굴을 마주 보지 않고 이름을 밝히지 않아 쉽게 쓰는 악성 댓글을 돌아보고 온라인 대화에서 바르고 고운 말을 쓰자(『국어』 230쪽)',ARRAY['[4국01-04][4국04-05]']::text[],65) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X01','kor',4,'u5',ARRAY['K4-2-u5-C1']::text[],'이 단원에서 배울 내용을 「온라인 대화를 안 하는 법」이나 「편지는 옛날 것」처럼 엉뚱하게 여긴다','상대를 살피는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X02','kor',4,'u5',ARRAY['K4-2-u5-C2']::text[],'전하는 방법에 따라 마음이 진짜이거나 가짜라고 여긴다(편지는 진짜, 메시지는 가짜)','같은 마음, 다른 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X03','kor',4,'u5',ARRAY['K4-2-u5-C2','K4-2-u5-C12']::text[],'온라인 대화나 메시지에서는 예절을 지키지 않아도 된다고 여긴다','화면 너머에도 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X04','kor',4,'u5',ARRAY['K4-2-u5-C3']::text[],'마음속으로만 생각하거나 남에게 대신 말해 달라고만 해도 마음이 전해진다고 여긴다','건네야 전해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X05','kor',4,'u5',ARRAY['K4-2-u5-C4','K4-2-u5-C57']::text[],'어느 한 방법이 언제나 더 좋다고 방법에 등수를 매긴다','상황에 알맞은 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X06','kor',4,'u5',ARRAY['K4-2-u5-C5']::text[],'상대가 있는 곳·급한 정도·간직할 마음을 보지 않고 상황과 방법을 엇갈리게 잇는다','어디에 · 얼마나 급한지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X07','kor',4,'u5',ARRAY['K4-2-u5-C6']::text[],'마음을 전할 때 가장 먼저 생각할 것을 「가장 빠른 방법」으로 여긴다','상대의 상황 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X08','kor',4,'u5',ARRAY['K4-2-u5-C6']::text[],'마음을 전할 때 가장 먼저 생각할 것을 「내가 가장 편한 방법」으로 여긴다','상대의 마음 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X09','kor',4,'u5',ARRAY['K4-2-u5-C7','K4-2-u5-C9']::text[],'혼자 공책에 적거나 혼자 자료를 읽는 일처럼 상대와 말이 오가지 않는 일도 온라인 대화라고 여긴다','말이 오가나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X10','kor',4,'u5',ARRAY['K4-2-u5-C8','K4-2-u5-C10']::text[],'온라인 대화의 종류나 세 가지 특성(기기·시간과 장소·대화 상대)을 엇갈리게 잇는다','무엇 · 어디 · 누구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X11','kor',4,'u5',ARRAY['K4-2-u5-C11']::text[],'온라인 대화의 특성을 언제나 그런 규칙으로 여긴다(언제나 상대를 모름 · 언제 들어가도 상관없음)','대체로 그래요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X12','kor',4,'u5',ARRAY['K4-2-u5-C12']::text[],'온라인 대화는 직접 대화와 전혀 다른 일이라 존중이나 주제에 맞는 말이 필요 없다고 여긴다','똑같은 것도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X13','kor',4,'u5',ARRAY['K4-2-u5-C13','K4-2-u5-C14','K4-2-u5-C19']::text[],'조심할 점이 있으니 온라인 대화는 아예 안 쓰는 것이 가장 좋다고 여긴다','잘 쓰는 법을 배워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X14','kor',4,'u5',ARRAY['K4-2-u5-C13','K4-2-u5-C14','K4-2-u5-C27']::text[],'편리하니까 온라인에서는 무엇을 해도 괜찮고 만나서 하는 대화는 필요 없다고 여긴다','편리함과 예절은 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X15','kor',4,'u5',ARRAY['K4-2-u5-C15','K4-2-u5-C24']::text[],'토의를 화면에서 혼자 끝낼 수 있다고 여기거나 토의를 이기고 지는 일로 여긴다','함께 정하는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X16','kor',4,'u5',ARRAY['K4-2-u5-C16']::text[],'대화방 문제의 까닭을 사람 수나 대화한 시각처럼 엉뚱한 데서 찾는다','모인 까닭은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X17','kor',4,'u5',ARRAY['K4-2-u5-C17']::text[],'「아마 맞을 것」이면 확인하지 않은 이야기도 올려도 되거나, 그 글의 문제를 길이에서 찾는다','올리기 전에 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X18','kor',4,'u5',ARRAY['K4-2-u5-C18']::text[],'온라인 대화에서 문제가 생기는 까닭을 디지털 기기 자체가 나쁜 탓으로 여긴다','얼굴 · 이름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X19','kor',4,'u5',ARRAY['K4-2-u5-C18']::text[],'문제가 생기는 까닭을 「글자 쓰기가 말보다 느려서」처럼 상관없는 데서 찾는다','보이지 않는 얼굴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X20','kor',4,'u5',ARRAY['K4-2-u5-C20','K4-2-u5-C21']::text[],'남의 사진이나 영상은 다들 재미있어하면 허락 없이 올려도 된다고 여긴다','찍힌 사람에게 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X21','kor',4,'u5',ARRAY['K4-2-u5-C20','K4-2-u5-C22']::text[],'상대에게 묻지 않고 대화방에 불러도 되고 자꾸 초대해도 된다고 여긴다','들어올지 먼저 물어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X22','kor',4,'u5',ARRAY['K4-2-u5-C23','K4-2-u5-C32']::text[],'상대가 뜻을 몰라도 내가 쓰던 말을 그대로 쓰거나, 못 알아들은 것을 상대 잘못으로 여긴다','알아듣게 풀어서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X23','kor',4,'u5',ARRAY['K4-2-u5-C20','K4-2-u5-C31']::text[],'답이 늦으면 답할 때까지 계속 말을 걸어 재촉해도 된다고 여긴다','상대의 사정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X24','kor',4,'u5',ARRAY['K4-2-u5-C25']::text[],'의견을 「좋은 말 같으니까」로 고르거나 지킬 수 없는 극단(아무 말도 안 하기 · 아예 안 쓰기)을 예절로 고른다','지킬 수 있는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X25','kor',4,'u5',ARRAY['K4-2-u5-C24']::text[],'토의에서 말차례를 무시하거나 주제와 상관없는 이야기를 해도 된다고 여긴다','말차례 · 존중 · 주제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X26','kor',4,'u5',ARRAY['K4-2-u5-C26','K4-2-u5-C27']::text[],'온라인 대화가 언제나 더 편하다고 여겨 마음 상한 일의 사과도 온라인이 낫다고 고른다','표정과 목소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X27','kor',4,'u5',ARRAY['K4-2-u5-C28','K4-2-u5-C44']::text[],'계획의 칸(누구·왜·어떻게·무엇)과 정한 내용을 엇갈리게 잇는다','누구 · 왜 · 무엇') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X28','kor',4,'u5',ARRAY['K4-2-u5-C29']::text[],'화면에서는 웃어른께도 반말을 쓰거나 재촉하고 낱말만 툭 보내도 된다고 여긴다','화면이라도 높임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X29','kor',4,'u5',ARRAY['K4-2-u5-C30']::text[],'모르는 사람이 물으면 예의를 지켜 이름·학교·사진을 알려 주어야 한다고 여긴다','나를 지키는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X30','kor',4,'u5',ARRAY['K4-2-u5-C30']::text[],'모르는 사람이 말을 걸어오면 어른께 알리지 않고 혼자 넘기거나 혼자 판단한다','어른께 바로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X31','kor',4,'u5',ARRAY['K4-2-u5-C33','K4-2-u5-C50']::text[],'점검하다가 「아니요」가 나오면 「예」가 되도록 표시를 고쳐 둔다','고칠 곳 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X32','kor',4,'u5',ARRAY['K4-2-u5-C33','K4-2-u5-C50']::text[],'점검하다가 「아니요」가 나온 줄은 넘기고 다음 줄만 본다','그 줄로 돌아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X33','kor',4,'u5',ARRAY['K4-2-u5-C34']::text[],'다짐은 많이 정할수록 좋다고 여긴다','하나를 지키기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X34','kor',4,'u5',ARRAY['K4-2-u5-C31','K4-2-u5-C60']::text[],'대화방에서 먼저 나갈 때 아무 말 없이 나가거나 까닭 없이 툭 끊어도 된다고 여긴다','양해를 구해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X35','kor',4,'u5',ARRAY['K4-2-u5-C35','K4-2-u5-C57']::text[],'편지는 옛날 것이라 이제는 쓸 수 없다거나, 기기가 생긴 뒤에 생긴 방법이라고 여긴다','아주 오래된 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X36','kor',4,'u5',ARRAY['K4-2-u5-C36']::text[],'편지는 언제나 빠르게 닿는다거나 다른 방법보다 언제나 더 좋다고 여긴다','천천히 · 오래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X37','kor',4,'u5',ARRAY['K4-2-u5-C37']::text[],'편지가 전하는 마음을 있었던 일과 다르게 짚는다','무슨 일이 있었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X38','kor',4,'u5',ARRAY['K4-2-u5-C38','K4-2-u5-C47']::text[],'편지의 줄과 짜임(첫인사·전하고 싶은 말·끝인사·쓴 사람)을 엇갈리게 잇는다','짜임 일곱') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X39','kor',4,'u5',ARRAY['K4-2-u5-C39']::text[],'추신은 모든 편지에 꼭 써야 하는 칸이라고 여긴다','보탤 말이 있을 때만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X40','kor',4,'u5',ARRAY['K4-2-u5-C40']::text[],'웃어른께 쓰면서 부르는 말·문장 끝·이름 뒤 가운데 일부만 높임으로 맞춘다','세 곳 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X41','kor',4,'u5',ARRAY['K4-2-u5-C41']::text[],'높임말을 쓰지 않으면 마음이 작은 것이라 여겨 친구에게도 「~께 … 올림」을 써야 한다고 여긴다','상대에 맞춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X42','kor',4,'u5',ARRAY['K4-2-u5-C42']::text[],'모자란 편지의 흠을 길이나 글씨에서 찾고 높임·있었던 일·짜임은 살피지 않는다','무엇이 빠졌나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X43','kor',4,'u5',ARRAY['K4-2-u5-C43','K4-2-u5-C49']::text[],'「읽는 이를 생각한다」를 「읽는 이가 좋아할 말만 골라 쓴다」로 여긴다','마음은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X44','kor',4,'u5',ARRAY['K4-2-u5-C43','K4-2-u5-C49']::text[],'읽는 이의 처지는 생각하지 않고 떠오르는 대로 쓰거나, 아예 아무 말도 안 쓰는 것을 배려로 여긴다','처지를 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X45','kor',4,'u5',ARRAY['K4-2-u5-C45']::text[],'급식 반찬이나 날씨 바람처럼 그 사람과 마음이 오가지 않은 일을 편지 글감으로 고른다','마음이 오간 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X46','kor',4,'u5',ARRAY['K4-2-u5-C46']::text[],'상황에 알맞은 마음의 갈래(감사·사과·축하·위로·응원)를 엇갈리게 고른다','상대의 처지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X47','kor',4,'u5',ARRAY['K4-2-u5-C47']::text[],'있었던 일과 그때의 마음을 처음이나 끝에 들어갈 내용으로 여긴다','쓴 까닭은 가운데') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X48','kor',4,'u5',ARRAY['K4-2-u5-C48']::text[],'구체적으로 쓰라는 말을 길게 쓰거나 「아주아주·정말정말」을 되풀이하라는 말로 여긴다','무슨 일인지 알 수 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X49','kor',4,'u5',ARRAY['K4-2-u5-C48']::text[],'「좋았어·고마워」 한마디처럼 짧고 막연한 말이 마음을 더 잘 전한다고 여긴다','읽는 사람이 떠올리게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X50','kor',4,'u5',ARRAY['K4-2-u5-C51']::text[],'편지봉투에서 받는 사람을 왼쪽 위에, 보내는 사람을 오른쪽 아래에 쓴다','받는 사람은 오른쪽 아래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X51','kor',4,'u5',ARRAY['K4-2-u5-C51']::text[],'웃어른께 보내는 봉투에 「앞·에게」를 쓰거나, 우편 번호를 아무렇게나 쓴다','귀하 · 님께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X52','kor',4,'u5',ARRAY['K4-2-u5-C52']::text[],'편지는 써 두기만 하면 전하지 않아도 마음이 전해진다고 여긴다','닿아야 편지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X53','kor',4,'u5',ARRAY['K4-2-u5-C53','K4-2-u5-C54']::text[],'표어를 설명처럼 길게 쓰거나 여러 가지를 한꺼번에 담고, 화면에서 표어를 다 지을 수 있다고 여긴다','한 줄 · 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X54','kor',4,'u5',ARRAY['K4-2-u5-C54']::text[],'「온라인 대화를 아예 하지 말자」처럼 한쪽으로 치우친 말을 표어로 고른다','무엇을 하자?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X55','kor',4,'u5',ARRAY['K4-2-u5-C55']::text[],'알릴 범위와 기간을 생각하지 않고 공책에 적기나 모둠끼리 말하기를 온 학교 알림으로 고른다','몇 사람이 · 며칠 동안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X56','kor',4,'u5',ARRAY['K4-2-u5-C56']::text[],'비밀 친구 편지에 둘만 겪은 특별한 일을 써서 내가 누구인지 드러나게 한다','좋은 점 칭찬') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X57','kor',4,'u5',ARRAY['K4-2-u5-C57','K4-2-u5-C5']::text[],'매체 견주기를 「어느 매체가 모든 면에서 이기나」로 여긴다','잘하는 일이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X58','kor',4,'u5',ARRAY['K4-2-u5-C58']::text[],'ㄺ 뒤에 ㄱ이 와도 [ㄱ]으로 읽거나, ㄺ을 언제나 [ㄹ]로 읽는다','뒤 글자의 첫소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X59','kor',4,'u5',ARRAY['K4-2-u5-C58','K4-2-u5-C59']::text[],'겹받침 두 글자를 모두 소리 내어 읽는다([읽꼬] · [넓따])','하나만 소리 나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X61','kor',4,'u5',ARRAY['K4-2-u5-C60','K4-2-u5-C23']::text[],'다시 쓸 때 더 짧게 줄이거나 그림말만 보내는 것을 알아듣기 쉬운 말로 여긴다','알아듣고 서운하지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X62','kor',4,'u5',ARRAY['K4-2-u5-C31','K4-2-u5-C33']::text[],'온라인 대화를 잘했는지를 주고받은 내용의 재미나 양으로만 판단하고, 예절을 지키며 참여했는지는 살피지 않는다','무엇을 말했나보다 어떻게 말했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X63','kor',4,'u5',ARRAY['K4-2-u5-C61','K4-2-u5-C62']::text[],'편지에 담긴 마음을 한 가지로만 정해, 함께 담긴 다른 마음(감사와 기쁨 · 걱정과 축하)을 놓친다','이 편지에 마음이 하나뿐일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X64','kor',4,'u5',ARRAY['K4-2-u5-C40','K4-2-u5-C42']::text[],'웃어른께 쓰는 글에서 높임 낱말(생신·댁·찾아뵙다·편찮으시다)을 쓰지 않고 예사말(생일·집·가다·아프다)을 그대로 쓴다','이 낱말을 높이는 말은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X65','kor',4,'u5',ARRAY['K4-2-u5-C63','K4-2-u5-C24']::text[],'토의 순서(주제 정하기 → 의견 마련하기 → 의견 모으기 → 의견 결정하기)를 뒤섞어 의견을 마련하기도 전에 결정부터 한다','무엇부터 해야 의견을 모을 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X66','kor',4,'u5',ARRAY['K4-2-u5-C20','K4-2-u5-C11']::text[],'온라인 대화는 시간과 장소의 제약이 없으니 밤늦은 시간에도 상대의 사정을 생각하지 않고 보내고 답을 다그쳐도 된다고 여긴다','지금 상대는 무엇을 하고 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X67','kor',4,'u5',ARRAY['K4-2-u5-C12','K4-2-u5-C60']::text[],'그림말은 예절에 어긋나니 온라인 대화에서 아예 쓰면 안 된다고 여긴다(주제와 관련 없이 되풀이하는 것이 문제임을 가르지 못함)','그림말이 마음을 잘 전할 때는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X68','kor',4,'u5',ARRAY['K4-2-u5-C64']::text[],'겹받침 ㄼ이 들어간 낱말(밟다·짧다·넓이·떫다·여덟·얇음·엷다)을 받침 하나(ㄹ이나 ㅂ)만 적는다','받침 자리에 글자가 둘!') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#1','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C2',1,'mc','auto','『국어』 225쪽 「생각 열기」에서 미나는 규리에게 휴대 전화 메시지로 마음을 전했어요. 미나가 메시지로 전한 내용은 무엇인가요?',ARRAY['K4-2-u5-X02','K4-2-u5-X46','K4-2-u5-X06']::text[],false,'{"seq":1,"concept":"K4-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어』 225쪽 「생각 열기」에서 미나는 규리에게 휴대 전화 메시지로 마음을 전했어요. 미나가 메시지로 전한 내용은 무엇인가요?","options":[{"t":"규리를 생일잔치에 초대하는 내용","correct":true},{"t":"규리의 생일을 축하하는 내용","mis":"K4-2-u5-X02"},{"t":"규리에게 사과하는 내용","mis":"K4-2-u5-X46"},{"t":"규리에게 준비물을 묻는 내용","mis":"K4-2-u5-X06"}],"explanation":["미나는 “토요일 1시에 우리 집에서 생일잔치를 하려고 하는데 올 수 있니?”라고 물었어요.","같은 내용을 손 편지로도 전했어요.","방법은 달라도 전한 내용은 같은 초대예요."],"asset":{"type":"speech","turns":[{"who":"미나","text":"이번 주 토요일이 내 생일이야."},{"who":"규리","text":"미나야, 생일 축하해."},{"who":"미나","text":"토요일 1시에 우리 집에서 생일잔치를 하려고 하는데 올 수 있니?"},{"who":"규리","text":"초대해 주어서 고마워. 꼭 갈게. (웃는 그림말)"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#2','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C3',1,'mc','auto','『국어』 226쪽 2번 그림 가, 나, 다에서 마음을 전하는 방법을 차례대로 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X06','K4-2-u5-X10']::text[],false,'{"seq":2,"concept":"K4-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어』 226쪽 2번 그림 가, 나, 다에서 마음을 전하는 방법을 차례대로 바르게 말한 것은 무엇인가요?","options":[{"t":"직접 만나서 대화하기 — 편지 쓰기 — 전화로 대화하기","correct":true},{"t":"편지 쓰기 — 직접 만나서 대화하기 — 전화로 대화하기","mis":"K4-2-u5-X06"},{"t":"전화로 대화하기 — 편지 쓰기 — 영상 회의 하기","mis":"K4-2-u5-X10"}],"explanation":["가는 만나서 “오랜만이야. 정말 반가워.” 하고 인사해요.","나는 미안한 마음을 글로 써서 전해요.","다는 할아버지께 전화로 생신을 축하드려요."],"asset":{"type":"passage","lines":["[그림 가] 직접 만나서 — “오랜만이야. 정말 반가워.”","         “나도 반가워. 그동안 어떻게 지냈니?”","[그림 나] 편지를 써서 — “그림 숙제를 하느라고 언니가 아끼는","         색연필을 썼어. 미리 말하지 않고 사용해서 미안해.”","[그림 다] 전화로 — “할아버지, 생신 축하드려요.” “고맙구나.”","[그림 ?] 마음을 전하는 또 다른 방법"],"numbered":false,"title":"마음을 전하는 여러 방법 — 『국어』 226쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#3','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C6',1,'ox','auto','상대에게 마음을 표현할 때에는 상대가 처한 상황이나 입장을 살피며 말해야 해요.',ARRAY['K4-2-u5-X07']::text[],false,'{"seq":3,"concept":"K4-2-u5-C6","difficulty":1,"kind":"ox","stem":"상대에게 마음을 표현할 때에는 상대가 처한 상황이나 입장을 살피며 말해야 해요.","answer":"O","reason_options":[{"t":"상대의 사정이나 입장을 살펴야 배려와 존중의 대화가 되기 때문에","correct":true},{"t":"내가 하고 싶은 말을 가장 빨리 전하는 것이 먼저이기 때문에","mis":"K4-2-u5-X07"}],"mis":"K4-2-u5-X07","explanation":["『국어』 227쪽 3번에서 마음을 표현할 때 주의할 점을 이야기했어요.","상대의 상황과 입장을 살피고, 상대에 따라 높임 표현을 써요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"상황에 따라 대화, 편지, 전화, 문자 메시지, 온라인 대화 같은 방법을 선택해야 해."},{"who":"친구 2","text":"상대가 처한 상황이나 입장을 살피며 말해야 해."},{"who":"친구 3","text":"상대에 따라 알맞은 높임 표현을 사용해야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#4','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C7',1,'mc','auto','『국어』 228쪽 1번에서 온라인 대화를 해 본 경험을 나누며 그 뜻을 정리했어요. 온라인 대화의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X09','K4-2-u5-X10','K4-2-u5-X04']::text[],false,'{"seq":4,"concept":"K4-2-u5-C7","difficulty":1,"kind":"mc","stem":"『국어』 228쪽 1번에서 온라인 대화를 해 본 경험을 나누며 그 뜻을 정리했어요. 온라인 대화의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"인터넷이나 스마트폰 응용 프로그램을 활용하여 온라인에서 자유롭게 나누는 대화","correct":true},{"t":"혼자 공책에 적어 두는 오늘의 기록","mis":"K4-2-u5-X09"},{"t":"같은 교실에서 얼굴을 마주 보고 나누는 이야기","mis":"K4-2-u5-X10"},{"t":"마음속으로만 하는 혼잣말","mis":"K4-2-u5-X04"}],"explanation":["온라인 대화는 인터넷이나 스마트폰 응용 프로그램을 써요.","상대와 말이 오가야 대화예요.","일상의 경험을 떠올리면 뜻을 말할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#5','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C8',2,'mc','auto','『국어』 228쪽 그림 다처럼 컴퓨터 화면에 여러 친구의 얼굴이 함께 보이며 이야기하는 온라인 대화는 무엇인가요?',ARRAY['K4-2-u5-X10']::text[],false,'{"seq":5,"concept":"K4-2-u5-C8","difficulty":2,"kind":"mc","stem":"『국어』 228쪽 그림 다처럼 컴퓨터 화면에 여러 친구의 얼굴이 함께 보이며 이야기하는 온라인 대화는 무엇인가요?","options":[{"t":"영상 회의","correct":true},{"t":"질문 게시판","mis":"K4-2-u5-X10"},{"t":"전자 우편","mis":"K4-2-u5-X10"},{"t":"쪽지","mis":"K4-2-u5-X10"}],"explanation":["여러 사람이 한 화면에 함께 보여요.","얼굴을 보며 이야기해요.","온라인 대화의 종류 가운데 영상 회의예요."],"asset":{"type":"passage","lines":["[그림 가] 컴퓨터 화면의 질문 게시판에 글을 쓰는 모습","[그림 나] 휴대 전화 화면을 보는 모습","[그림 다] 컴퓨터 화면에 여러 친구의 얼굴이 함께 보이는 모습","[그림 ?] 내가 해 본 또 다른 온라인 대화"],"numbered":false,"title":"온라인 대화를 해 본 경험 — 『국어』 228쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#6','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C10',2,'match','auto','『국어』 229쪽 3번처럼 온라인 대화를 직접 만나서 나누는 대화와 견주어 정리했어요. 기준에 맞는 온라인 대화의 특성을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u5-C10","difficulty":2,"kind":"match","stem":"『국어』 229쪽 3번처럼 온라인 대화를 직접 만나서 나누는 대화와 견주어 정리했어요. 기준에 맞는 온라인 대화의 특성을 이으세요.","pairs":[{"l":"디지털 기기의 사용","r":"디지털 기기를 사용한다"},{"l":"시간과 장소","r":"상대와 같은 시간과 장소에 있지 않아도 된다"},{"l":"대화 상대","r":"대화 상대가 분명하지 않을 수 있다"}],"mis":"K4-2-u5-X10","explanation":["그림 가는 한국과 미국에서 화면으로 대화해요.","기기가 있으면 떨어진 곳에서도 대화할 수 있어요.","상대가 누구인지 분명하지 않을 때도 있어요."],"asset":{"type":"passage","lines":["[그림 가] 한국(오전)과 미국(오후)에 있는 두 사람이 화면으로 대화한다.","[그림 나] 한자리에 모인 사람들이 얼굴을 보며 대화한다.","         “추천해 준 영화, 정말 재미있더라.”"],"numbered":false,"title":"온라인 대화와 직접 만나서 하는 대화 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#7','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C11',2,'mc','auto','민준이와 지후의 온라인 대화예요. 『국어』 229쪽 4번에서 찾은 온라인 대화의 특성 가운데 이 대화에서 볼 수 있는 것은 무엇인가요?',ARRAY['K4-2-u5-X11','K4-2-u5-X67','K4-2-u5-X10']::text[],false,'{"seq":7,"concept":"K4-2-u5-C11","difficulty":2,"kind":"mc","stem":"민준이와 지후의 온라인 대화예요. 『국어』 229쪽 4번에서 찾은 온라인 대화의 특성 가운데 이 대화에서 볼 수 있는 것은 무엇인가요?","options":[{"t":"그림말로 감정을 나타내고, 상대가 곧바로 답하기도 하고 조금 뒤에 답하기도 한다","correct":true},{"t":"상대가 언제나 그 자리에서 바로 답한다","mis":"K4-2-u5-X11"},{"t":"그림말은 예절에 어긋나니 온라인 대화에서 쓰면 안 된다","mis":"K4-2-u5-X67"},{"t":"서로 같은 곳에 있어야만 대화할 수 있다","mis":"K4-2-u5-X10"}],"explanation":["지후는 엄지를 든 그림말과 웃는 얼굴 그림말을 보냈어요.","오후 3:28에 보낸 말에 오후 3:40에 답이 왔어요.","즉각 반응하는 경우도, 그렇지 않은 경우도 있어요."],"asset":{"type":"speech","turns":[{"who":"민준 (오후 3:25)","text":"지후야, 내일 공원에서 유나랑 자전거 타기로 했는데 너도 같이 갈래?"},{"who":"지후 (오후 3:25)","text":"(엄지를 든 그림말) 몇 시에 갈 거야?"},{"who":"민준 (오후 3:26)","text":"2시."},{"who":"지후 (오후 3:28)","text":"2시 좋아."},{"who":"민준 (오후 3:40)","text":"그럼 내일 2시에 놀이터에서 만나서 같이 가자."},{"who":"지후 (오후 3:43)","text":"(웃는 얼굴 그림말) 그래. 내일 봐."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#8','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C12',2,'ox','auto','온라인 대화는 직접 만나서 나누는 대화와 달라서 주제에 맞는 대화를 하지 않아도 돼요.',ARRAY['K4-2-u5-X12']::text[],false,'{"seq":8,"concept":"K4-2-u5-C12","difficulty":2,"kind":"ox","stem":"온라인 대화는 직접 만나서 나누는 대화와 달라서 주제에 맞는 대화를 하지 않아도 돼요.","answer":"X","reason_options":[{"t":"두 대화 모두 상대와 뜻을 주고받는 의사소통이라 존중과 배려, 주제에 맞는 대화가 똑같이 필요하기 때문에","correct":true},{"t":"온라인 대화에서는 무슨 말을 해도 상대가 알 수 없기 때문에","mis":"K4-2-u5-X12"}],"mis":"K4-2-u5-X12","explanation":["다른 점뿐 아니라 같은 점도 찾아봐요.","존중과 배려, 주제에 맞는 대화는 똑같이 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#9','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C13',2,'ox','auto','개인 정보가 새어 나가거나 남의 사진을 함부로 올려 초상권을 침해할 수 있는 것은 온라인 대화에서 조심할 점이에요.',ARRAY['K4-2-u5-X14']::text[],false,'{"seq":9,"concept":"K4-2-u5-C13","difficulty":2,"kind":"ox","stem":"개인 정보가 새어 나가거나 남의 사진을 함부로 올려 초상권을 침해할 수 있는 것은 온라인 대화에서 조심할 점이에요.","answer":"O","reason_options":[{"t":"온라인 대화에는 좋은 점뿐 아니라 개인 정보 유출, 저작권·초상권 침해 같은 조심할 점도 있기 때문에","correct":true},{"t":"온라인 대화에는 좋은 점만 있기 때문에","mis":"K4-2-u5-X14"}],"mis":"K4-2-u5-X14","explanation":["멀리서도 대화할 수 있는 것은 좋은 점이에요.","개인 정보 유출, 저작권·초상권 침해는 조심할 점이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_basic#10','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C14',3,'error','auto','온라인 대화를 두고 친구들이 말했어요. 『국어』 228~229쪽에서 배운 것과 다르게 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X13','K4-2-u5-X14','K4-2-u5-X12']::text[],false,'{"seq":10,"concept":"K4-2-u5-C14","difficulty":3,"kind":"error","stem":"온라인 대화를 두고 친구들이 말했어요. 『국어』 228~229쪽에서 배운 것과 다르게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — “온라인 대화는 문제가 생길 수 있으니 아예 쓰지 않는 것이 가장 좋아.”","correct":true,"mis_target":"K4-2-u5-X13"},{"t":"친구 가 — “온라인 대화에는 좋은 점도 있고 조심할 점도 있어.”","mis":"K4-2-u5-X14"},{"t":"친구 나 — “온라인 대화에서도 상대를 존중하며 주제에 맞게 말해야 해.”","mis":"K4-2-u5-X12"}],"explanation":["온라인 대화에는 좋은 점과 조심할 점이 함께 있어요.","아예 쓰지 말자는 것이 아니라 예절을 지키며 쓰는 거예요.","친구 다가 다르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#1','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C1',2,'sa','auto','『국어』 227쪽 「무엇을 배울까요」를 보았어요. 소단원 2에서는 읽는 이를 생각하며 무엇을 쓰는 공부를 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C1","difficulty":2,"kind":"sa","stem":"『국어』 227쪽 「무엇을 배울까요」를 보았어요. 소단원 2에서는 읽는 이를 생각하며 무엇을 쓰는 공부를 하나요? 두 글자로 쓰세요.","answer":["편지"],"explanation":["소단원 1은 온라인 대화 예절을 지키며 대화하기예요.","소단원 2는 읽는 이를 생각하며 편지 쓰기예요.","답은 ‘편지’예요."],"asset":{"type":"passage","lines":["소단원 1 온라인 대화 예절을 지키며 대화하기","  ① 온라인 대화의 특성 알기 ② 온라인 대화의 예절 알기","  ③ 예절을 지키며 온라인 대화 하기","소단원 2 읽는 이를 생각하며 편지 쓰기","  ① 읽는 이를 생각하며 편지 쓰는 방법 알기","  ② 읽는 이를 생각하며 마음을 전하는 편지 쓰기"],"title":"무엇을 배울까요 — 『국어』 227쪽"},"mis":"K4-2-u5-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#2','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C5',2,'mc','auto','“상황에 따라 대화, 편지, 전화, 문자 메시지, 온라인 대화 같은 방법을 선택해야 해.”라는 말과 같은 생각은 무엇인가요?',ARRAY['K4-2-u5-X05','K4-2-u5-X07','K4-2-u5-X08']::text[],false,'{"seq":2,"concept":"K4-2-u5-C5","difficulty":2,"kind":"mc","stem":"“상황에 따라 대화, 편지, 전화, 문자 메시지, 온라인 대화 같은 방법을 선택해야 해.”라는 말과 같은 생각은 무엇인가요?","options":[{"t":"어느 한 방법이 늘 좋은 것이 아니라 상황에 알맞은 방법을 고른다","correct":true},{"t":"마음을 전할 때에는 언제나 손 편지가 가장 좋다","mis":"K4-2-u5-X05"},{"t":"가장 빠른 방법인 문자 메시지만 쓰면 된다","mis":"K4-2-u5-X07"},{"t":"내가 가장 편한 방법을 고르면 된다","mis":"K4-2-u5-X08"}],"explanation":["방법마다 좋은 점과 불편한 점이 달라요.","상대와 상황을 먼저 살펴요.","그 상황에 알맞은 방법을 골라요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"상황에 따라 대화, 편지, 전화, 문자 메시지, 온라인 대화 같은 방법을 선택해야 해."},{"who":"친구 2","text":"상대가 처한 상황이나 입장을 살피며 말해야 해."},{"who":"친구 3","text":"상대에 따라 알맞은 높임 표현을 사용해야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#3','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C6',3,'mc','auto','오랫동안 뵙지 못했던 할머니께 그리운 마음을 전하려는 친구가 『국어』 227쪽 3번에서 말한 주의할 점을 지킨 것은 무엇인가요?',ARRAY['K4-2-u5-X28','K4-2-u5-X44','K4-2-u5-X07']::text[],false,'{"seq":3,"concept":"K4-2-u5-C6","difficulty":3,"kind":"mc","stem":"오랫동안 뵙지 못했던 할머니께 그리운 마음을 전하려는 친구가 『국어』 227쪽 3번에서 말한 주의할 점을 지킨 것은 무엇인가요?","options":[{"t":"할머니의 상황을 살피고, 웃어른이니 알맞은 높임 표현을 쓴다","correct":true},{"t":"친구에게 하듯이 반말로 짧게 쓴다","mis":"K4-2-u5-X28"},{"t":"할머니가 어떻게 지내시는지는 생각하지 않고 내 소식만 쓴다","mis":"K4-2-u5-X44"},{"t":"가장 빠른 방법이면 무엇이든 괜찮다","mis":"K4-2-u5-X07"}],"explanation":["『국어』 226쪽 1번에서 할머니께 그리운 마음을 전하고 싶었다는 경험이 나왔어요.","상대의 상황과 입장을 살펴요.","상대가 웃어른이면 높임 표현을 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"준비물을 빌려준 친구에게 고마운 마음을 전하고 싶었어."},{"who":"친구 2","text":"생일인 친구에게 축하하는 마음을 표현하고 싶었어."},{"who":"친구 3","text":"오랫동안 뵙지 못했던 할머니께 그리운 마음을 전하고 싶었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#4','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C3',3,'mc','auto','『국어』 226쪽 그림 나에서 “미리 말하지 않고 사용해서 미안해.”라고 쓴 친구는 어떤 마음을 어떤 방법으로 전했나요?',ARRAY['K4-2-u5-X46','K4-2-u5-X06','K4-2-u5-X04']::text[],false,'{"seq":4,"concept":"K4-2-u5-C3","difficulty":3,"kind":"mc","stem":"『국어』 226쪽 그림 나에서 “미리 말하지 않고 사용해서 미안해.”라고 쓴 친구는 어떤 마음을 어떤 방법으로 전했나요?","options":[{"t":"언니의 색연필을 미리 말하지 않고 쓴 일에 대한 미안한 마음을 편지로 전했다","correct":true},{"t":"언니에게 고마운 마음을 전화로 전했다","mis":"K4-2-u5-X46"},{"t":"할아버지께 축하하는 마음을 만나서 전했다","mis":"K4-2-u5-X06"},{"t":"미안한 마음을 마음속으로만 생각했다","mis":"K4-2-u5-X04"}],"explanation":["그림 숙제를 하느라 언니가 아끼는 색연필을 썼어요.","미리 말하지 않아서 미안한 마음이에요.","그 마음을 글로 써서 전했어요."],"asset":{"type":"passage","lines":["[그림 가] 직접 만나서 — “오랜만이야. 정말 반가워.”","         “나도 반가워. 그동안 어떻게 지냈니?”","[그림 나] 편지를 써서 — “그림 숙제를 하느라고 언니가 아끼는","         색연필을 썼어. 미리 말하지 않고 사용해서 미안해.”","[그림 다] 전화로 — “할아버지, 생신 축하드려요.” “고맙구나.”","[그림 ?] 마음을 전하는 또 다른 방법"],"numbered":false,"title":"마음을 전하는 여러 방법 — 『국어』 226쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#5','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C4',3,'ox','auto','『국어』 226쪽 2번의 여러 방법 가운데 직접 만나서 하는 대화가 언제나 가장 좋은 방법이에요.',ARRAY['K4-2-u5-X05']::text[],false,'{"seq":5,"concept":"K4-2-u5-C4","difficulty":3,"kind":"ox","stem":"『국어』 226쪽 2번의 여러 방법 가운데 직접 만나서 하는 대화가 언제나 가장 좋은 방법이에요.","answer":"X","reason_options":[{"t":"방법마다 좋은 점과 불편한 점이 있어서 상대와 상황에 알맞은 방법을 골라야 하기 때문에","correct":true},{"t":"얼굴을 보며 말하면 어떤 상황에서도 마음이 가장 잘 전해지기 때문에","mis":"K4-2-u5-X05"}],"mis":"K4-2-u5-X05","explanation":["각 방법에 어떤 좋은 점과 불편한 점이 있는지 살펴봐요.","언제나 가장 좋은 방법은 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#6','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C9',3,'mc','auto','『국어』 228쪽에서 떠올린 온라인 대화 경험과 견주어 보아요. 다음 가운데 온라인 대화가 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X10']::text[],false,'{"seq":6,"concept":"K4-2-u5-C9","difficulty":3,"kind":"mc","stem":"『국어』 228쪽에서 떠올린 온라인 대화 경험과 견주어 보아요. 다음 가운데 온라인 대화가 아닌 것은 무엇인가요?","options":[{"t":"혼자 책을 읽고 독서 공책에 느낀 점을 적는다","correct":true},{"t":"질문 게시판에 궁금한 점을 올리고 답글을 받는다","mis":"K4-2-u5-X10"},{"t":"영상 통화로 멀리 사는 친척과 이야기한다","mis":"K4-2-u5-X10"},{"t":"온라인 대화방에서 모둠 친구들과 의견을 나눈다","mis":"K4-2-u5-X10"}],"explanation":["온라인 대화는 디지털 기기로 상대와 말을 주고받아요.","게시판 댓글, 영상 통화, 대화방은 모두 온라인 대화예요.","혼자 적는 일은 대화가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#7','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C11',3,'ox','auto','지후가 오후 3:28에 보낸 말에 민준이가 오후 3:40에 답한 것처럼, 온라인 대화에서는 상대가 곧바로 답하지 않을 때도 있어요.',ARRAY['K4-2-u5-X11']::text[],false,'{"seq":7,"concept":"K4-2-u5-C11","difficulty":3,"kind":"ox","stem":"지후가 오후 3:28에 보낸 말에 민준이가 오후 3:40에 답한 것처럼, 온라인 대화에서는 상대가 곧바로 답하지 않을 때도 있어요.","answer":"O","reason_options":[{"t":"온라인 대화에서는 상대가 즉각 반응하는 경우도 있고 그렇지 않은 경우도 있기 때문에","correct":true},{"t":"온라인 대화에서는 언제나 상대가 바로 답해야 하기 때문에","mis":"K4-2-u5-X11"}],"mis":"K4-2-u5-X11","explanation":["『국어』 229쪽 4번에서 반응 시간을 살펴보았어요.","온라인 대화는 바로 답이 올 때도, 늦게 올 때도 있어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"민준 (오후 3:25)","text":"지후야, 내일 공원에서 유나랑 자전거 타기로 했는데 너도 같이 갈래?"},{"who":"지후 (오후 3:25)","text":"(엄지를 든 그림말) 몇 시에 갈 거야?"},{"who":"민준 (오후 3:26)","text":"2시."},{"who":"지후 (오후 3:28)","text":"2시 좋아."},{"who":"민준 (오후 3:40)","text":"그럼 내일 2시에 놀이터에서 만나서 같이 가자."},{"who":"지후 (오후 3:43)","text":"(웃는 얼굴 그림말) 그래. 내일 봐."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#8','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C2',4,'essay','teacher','미나처럼 친구를 생일잔치에 초대하려고 해요. 손 편지와 휴대 전화 메시지 가운데 하나를 골라 그 방법의 좋은 점을 쓰고, 그 방법으로 보낼 초대의 말을 한두 문장으로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C2","difficulty":4,"kind":"essay","stem":"미나처럼 친구를 생일잔치에 초대하려고 해요. 손 편지와 휴대 전화 메시지 가운데 하나를 골라 그 방법의 좋은 점을 쓰고, 그 방법으로 보낼 초대의 말을 한두 문장으로 쓰세요.","answer_guide":{"answer":"예: 손 편지 — 보내는 사람의 예의와 정성을 보여 줄 수 있다. 「이번 주 토요일 1시에 우리 집에서 생일잔치를 해. 네가 와 준다면 정말 기쁠 거야.」 / 휴대 전화 메시지 — 내용을 빠르게 전하고 그림말로 감정도 나타낼 수 있다.","scoring_points":["방법 하나를 골랐는가","그 방법의 좋은 점을 썼는가","초대하는 내용이 드러나게 썼는가"]},"explanation":["손 편지는 정성과 예의를 보여 줘요.","메시지는 빠르고 그림말을 쓸 수 있어요.","언제, 어디에서 하는지 초대 내용을 담아요."],"asset":{"type":"passage","lines":["소중한 친구에게","안녕? 규리야.","이번 주 토요일이 내 생일이어서 친구들을 초대하려고 해.","(간추림) 생일잔치에 와 준다면 정말 기쁠 거라며 토요일 1시에","(간추림) 우리 집에 올 수 있는지 알려 달라고 했다.","20○○년 ○○월 ○○일 미나가"],"title":"미나가 규리에게 쓴 손 편지 — 『국어』 225쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#9','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C10',4,'essay','teacher','『국어』 229쪽 2번 그림 가와 그림 나를 견주어, 디지털 기기의 사용 · 시간과 장소 · 대화 상대 가운데 두 가지 기준으로 다른 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C10","difficulty":4,"kind":"essay","stem":"『국어』 229쪽 2번 그림 가와 그림 나를 견주어, 디지털 기기의 사용 · 시간과 장소 · 대화 상대 가운데 두 가지 기준으로 다른 점을 쓰세요.","answer_guide":{"answer":"예: 디지털 기기의 사용 — 그림 가는 디지털 기기를 사용하고 그림 나는 사용하지 않는다. 시간과 장소 — 그림 가는 한국과 미국처럼 떨어진 곳에서도 대화하지만 그림 나는 같은 시간에 같은 곳에 모여야 한다.","scoring_points":["두 가지 기준을 골랐는가","기준마다 그림 가(온라인 대화)의 특성을 썼는가","기준마다 그림 나(직접 만나서 하는 대화)의 특성을 썼는가"]},"explanation":["그림 가는 화면으로, 그림 나는 한자리에서 대화해요.","기준을 하나씩 정해 견주어요.","같은 기준으로 두 대화를 나란히 써요."],"asset":{"type":"passage","lines":["[그림 가] 한국(오전)과 미국(오후)에 있는 두 사람이 화면으로 대화한다.","[그림 나] 한자리에 모인 사람들이 얼굴을 보며 대화한다.","         “추천해 준 영화, 정말 재미있더라.”"],"numbered":false,"title":"온라인 대화와 직접 만나서 하는 대화 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L02_challenge#10','kor',4,2,'u5','L02','tb_g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C14',4,'essay','teacher','온라인 대화의 좋은 점 한 가지와 조심할 점 한 가지를 쓰고, 온라인 대화를 어떻게 쓰면 좋을지 자신의 생각을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C14","difficulty":4,"kind":"essay","stem":"온라인 대화의 좋은 점 한 가지와 조심할 점 한 가지를 쓰고, 온라인 대화를 어떻게 쓰면 좋을지 자신의 생각을 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 멀리 있는 친구와도 이야기할 수 있다. 조심할 점 — 개인 정보가 새어 나가거나 남의 사진을 허락 없이 올려 초상권을 침해할 수 있다. 그래서 아예 안 쓰기보다 조심할 점을 알고 예절을 지키며 쓰겠다.","scoring_points":["좋은 점을 한 가지 썼는가","조심할 점을 한 가지 썼는가","예절을 지키며 쓴다는 생각을 썼는가"]},"explanation":["좋은 점과 조심할 점을 함께 봐요.","조심할 점이 있다고 아예 쓰지 않을 일은 아니에요.","예절을 지키며 알맞게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#1','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C65',1,'mc','auto','『국어』 230쪽 광고 가와 광고 나의 주제로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X13','K4-2-u5-X17','K4-2-u5-X19']::text[],false,'{"seq":1,"concept":"K4-2-u5-C65","difficulty":1,"kind":"mc","stem":"『국어』 230쪽 광고 가와 광고 나의 주제로 알맞은 것은 무엇인가요?","options":[{"t":"온라인 대화를 할 때 바르고 고운 말을 사용하자","correct":true},{"t":"온라인 대화는 되도록 하지 말자","mis":"K4-2-u5-X13"},{"t":"댓글은 길게 쓸수록 좋다","mis":"K4-2-u5-X17"},{"t":"마이크를 쓰면 말을 더 잘할 수 있다","mis":"K4-2-u5-X19"}],"explanation":["두 광고는 모두 댓글과 말에 대한 광고예요.","인터넷에서 바른 언어를 쓰지 않는 일이 있어서 만들어졌어요.","바르고 고운 말을 쓰자는 것이 주제예요."],"asset":{"type":"passage","lines":["[광고 가] 윗글이 맑아야 아랫글이 맑다","[광고 나] 당신이 쓴 악성 댓글 ‘말’로 해 보시겠습니까?","         (마이크에 ‘bsf9****’처럼 일부를 가린 아이디가 적혀 있다.)","         생각이 달라서 비난 한 줄 / 스트레스 때문에 욕설 한 줄","         무심코 쓴 당신의 댓글 한 줄 입에 달기 부끄럽지 않으신가요?"],"numbered":false,"title":"공익 광고 두 편 — 『국어』 230쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#2','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C65',1,'mc','auto','광고 가에서 “윗글이 맑아야 아랫글이 맑다”고 표현한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X16','K4-2-u5-X19']::text[],false,'{"seq":2,"concept":"K4-2-u5-C65","difficulty":1,"kind":"mc","stem":"광고 가에서 “윗글이 맑아야 아랫글이 맑다”고 표현한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"처음에 좋은 말을 댓글에 쓰면 그 댓글을 읽는 사람도 기분이 좋아져 좋은 댓글을 쓰게 되기 때문에","correct":true},{"t":"위에 쓴 글은 아래 글보다 언제나 중요하기 때문에","mis":"K4-2-u5-X16"},{"t":"글자를 맑은 색으로 써야 읽기 쉽기 때문에","mis":"K4-2-u5-X19"}],"explanation":["윗글은 먼저 쓴 댓글, 아랫글은 그 뒤에 이어지는 댓글이에요.","좋은 댓글을 읽으면 기분이 좋아져요.","그래서 좋은 댓글이 이어지게 돼요."],"asset":{"type":"passage","lines":["[광고 가] 윗글이 맑아야 아랫글이 맑다","[광고 나] 당신이 쓴 악성 댓글 ‘말’로 해 보시겠습니까?","         (마이크에 ‘bsf9****’처럼 일부를 가린 아이디가 적혀 있다.)","         생각이 달라서 비난 한 줄 / 스트레스 때문에 욕설 한 줄","         무심코 쓴 당신의 댓글 한 줄 입에 달기 부끄럽지 않으신가요?"],"numbered":false,"title":"공익 광고 두 편 — 『국어』 230쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#3','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C16',1,'mc','auto','『국어』 231쪽 상황 가에서 찾을 수 있는 온라인 대화의 문제점은 무엇인가요?',ARRAY['K4-2-u5-X16','K4-2-u5-X12']::text[],false,'{"seq":3,"concept":"K4-2-u5-C16","difficulty":1,"kind":"mc","stem":"『국어』 231쪽 상황 가에서 찾을 수 있는 온라인 대화의 문제점은 무엇인가요?","options":[{"t":"대화 주제와 관련 없는 그림말을 반복하여 사용했다","correct":true},{"t":"대화방에 모인 사람이 너무 많았다","mis":"K4-2-u5-X16"},{"t":"준비물을 물어본 것 자체가 잘못이다","mis":"K4-2-u5-X12"},{"t":"대화한 시각이 너무 일렀다","mis":"K4-2-u5-X16"}],"explanation":["친구는 내일 준비물을 물었어요.","그런데 대화방에는 그림말만 이어졌어요.","주제와 관련 없는 그림말을 되풀이한 것이 문제예요."],"asset":{"type":"passage","lines":["[상황 가] 한 친구가 “내일 준비물이 뭐였지?” 하고 물었다.","         대화방에는 그림말만 잇따라 올라온다."],"numbered":false,"title":"온라인 대화 상황 가 — 『국어』 231쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#4','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C17',1,'mc','auto','『국어』 231쪽 상황 나에서 찾을 수 있는 온라인 대화의 문제점은 무엇인가요?',ARRAY['K4-2-u5-X17','K4-2-u5-X16']::text[],false,'{"seq":4,"concept":"K4-2-u5-C17","difficulty":1,"kind":"mc","stem":"『국어』 231쪽 상황 나에서 찾을 수 있는 온라인 대화의 문제점은 무엇인가요?","options":[{"t":"자신의 이름이 드러나지 않는다고 여러 사람이 읽는 게시판에 다른 사람에 대한 소문을 썼다","correct":true},{"t":"게시판 글이 너무 짧았다","mis":"K4-2-u5-X17"},{"t":"글을 쓴 시각이 표시되어 있다","mis":"K4-2-u5-X16"}],"explanation":["‘소리 요정’, ‘천재 작가’처럼 이름을 밝히지 않았어요.","여러 사람이 읽는 게시판에 남의 소문을 올렸어요.","사실인지 모르는 소문은 그 사람을 다치게 할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"소리 요정 (10/15 15:20)","text":"○○에 대한 소문 들었어? 난 다 알고 있음."},{"who":"한글 박사 (10/15 15:25)","text":"뭔데? 빨리 말해 봐!"},{"who":"천재 작가 (10/15 15:26)","text":"나도 알고 있지. ㅋㅋㅋ 내가 어제 게시판에 올린 그 소문이지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#5','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C18',2,'blank','auto','상황 가와 상황 나처럼 온라인 대화에서 문제가 생기는 까닭을 정리했어요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#6','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C20',2,'match','auto','『국어』 232쪽 3번의 문제 상황과 지켜야 할 예절을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u5-C20","difficulty":2,"kind":"match","stem":"『국어』 232쪽 3번의 문제 상황과 지켜야 할 예절을 알맞게 이으세요.","pairs":[{"l":"그림 가 — 묻지 않고 자꾸 대화방에 초대함","r":"초대할 때에는 상대에게 먼저 물어본다"},{"l":"그림 나 — 길동이 사진을 올리려 함","r":"다른 사람의 사진은 허락 없이 공유하지 않는다"},{"l":"그림 다 — 사실인지 모르는 채 올리려 함","r":"자료를 올리기 전에 사실인지 확인한다"}],"mis":"K4-2-u5-X21","explanation":["문제 상황마다 고쳐야 할 점이 달라요.","초대 · 사진 · 사실 확인을 하나씩 짝 지어요.","이것이 온라인 대화 예절이 돼요."],"asset":{"type":"passage","lines":["[그림 가] “왜 나에게 물어보지도 않고 대화방에 자꾸 초대하는 거야?”","[그림 나] “길동이 사진을 온라인 대화방에 올리면 다들 재미있어하겠지?”","[그림 다] “사실인지는 잘 모르겠지만, 일단 게시판에 올려 볼까?”","[그림 ?] 온라인 대화를 할 때 생길 수 있는 또 다른 문제"],"numbered":false,"title":"온라인 대화를 할 때 생길 수 있는 문제 — 『국어』 232쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#7','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C21',2,'mc','auto','“길동이 사진을 온라인 대화방에 올리면 다들 재미있어하겠지?”라고 생각하는 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X20','K4-2-u5-X17']::text[],false,'{"seq":7,"concept":"K4-2-u5-C21","difficulty":2,"kind":"mc","stem":"“길동이 사진을 온라인 대화방에 올리면 다들 재미있어하겠지?”라고 생각하는 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"사진에 나온 길동이와 사진을 찍은 사람에게 먼저 동의를 구해야 해","correct":true},{"t":"다들 재미있어하면 허락 없이 올려도 돼","mis":"K4-2-u5-X20"},{"t":"일단 올리고 싫다고 하면 그때 지우면 돼","mis":"K4-2-u5-X17"}],"explanation":["다른 사람의 사진은 그 사람의 것이에요.","등장하는 사람과 찍은 사람에게 동의를 구해요.","개인 정보가 담겨 있지 않은지도 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#8','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C22',2,'ox','auto','친한 친구라면 묻지 않고 대화방에 여러 번 초대해도 괜찮아요.',ARRAY['K4-2-u5-X21']::text[],false,'{"seq":8,"concept":"K4-2-u5-C22","difficulty":2,"kind":"ox","stem":"친한 친구라면 묻지 않고 대화방에 여러 번 초대해도 괜찮아요.","answer":"X","reason_options":[{"t":"상대에게 양해를 구하고, 상대의 뜻과 상관없이 반복하여 초대하지 않아야 하기 때문에","correct":true},{"t":"친한 사이에는 온라인 대화 예절이 필요 없기 때문에","mis":"K4-2-u5-X21"}],"mis":"K4-2-u5-X21","explanation":["그림 가의 친구는 묻지도 않고 자꾸 초대해서 속상했어요.","먼저 상대의 뜻을 물어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#9','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C63',2,'mc','auto','온라인 대화 예절을 주제로 토의를 해요. 토의 순서를 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K4-2-u5-X65']::text[],false,'{"seq":9,"concept":"K4-2-u5-C63","difficulty":2,"kind":"mc","stem":"온라인 대화 예절을 주제로 토의를 해요. 토의 순서를 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"토의 주제 정하기 → 의견 마련하기 → 의견 모으기 → 의견 결정하기","correct":true},{"t":"의견 결정하기 → 토의 주제 정하기 → 의견 모으기 → 의견 마련하기","mis":"K4-2-u5-X65"},{"t":"의견 모으기 → 의견 결정하기 → 의견 마련하기 → 토의 주제 정하기","mis":"K4-2-u5-X65"}],"explanation":["먼저 무엇을 토의할지 주제를 정해요.","각자 의견을 마련하고 모아요.","모은 의견 가운데에서 결정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_basic#10','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C25',3,'error','auto','토의에서 의견이 적절한지 판단하는 방법을 두고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?',ARRAY['K4-2-u5-X24']::text[],false,'{"seq":10,"concept":"K4-2-u5-C25","difficulty":3,"kind":"error","stem":"토의에서 의견이 적절한지 판단하는 방법을 두고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“온라인 대화를 아예 하지 말자는 의견이 가장 확실하니까 그걸로 정하자.”","correct":true,"mis_target":"K4-2-u5-X24"},{"t":"“실천이 가능한 의견인지 따져 봐야 해.”","mis":"K4-2-u5-X24"},{"t":"“장점이 단점보다 더 큰지 생각해 봐야 해.”","mis":"K4-2-u5-X24"}],"explanation":["의견은 실천할 수 있는지 따져요.","장점이 단점보다 큰지도 생각해요.","아예 하지 말자는 의견은 실천하기 어렵고 좋은 점까지 잃어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#1','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C65',2,'sa','auto','광고 나의 문구예요. 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#2','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C19',2,'mc','auto','『국어』 230~233쪽에서 온라인 대화의 문제점을 공부했어요. 이 공부를 마친 뒤의 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X13','K4-2-u5-X14','K4-2-u5-X18']::text[],false,'{"seq":2,"concept":"K4-2-u5-C19","difficulty":2,"kind":"mc","stem":"『국어』 230~233쪽에서 온라인 대화의 문제점을 공부했어요. 이 공부를 마친 뒤의 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"온라인 대화의 부정적인 면만 보지 말고, 좋은 점을 살리며 예절을 지켜 쓴다","correct":true},{"t":"문제가 많으니 온라인 대화는 무조건 쓰지 말아야 한다","mis":"K4-2-u5-X13"},{"t":"문제는 남의 일이니 나는 하던 대로 써도 된다","mis":"K4-2-u5-X14"},{"t":"문제는 기기 때문이니 새 기기로 바꾸면 된다","mis":"K4-2-u5-X18"}],"explanation":["온라인 대화에는 부정적인 면도 긍정적인 면도 있어요.","무조건 쓰지 말자는 것이 아니에요.","예절을 지키며 쓰는 것이 공부의 목표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#3','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C23',3,'mc','auto','지후와 유나의 온라인 대화예요. 지후가 고칠 점을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X22','K4-2-u5-X61','K4-2-u5-X12']::text[],false,'{"seq":3,"concept":"K4-2-u5-C23","difficulty":3,"kind":"mc","stem":"지후와 유나의 온라인 대화예요. 지후가 고칠 점을 바르게 말한 것은 무엇인가요?","options":[{"t":"그림말만 보내 뜻이 통하지 않았으니, 무엇을 묻는지 알아들을 수 있는 말로 써야 한다","correct":true},{"t":"유나가 그림말의 뜻을 모르는 것이 잘못이다","mis":"K4-2-u5-X22"},{"t":"그림말을 더 많이 보내면 뜻이 통한다","mis":"K4-2-u5-X61"},{"t":"지후는 잘못한 것이 없다","mis":"K4-2-u5-X12"}],"explanation":["유나는 “???”, “뭐라는 거야?” 하고 되물었어요.","그림말만으로는 무엇을 묻는지 알 수 없었어요.","상대가 알아들을 수 있는 말로 써야 해요."],"asset":{"type":"speech","turns":[{"who":"지후","text":"(그림말만 잇따라 보냄)"},{"who":"유나","text":"???"},{"who":"지후","text":"(그림말만 또 잇따라 보냄)"},{"who":"유나","text":"뭐라는 거야?"},{"who":"지후","text":"뭐 하고 놀 건지, 어떤 간식 먹을 건지 물어본 거잖아!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#4','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C20',3,'mc','auto','유나가 지후에게 보낸 메시지예요. 유나의 메시지에서 고칠 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X66','K4-2-u5-X23','K4-2-u5-X13']::text[],false,'{"seq":4,"concept":"K4-2-u5-C20","difficulty":3,"kind":"mc","stem":"유나가 지후에게 보낸 메시지예요. 유나의 메시지에서 고칠 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"밤늦은 시간이니 상대의 사정을 생각하고, 답이 없다고 다그치지 않는다","correct":true},{"t":"온라인 대화는 시간 제약이 없으니 고칠 점이 없다","mis":"K4-2-u5-X66"},{"t":"답을 빨리 받으려면 더 자주 보내야 한다","mis":"K4-2-u5-X23"},{"t":"숙제는 온라인으로 물으면 안 된다","mis":"K4-2-u5-X13"}],"explanation":["유나는 오후 10시 50분과 11시 40분에 메시지를 보냈어요.","밤늦은 시간에는 상대가 답하기 어려울 수 있어요.","답이 없다고 다그치면 상대의 기분이 상해요."],"asset":{"type":"speech","turns":[{"who":"유나 (오후 10:50)","text":"내일 숙제 뭐였어? 기억이 안 나ㅠㅠ"},{"who":"유나 (오후 11:40)","text":"김지후, 너 왜 확인을 안 해?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#5','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C17',3,'ox','auto','“사실인지는 잘 모르겠지만, 일단 게시판에 올려 볼까?”처럼 올린 뒤에 사실인지 알아보아도 괜찮아요.',ARRAY['K4-2-u5-X17']::text[],false,'{"seq":5,"concept":"K4-2-u5-C17","difficulty":3,"kind":"ox","stem":"“사실인지는 잘 모르겠지만, 일단 게시판에 올려 볼까?”처럼 올린 뒤에 사실인지 알아보아도 괜찮아요.","answer":"X","reason_options":[{"t":"인터넷에 남긴 글은 지우기 어렵고, 사실이 아닌 내용으로 오해가 생길 수 있어 올리기 전에 확인해야 하기 때문에","correct":true},{"t":"틀린 내용이면 나중에 지우면 되기 때문에","mis":"K4-2-u5-X17"}],"mis":"K4-2-u5-X17","explanation":["자료를 올리기 전에 사실인지 확인해요.","잘못된 정보는 오해를 만들어요.","그래서 X예요."],"asset":{"type":"passage","lines":["[그림 가] “왜 나에게 물어보지도 않고 대화방에 자꾸 초대하는 거야?”","[그림 나] “길동이 사진을 온라인 대화방에 올리면 다들 재미있어하겠지?”","[그림 다] “사실인지는 잘 모르겠지만, 일단 게시판에 올려 볼까?”","[그림 ?] 온라인 대화를 할 때 생길 수 있는 또 다른 문제"],"numbered":false,"title":"온라인 대화를 할 때 생길 수 있는 문제 — 『국어』 232쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#6','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C24',3,'mc','auto','토의에서 의견을 모을 때 주의할 점을 바르게 모은 것은 무엇인가요?',ARRAY['K4-2-u5-X15','K4-2-u5-X25']::text[],false,'{"seq":6,"concept":"K4-2-u5-C24","difficulty":3,"kind":"mc","stem":"토의에서 의견을 모을 때 주의할 점을 바르게 모은 것은 무엇인가요?","options":[{"t":"토의 주제와 관련 있는 이야기를 한다 · 말차례를 지킨다 · 다른 사람의 의견을 존중하며 듣는다","correct":true},{"t":"내 의견이 뽑히도록 크게 말한다 · 다른 의견은 끝까지 반대한다","mis":"K4-2-u5-X15"},{"t":"주제와 상관없는 재미있는 이야기로 분위기를 띄운다","mis":"K4-2-u5-X25"}],"explanation":["토의는 함께 좋은 의견을 정하는 일이에요.","주제에 맞게, 차례를 지켜 말해요.","다른 사람의 의견도 존중하며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#7','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C18',3,'mc','auto','『국어』 231쪽 상황 나에서 글쓴이는 ‘소리 요정’, ‘한글 박사’, ‘천재 작가’처럼 이름을 밝히지 않았어요. 이런 상황에서 문제가 더 잘 생기는 까닭은 무엇인가요?',ARRAY['K4-2-u5-X19','K4-2-u5-X18']::text[],false,'{"seq":7,"concept":"K4-2-u5-C18","difficulty":3,"kind":"mc","stem":"『국어』 231쪽 상황 나에서 글쓴이는 ‘소리 요정’, ‘한글 박사’, ‘천재 작가’처럼 이름을 밝히지 않았어요. 이런 상황에서 문제가 더 잘 생기는 까닭은 무엇인가요?","options":[{"t":"이름을 밝히지 않고 대화할 수 있어서, 사실이 확실하지 않은 이야기나 소문을 쉽게 말하게 되기 때문","correct":true},{"t":"대화명이 재미있어서 모두가 글을 많이 읽기 때문","mis":"K4-2-u5-X19"},{"t":"게시판은 디지털 기기로 쓰는 것이라 원래 나쁘기 때문","mis":"K4-2-u5-X18"}],"explanation":["이름이 드러나지 않으면 말에 책임을 덜 느끼기 쉬워요.","대화 상대가 분명하지 않을 수 있어요.","그래서 험담이나 소문을 쉽게 말하게 돼요."],"asset":{"type":"speech","turns":[{"who":"소리 요정 (10/15 15:20)","text":"○○에 대한 소문 들었어? 난 다 알고 있음."},{"who":"한글 박사 (10/15 15:25)","text":"뭔데? 빨리 말해 봐!"},{"who":"천재 작가 (10/15 15:26)","text":"나도 알고 있지. ㅋㅋㅋ 내가 어제 게시판에 올린 그 소문이지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#8','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C20',4,'essay','teacher','『국어』 233쪽 4번 (2)에서 정한 온라인 대화 예절 가운데 반드시 지켜야 한다고 생각하는 것 하나를 고르고, 그렇게 정한 까닭을 자신의 경험이나 생각과 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C20","difficulty":4,"kind":"essay","stem":"『국어』 233쪽 4번 (2)에서 정한 온라인 대화 예절 가운데 반드시 지켜야 한다고 생각하는 것 하나를 고르고, 그렇게 정한 까닭을 자신의 경험이나 생각과 이어 쓰세요.","answer_guide":{"answer":"예: 대화방에 상대를 초대할 때에는 상대의 의사를 확인한다. 숙제를 하거나 가족과 시간을 보내고 있는데 갑자기 알지도 못하는 대화방에 초대되어 답할 때까지 말을 걸어오면 내 시간을 빼앗기기 때문이다.","scoring_points":["예절 하나를 골랐는가","그 예절을 정한 까닭을 썼는가","까닭이 자신의 경험이나 생각과 이어져 있는가"]},"explanation":["다섯 가지 예절 가운데 하나를 골라요.","왜 꼭 지켜야 하는지 까닭을 붙여요.","내가 겪은 일과 이어 쓰면 설득력이 생겨요."],"asset":{"type":"passage","lines":["○ 대화의 주제와 관련 없는 말이나 그림말을 반복하여 사용하지 않는다.","○ 온라인 대화방에 상대를 초대할 때에는 상대의 의사를 확인한다.","○ 자료를 올리기 전에 사실이 아니거나 잘못된 내용은 없는지 확인한다.","○ 상대가 보이지 않아도 존중하며 대화한다.","○ 다른 사람의 사진이나 동영상은 허락 없이 공유하지 않는다."],"numbered":false,"title":"온라인 대화를 할 때 지켜야 할 예절 — 『국어』 233쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#9','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C65',4,'essay','teacher','광고 나의 “당신이 쓴 악성 댓글 ‘말’로 해 보시겠습니까?”라는 물음에 담긴 뜻을 쓰고, 이 광고와 비슷한 자신의 경험을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C65","difficulty":4,"kind":"essay","stem":"광고 나의 “당신이 쓴 악성 댓글 ‘말’로 해 보시겠습니까?”라는 물음에 담긴 뜻을 쓰고, 이 광고와 비슷한 자신의 경험을 쓰세요.","answer_guide":{"answer":"예: 얼굴을 마주 보거나 이름을 밝히면 하기 어려운 비난이나 욕설을 온라인에서는 쉽게 쓰고 있다는 것을 돌아보게 하려는 뜻이다. 게시판의 글에 비속어가 쓰인 댓글이 있어서 놀랐던 적이 있다.","scoring_points":["얼굴을 마주 보지 않고 이름을 밝히지 않는 상황과 이어 뜻을 썼는가","바르고 고운 말을 쓰자는 주제가 드러났는가","비슷한 경험을 썼는가"]},"explanation":["직접 말로 하면 어떨지 떠올려 봐요.","온라인에서는 쉽게 쓰는 말이 있어요.","내가 보거나 겪은 일과 이어요."],"asset":{"type":"passage","lines":["[광고 가] 윗글이 맑아야 아랫글이 맑다","[광고 나] 당신이 쓴 악성 댓글 ‘말’로 해 보시겠습니까?","         (마이크에 ‘bsf9****’처럼 일부를 가린 아이디가 적혀 있다.)","         생각이 달라서 비난 한 줄 / 스트레스 때문에 욕설 한 줄","         무심코 쓴 당신의 댓글 한 줄 입에 달기 부끄럽지 않으신가요?"],"numbered":false,"title":"공익 광고 두 편 — 『국어』 230쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L03_challenge#10','kor',4,2,'u5','L03','tb_g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C16',4,'essay','teacher','『국어』 231쪽 상황 가의 대화방에서 「내일 준비물이 뭐였지?」 하고 물은 친구에게 대화 예절을 지키며 보낼 답을 쓰고, 그렇게 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C16","difficulty":4,"kind":"essay","stem":"『국어』 231쪽 상황 가의 대화방에서 「내일 준비물이 뭐였지?」 하고 물은 친구에게 대화 예절을 지키며 보낼 답을 쓰고, 그렇게 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 「내일 준비물은 ○○이야. 같이 챙겨 가자.」 — 대화의 주제가 준비물이니, 주제와 관련 없는 그림말을 되풀이하지 않고 묻는 말에 알맞게 답했다.","scoring_points":["묻는 말에 알맞은 답을 썼는가","주제와 관련 없는 그림말을 되풀이하지 않았는가","그렇게 쓴 까닭을 썼는가"]},"explanation":["친구가 무엇을 물었는지 먼저 봐요.","주제에 맞게 답해요.","그림말만 되풀이하면 뜻이 통하지 않아요."],"asset":{"type":"passage","lines":["[상황 가] 한 친구가 “내일 준비물이 뭐였지?” 하고 물었다.","         대화방에는 그림말만 잇따라 올라온다."],"numbered":false,"title":"온라인 대화 상황 가 — 『국어』 231쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#1','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C26',1,'mc','auto','『국어』 234쪽 그림 가, 나, 다는 어떤 상황을 보여 주나요?',ARRAY['K4-2-u5-X13','K4-2-u5-X05']::text[],false,'{"seq":1,"concept":"K4-2-u5-C26","difficulty":1,"kind":"mc","stem":"『국어』 234쪽 그림 가, 나, 다는 어떤 상황을 보여 주나요?","options":[{"t":"온라인 대화가 직접 만나서 하는 대화보다 편리한 상황","correct":true},{"t":"온라인 대화를 하면 안 되는 상황","mis":"K4-2-u5-X13"},{"t":"반드시 손 편지를 써야 하는 상황","mis":"K4-2-u5-X05"}],"explanation":["전학 간 친구, 자료를 주고받는 숙제, 독감에 걸린 날이에요.","모두 직접 만나기 어려운 상황이에요.","이럴 때 온라인 대화가 편리해요."],"asset":{"type":"passage","lines":["[그림 가] 전학 간 친구와 대화하고 싶을 때 — “전학 간 학교는 어때?”","[그림 나] 친구들과 자료를 주고받으며 숙제하고 싶을 때","         — “이 동영상이 괜찮을지 친구들에게 물어봐야겠다.”","[그림 다] 독감에 걸렸을 때 — “독감은 좀 어떠니?”","         “이제 좀 괜찮아졌어요.”"],"numbered":false,"title":"온라인 대화가 편리한 상황 — 『국어』 234쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#2','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C26',1,'ox','auto','외국에 사는 친척과 연락할 때는 온라인 대화가 직접 만나서 하는 대화보다 편리해요.',ARRAY['K4-2-u5-X26']::text[],false,'{"seq":2,"concept":"K4-2-u5-C26","difficulty":1,"kind":"ox","stem":"외국에 사는 친척과 연락할 때는 온라인 대화가 직접 만나서 하는 대화보다 편리해요.","answer":"O","reason_options":[{"t":"멀리 떨어져 있어 만나서 이야기하기 어려울 때 온라인 대화로 쉽게 연락할 수 있기 때문에","correct":true},{"t":"온라인 대화는 언제나 직접 만나서 하는 대화보다 좋기 때문에","mis":"K4-2-u5-X26"}],"mis":"K4-2-u5-X26","explanation":["멀리 떨어져 있으면 만나서 이야기하기 어려워요.","『국어』 234쪽 예시 답안에 나온 상황이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#3','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C28',1,'match','auto','『국어』 235쪽 온라인 대화 계획표의 칸과 예시 답안을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u5-C28","difficulty":1,"kind":"match","stem":"『국어』 235쪽 온라인 대화 계획표의 칸과 예시 답안을 알맞게 이으세요.","pairs":[{"l":"대화 상대","r":"○○ 지역의 4학년 친구들"},{"l":"온라인 대화 방식","r":"누리 소통망"},{"l":"온라인 대화 주제","r":"우리 지역의 국가유산 소개하기"}],"mis":"K4-2-u5-X27","explanation":["누구와 이야기할지 정해요.","왜 온라인으로 하는지, 어떤 방식으로 할지 정해요.","무엇을 이야기할지 주제를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#4','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C31',1,'ox','auto','『국어활동』 71쪽 현지네 반 대화방에서 친구 3처럼 대화를 마치기 전에 말없이 나가도 괜찮아요.',ARRAY['K4-2-u5-X34']::text[],false,'{"seq":4,"concept":"K4-2-u5-C31","difficulty":1,"kind":"ox","stem":"『국어활동』 71쪽 현지네 반 대화방에서 친구 3처럼 대화를 마치기 전에 말없이 나가도 괜찮아요.","answer":"X","reason_options":[{"t":"불쾌감을 주는 말을 하지 않고, 대화를 마치고 나가기 전에 상대에게 양해를 구해야 하기 때문에","correct":true},{"t":"온라인 대화방은 언제든 마음대로 나가도 되기 때문에","mis":"K4-2-u5-X34"}],"mis":"K4-2-u5-X34","explanation":["친구 3은 “대충 하자니까. 너희끼리 가!” 하고 나갔어요.","남은 친구들은 기분이 상하고 대화가 멈춰요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"(간식 그림말만 잇따라 보냄)"},{"who":"친구 2","text":"도서관에 같이 갈 수 있는 사람 있어?"},{"who":"현지","text":"나랑 가자! 언제 갈까?"},{"who":"친구 4","text":"수업 끝나고 가자."},{"who":"친구 3","text":"대충 하자니까. 너희끼리 가!"},{"who":"알림","text":"친구 3 님이 나갔습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#5','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C28',2,'mc','auto','『국어』 235쪽 계획 예시에서 ‘○○ 지역의 4학년 친구들’과 온라인으로 대화하고 싶은 까닭은 무엇인가요?',ARRAY['K4-2-u5-X26','K4-2-u5-X03']::text[],false,'{"seq":5,"concept":"K4-2-u5-C28","difficulty":2,"kind":"mc","stem":"『국어』 235쪽 계획 예시에서 ‘○○ 지역의 4학년 친구들’과 온라인으로 대화하고 싶은 까닭은 무엇인가요?","options":[{"t":"다른 지역에 사는 친구들과는 만나서 대화하기 어렵기 때문","correct":true},{"t":"온라인 대화가 언제나 더 좋은 방법이기 때문","mis":"K4-2-u5-X26"},{"t":"만나서 대화하면 예절을 지켜야 하기 때문","mis":"K4-2-u5-X03"}],"explanation":["대화 상대는 다른 지역에 살아요.","만나서 이야기하기 어려워요.","그래서 온라인 대화를 골랐어요."],"asset":{"type":"passage","lines":["대화 상대 — ○○ 지역의 4학년 친구들","온라인으로 대화하고 싶은 까닭 — 다른 지역에 사는 친구들과는","        만나서 대화하기 어렵기 때문입니다.","온라인 대화 방식 — 누리 소통망","온라인 대화 주제 — 자기소개하기 · 우리 지역의 국가유산 소개하기 ·","        ○○ 지역의 국가유산에 대한 설명 듣기 · 지역에서 유명한 맛집 정보 공유하기"],"title":"온라인 대화 계획 (예시) — 『국어』 235쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#6','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C29',2,'blank','auto','『국어』 234쪽 그림 다에서 웃어른이 “독감은 좀 어떠니?” 하고 물었어요. 빈칸에 들어갈 알맞은 답은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#7','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C31',2,'mc','auto','『국어활동』 71쪽 현지네 반 대화방에서 친구 1에게 필요한 대화 예절은 무엇인가요?',ARRAY['K4-2-u5-X21','K4-2-u5-X20']::text[],false,'{"seq":7,"concept":"K4-2-u5-C31","difficulty":2,"kind":"mc","stem":"『국어활동』 71쪽 현지네 반 대화방에서 친구 1에게 필요한 대화 예절은 무엇인가요?","options":[{"t":"대화 주제와 관련 없는 말이나 그림말을 반복하여 사용하지 않는다","correct":true},{"t":"대화방에 초대할 때 상대의 뜻을 묻는다","mis":"K4-2-u5-X21"},{"t":"사진은 허락을 받고 올린다","mis":"K4-2-u5-X20"}],"explanation":["친구 1은 간식 그림말만 잇따라 보냈어요.","도서관에 갈 사람을 정하는 대화와 관련이 없어요.","주제와 관련 없는 그림말을 되풀이하지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"(간식 그림말만 잇따라 보냄)"},{"who":"친구 2","text":"도서관에 같이 갈 수 있는 사람 있어?"},{"who":"현지","text":"나랑 가자! 언제 갈까?"},{"who":"친구 4","text":"수업 끝나고 가자."},{"who":"친구 3","text":"대충 하자니까. 너희끼리 가!"},{"who":"알림","text":"친구 3 님이 나갔습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#8','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C33',2,'mc','auto','『국어』 237쪽 점검표로 스스로 확인했더니 「자료를 공유하기 전에 자료의 내용이 사실인지 확인했나요?」에 ●만 칠했어요. 다음에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X31','K4-2-u5-X32']::text[],false,'{"seq":8,"concept":"K4-2-u5-C33","difficulty":2,"kind":"mc","stem":"『국어』 237쪽 점검표로 스스로 확인했더니 「자료를 공유하기 전에 자료의 내용이 사실인지 확인했나요?」에 ●만 칠했어요. 다음에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"다음 온라인 대화에서는 자료를 올리기 전에 사실인지 먼저 확인하도록 고친다","correct":true},{"t":"점수를 높이려고 ●●●로 다시 칠해 둔다","mis":"K4-2-u5-X31"},{"t":"그 줄은 넘기고 잘한 줄만 본다","mis":"K4-2-u5-X32"}],"explanation":["●는 보통임이에요.","점검표는 고칠 점을 찾으려고 써요.","찾은 점은 다음 대화에서 고쳐요."],"asset":{"type":"passage","lines":["대화의 주제와 관련 없는 말이나 그림말을 반복해서 사용하지 않았나요? ○○○","상대가 보이지 않는 상황에서도 예의를 갖추어 대화했나요? ○○○","자료를 공유하기 전에 자료의 내용이 사실인지 확인했나요? ○○○","사진이나 동영상 같은 자료를 공유하기 전에 상대의 허락을 구했나요? ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"예절을 지키며 온라인 대화를 했는지 스스로 확인하기 — 『국어』 237쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#9','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C30',2,'ox','auto','온라인 대화 상대를 정할 때에는 신뢰가 가지 않는 사람과 접촉하지 않도록 조심해야 해요.',ARRAY['K4-2-u5-X29']::text[],false,'{"seq":9,"concept":"K4-2-u5-C30","difficulty":2,"kind":"ox","stem":"온라인 대화 상대를 정할 때에는 신뢰가 가지 않는 사람과 접촉하지 않도록 조심해야 해요.","answer":"O","reason_options":[{"t":"대화 상대는 다양할 수 있지만 믿을 수 없는 사람과의 접촉은 나를 지키기 위해 피해야 하기 때문에","correct":true},{"t":"먼저 말을 걸어온 사람에게는 예의를 지켜 내 정보를 알려 주어야 하기 때문에","mis":"K4-2-u5-X29"}],"mis":"K4-2-u5-X29","explanation":["대화 상대는 다른 반, 다른 지역, 다른 나라 사람까지 다양할 수 있어요.","그러나 믿을 수 없는 사람과는 대화하지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_basic#10','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C26',3,'mc','auto','『국어』 234~235쪽을 공부하고 나서 바르게 정리한 것은 무엇인가요?',ARRAY['K4-2-u5-X26','K4-2-u5-X14']::text[],false,'{"seq":10,"concept":"K4-2-u5-C26","difficulty":3,"kind":"mc","stem":"『국어』 234~235쪽을 공부하고 나서 바르게 정리한 것은 무엇인가요?","options":[{"t":"온라인 대화가 직접 만나서 하는 대화보다 좋다는 것이 아니라, 상황을 생각해 가장 알맞은 대화 방법을 고른다","correct":true},{"t":"온라인 대화가 언제나 직접 만나서 하는 대화보다 편리하다","mis":"K4-2-u5-X26"},{"t":"온라인 대화는 편리하니 예절을 덜 지켜도 된다","mis":"K4-2-u5-X14"},{"t":"직접 만나서 하는 대화는 이제 필요 없다","mis":"K4-2-u5-X14"}],"explanation":["온라인 대화가 편리한 상황이 있어요.","그렇다고 언제나 더 좋은 것은 아니에요.","의사소통 상황에 알맞은 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#1','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C28',2,'sa','auto','온라인 대화 계획을 세울 때 「누구와」 이야기할지 정하는 칸의 이름은 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C28","difficulty":2,"kind":"sa","stem":"온라인 대화 계획을 세울 때 「누구와」 이야기할지 정하는 칸의 이름은 무엇인가요? 네 글자로 쓰세요.","answer":["대화 상대","대화상대"],"explanation":["『국어』 235쪽 계획표의 첫 칸이에요.","예시에서는 ‘○○ 지역의 4학년 친구들’이라고 썼어요.","답은 ‘대화 상대’예요."],"mis":"K4-2-u5-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#2','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C34',2,'mc','auto','담임 선생님이 “온라인 대화 예절에 대한 나의 다짐을 댓글로 남겨 주세요.”라고 했어요. 시우처럼 공손하게 쓴 다짐 댓글은 무엇인가요?',ARRAY['K4-2-u5-X28','K4-2-u5-X33']::text[],false,'{"seq":2,"concept":"K4-2-u5-C34","difficulty":2,"kind":"mc","stem":"담임 선생님이 “온라인 대화 예절에 대한 나의 다짐을 댓글로 남겨 주세요.”라고 했어요. 시우처럼 공손하게 쓴 다짐 댓글은 무엇인가요?","options":[{"t":"“저는 항상 사실 여부를 확인하고 글을 쓸 거예요.”","correct":true},{"t":"“그림말 안 씀. ㅂㅇ.”","mis":"K4-2-u5-X28"},{"t":"“다짐은 많을수록 좋으니 열 가지를 쓸게요.”","mis":"K4-2-u5-X33"}],"explanation":["『국어』 237쪽 「더 나아가기」 활동이에요.","선생님께 다는 댓글이니 공손한 표현을 써요.","배운 예절 가운데 지킬 것을 분명하게 써요."],"asset":{"type":"speech","turns":[{"who":"담임 선생님","text":"온라인 대화 예절에 대한 나의 다짐을 댓글로 남겨 주세요."},{"who":"시우","text":"저는 온라인 대화를 할 때 공손한 표현을 사용할 거예요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#3','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C31',3,'mc','auto','『국어』 236쪽에서 예절을 지키며 온라인 대화를 해 보고 소감을 나누었어요. 이 활동에서 가장 중요하게 살필 것은 무엇인가요?',ARRAY['K4-2-u5-X62','K4-2-u5-X23']::text[],false,'{"seq":3,"concept":"K4-2-u5-C31","difficulty":3,"kind":"mc","stem":"『국어』 236쪽에서 예절을 지키며 온라인 대화를 해 보고 소감을 나누었어요. 이 활동에서 가장 중요하게 살필 것은 무엇인가요?","options":[{"t":"어떤 내용을 주고받았는지보다 예절을 지키며 대화에 참여했는지","correct":true},{"t":"얼마나 재미있는 내용을 많이 주고받았는지","mis":"K4-2-u5-X62"},{"t":"누가 가장 빨리 답했는지","mis":"K4-2-u5-X23"}],"explanation":["온라인 대화로 소통한 내용보다 예절이 중심이에요.","친구들은 그림말, 칭찬 댓글, 인사를 주고받은 소감을 말했어요.","예절을 지키며 참여했는지 돌아봐요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"누리 소통망에서 대화할 때 그림말을 사용해서 내 마음을 효과적으로 전달할 수 있었어."},{"who":"친구 2","text":"내가 쓴 글을 칭찬하는 댓글을 읽고 기분이 좋았어."},{"who":"친구 3","text":"영상 통화를 할 때 상대와 서로 인사를 주고받으며 기분 좋게 대화를 할 수 있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#4','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C29',3,'mc','auto','『국어』 234쪽 예시처럼 회사에 계신 부모님께 여쭈어볼 것이 있어 온라인으로 메시지를 보내요. 알맞은 메시지는 무엇인가요?',ARRAY['K4-2-u5-X28','K4-2-u5-X23']::text[],false,'{"seq":4,"concept":"K4-2-u5-C29","difficulty":3,"kind":"mc","stem":"『국어』 234쪽 예시처럼 회사에 계신 부모님께 여쭈어볼 것이 있어 온라인으로 메시지를 보내요. 알맞은 메시지는 무엇인가요?","options":[{"t":"“아버지, 일하시는 중에 죄송해요. 오늘 몇 시에 오시는지 여쭈어봐도 될까요?”","correct":true},{"t":"“몇 시에 와?”","mis":"K4-2-u5-X28"},{"t":"“빨리 답해. 몇 시?”","mis":"K4-2-u5-X23"}],"explanation":["받는 사람이 웃어른이에요.","화면으로 보내도 높임 표현을 써요.","상대의 사정을 헤아리는 말도 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#5','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C32',3,'error','auto','온라인 대화에서 상대가 내 말을 알아듣지 못했을 때를 두고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?',ARRAY['K4-2-u5-X22','K4-2-u5-X61']::text[],false,'{"seq":5,"concept":"K4-2-u5-C32","difficulty":3,"kind":"error","stem":"온라인 대화에서 상대가 내 말을 알아듣지 못했을 때를 두고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“못 알아들은 건 상대 잘못이니 그것도 모르냐고 하면 돼.”","correct":true,"mis_target":"K4-2-u5-X22"},{"t":"“무엇을 말하려는지 풀어서 다시 말해야 해.”","mis":"K4-2-u5-X22"},{"t":"“같은 그림말만 한 번 더 보내면 오해가 더 커질 수 있어.”","mis":"K4-2-u5-X61"}],"explanation":["상대는 얼굴과 표정을 볼 수 없어요.","그래서 정확하고 예의 바른 표현이 중요해요.","알아들을 수 있게 풀어서 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#6','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C31',3,'mc','auto','온라인 대화를 하고 관찰 기록표로 동료 평가를 해요. 「참여 태도」에서 살피는 것이 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":6,"concept":"K4-2-u5-C31","difficulty":3,"kind":"mc","stem":"온라인 대화를 하고 관찰 기록표로 동료 평가를 해요. 「참여 태도」에서 살피는 것이 아닌 것은 무엇인가요?","options":[{"t":"상대를 고려하여 매체를 선택했는가?","correct":true},{"t":"상대의 허락 없이 대화를 끊지 않았는가?","mis":"K4-2-u5-X27"},{"t":"바른 말, 고운 말을 썼는가?","mis":"K4-2-u5-X27"}],"explanation":["매체를 고르는 일은 「계획하기」에서 살펴요.","대화를 끊지 않았는지, 바른 말을 썼는지는 「참여 태도」예요.","세 칸이 무엇을 살피는지 가려요."],"asset":{"type":"passage","lines":["계획하기 — 상대를 고려하여 매체를 선택했는가? · 좋은 점과 문제점을 고려했는가?","온라인 대화 하기 — 상대가 흥미를 느낄 만한 내용인가? ·","        주제와 관련 있는 내용을 이야기했는가? · 사실과 다른 내용을 말하지 않았는가?","참여 태도 — 주제와 관련 없는 말이나 그림말을 반복하지 않았는가? ·","        불쾌감을 주지 않았는가? · 바른 말, 고운 말을 썼는가? ·","        상대의 허락 없이 대화를 끊지 않았는가? · 적극적으로 참여했는가?","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"온라인 대화 관찰 기록표 (평가 자료 1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#7','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C33',3,'mc','auto','온라인 대화를 자기 평가와 동료 평가로 살펴본 뒤에 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X31','K4-2-u5-X32']::text[],false,'{"seq":7,"concept":"K4-2-u5-C33","difficulty":3,"kind":"mc","stem":"온라인 대화를 자기 평가와 동료 평가로 살펴본 뒤에 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"평가 결과를 바탕으로 고칠 점을 찾아 이야기하고 다음 대화에서 고친다","correct":true},{"t":"잘한 것처럼 보이게 모두 ●●●로 고쳐 적는다","mis":"K4-2-u5-X31"},{"t":"평가는 끝났으니 다시 보지 않는다","mis":"K4-2-u5-X32"}],"explanation":["평가는 점수를 자랑하려고 하는 것이 아니에요.","고칠 점을 찾는 것이 목적이에요.","찾은 점을 다음 대화에서 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#8','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C28',4,'essay','teacher','『국어』 235쪽처럼 온라인 대화 계획을 세워 보세요. 대화 상대, 온라인으로 대화하고 싶은 까닭, 온라인 대화 방식, 온라인 대화 주제를 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C28","difficulty":4,"kind":"essay","stem":"『국어』 235쪽처럼 온라인 대화 계획을 세워 보세요. 대화 상대, 온라인으로 대화하고 싶은 까닭, 온라인 대화 방식, 온라인 대화 주제를 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 대화 상대 — 나와 같은 책을 읽은 다른 반 친구들 / 까닭 — 쉬는 시간이 서로 달라 만나서 이야기하기 어렵기 때문이다 / 방식 — 온라인 게시판 / 주제 — 책에서 가장 인상 깊은 장면 나누기","scoring_points":["대화 상대를 썼는가","온라인으로 대화하고 싶은 까닭을 썼는가","대화 방식과 주제를 썼는가"]},"explanation":["누구와 이야기하고 싶은지 떠올려요.","왜 온라인이 알맞은지 까닭을 써요.","방식과 주제까지 정하면 계획이 완성돼요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"외국에 사는 친구와 함께 음식 문화에 대하여 이야기하고 싶어."},{"who":"친구 2","text":"아리랑을 주제로 하는 지역 축제에 대해 알고 싶어. 지역 축제를 잘 알고 있는 사람이 알려 줬으면 좋겠어."},{"who":"친구 3","text":"친구들과 잘하는 것을 동영상으로 촬영해서 온라인 장기자랑을 해 보고 싶어."},{"who":"친구 4","text":"나와 같은 책을 읽은 친구들과 함께 의견을 나누고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#9','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C26',4,'essay','teacher','『국어』 234쪽 그림 나처럼 친구들과 자료를 주고받으며 숙제를 하려고 해요. 이 상황에서 온라인 대화가 편리한 까닭과, 동영상을 올리기 전에 지켜야 할 예절을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C26","difficulty":4,"kind":"essay","stem":"『국어』 234쪽 그림 나처럼 친구들과 자료를 주고받으며 숙제를 하려고 해요. 이 상황에서 온라인 대화가 편리한 까닭과, 동영상을 올리기 전에 지켜야 할 예절을 쓰세요.","answer_guide":{"answer":"예: 만나지 않아도 자료를 바로 주고받으며 의견을 나눌 수 있어 편리하다. 동영상에 다른 사람이 나오면 먼저 허락을 받고, 내용이 사실인지 확인한 뒤 올린다.","scoring_points":["온라인 대화가 편리한 까닭을 썼는가","허락을 받는 예절을 썼는가","사실을 확인하는 예절을 썼는가"]},"explanation":["직접 만나기 어려운 점을 떠올려요.","사진이나 동영상은 허락 없이 올리지 않아요.","올리기 전에 사실인지 확인해요."],"asset":{"type":"passage","lines":["[그림 가] 전학 간 친구와 대화하고 싶을 때 — “전학 간 학교는 어때?”","[그림 나] 친구들과 자료를 주고받으며 숙제하고 싶을 때","         — “이 동영상이 괜찮을지 친구들에게 물어봐야겠다.”","[그림 다] 독감에 걸렸을 때 — “독감은 좀 어떠니?”","         “이제 좀 괜찮아졌어요.”"],"numbered":false,"title":"온라인 대화가 편리한 상황 — 『국어』 234쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L05_challenge#10','kor',4,2,'u5','L05','tb_g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C31',4,'essay','teacher','『국어활동』 71쪽 현지네 반 대화방에서 친구 1과 친구 3이 지키지 않은 대화 예절을 각각 쓰고, 친구 3의 말을 예절에 맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C31","difficulty":4,"kind":"essay","stem":"『국어활동』 71쪽 현지네 반 대화방에서 친구 1과 친구 3이 지키지 않은 대화 예절을 각각 쓰고, 친구 3의 말을 예절에 맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 친구 1 — 대화 주제와 관련 없는 그림말을 반복하여 사용했다. 친구 3 — 불쾌감을 주는 말을 하고 양해를 구하지 않고 나갔다. 고친 말 — 「내일 바쁜 일이 있는데 인터넷으로 찾아봐도 될까?」","scoring_points":["친구 1이 지키지 않은 예절을 썼는가","친구 3이 지키지 않은 예절을 썼는가","친구 3의 말을 예절에 맞게 고쳐 썼는가"]},"explanation":["친구 1은 그림말만 보냈어요.","친구 3은 기분 상하는 말을 하고 나갔어요.","사정을 말하고 양해를 구하는 말로 고쳐요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"(간식 그림말만 잇따라 보냄)"},{"who":"친구 2","text":"도서관에 같이 갈 수 있는 사람 있어?"},{"who":"현지","text":"나랑 가자! 언제 갈까?"},{"who":"친구 4","text":"수업 끝나고 가자."},{"who":"친구 3","text":"대충 하자니까. 너희끼리 가!"},{"who":"알림","text":"친구 3 님이 나갔습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#1','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C36',1,'mc','auto','『국어』 238쪽 2번에서 친구들이 편지로 마음을 전하면 좋은 점을 말했어요. 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X36','K4-2-u5-X03','K4-2-u5-X35']::text[],false,'{"seq":1,"concept":"K4-2-u5-C36","difficulty":1,"kind":"mc","stem":"『국어』 238쪽 2번에서 친구들이 편지로 마음을 전하면 좋은 점을 말했어요. 알맞은 것은 무엇인가요?","options":[{"t":"직접 말할 때보다 생각할 시간이 충분하고 고쳐 쓸 수도 있어서 진심을 더 잘 전할 수 있다","correct":true},{"t":"편지는 언제나 가장 빠르게 닿는다","mis":"K4-2-u5-X36"},{"t":"편지에는 예절을 지키지 않아도 된다","mis":"K4-2-u5-X03"},{"t":"편지는 옛날 방법이라 지금은 쓸모가 없다","mis":"K4-2-u5-X35"}],"explanation":["친구 4가 생각할 시간과 고쳐 쓰기를 말했어요.","친구 2는 말로 하기 어려운 사과를 편지로 전할 수 있다고 했어요.","편지는 정성을 담아 진심을 전하기 좋아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"편지를 써서 상대에게 내 마음을 전하면 어떤 점이 좋을까?"},{"who":"친구 2","text":"친구에게 먼저 사과하고 싶은데 말로 하기 어려울 때 편지로 미안한 마음을 전달할 수 있어."},{"who":"친구 3","text":"마음을 담은 편지를 주고받으면 상대와 친해지고 더 사이좋게 지낼 수 있어."},{"who":"친구 4","text":"감사, 위로, 축하, 응원과 같은 마음을 직접 편지로 써서 전하면 생각할 시간이 충분하고 고쳐 쓸 수도 있어서 진심을 더 잘 전할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#2','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C61',1,'mc','auto','석원이의 편지를 읽을 사람은 누구인가요?',ARRAY['K4-2-u5-X37']::text[],false,'{"seq":2,"concept":"K4-2-u5-C61","difficulty":1,"kind":"mc","stem":"석원이의 편지를 읽을 사람은 누구인가요?","options":[{"t":"석원이의 할머니","correct":true},{"t":"석원이의 친구","mis":"K4-2-u5-X37"},{"t":"석원이의 선생님","mis":"K4-2-u5-X37"}],"explanation":["편지 맨 처음에 받는 사람을 써요.","“사랑하는 할머니께”라고 썼어요.","읽을 사람은 석원이의 할머니예요."],"asset":{"type":"passage","lines":["사랑하는 할머니께","할머니, 안녕하세요? 저 석원이예요. 건강하게 잘 지내고 계시지요?","할머니, 고구마를 보내 주셔서 고맙습니다.","(간추림) 우수상을 받은 기쁜 소식을 전하고, 다음 달 생신 때 찾아뵙겠다고 했다.","또 편지 보낼게요. 안녕히 계세요.","20○○년 ○○월 ○○일","손자 지석원 올림","추신: 참, 할머니, 텃밭 일 무리하지 마세요. 편찮으시면 안 돼요."],"title":"석원이의 편지 — 『국어』 239쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#3','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C38',1,'match','auto','석원이의 편지에서 줄과 편지의 짜임을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u5-C38","difficulty":1,"kind":"match","stem":"석원이의 편지에서 줄과 편지의 짜임을 알맞게 이으세요.","pairs":[{"l":"사랑하는 할머니께","r":"받는 사람"},{"l":"할머니, 안녕하세요? … 건강하게 잘 지내고 계시지요?","r":"첫인사"},{"l":"또 편지 보낼게요. 안녕히 계세요.","r":"끝인사"},{"l":"손자 지석원 올림","r":"쓴 사람"}],"mis":"K4-2-u5-X38","explanation":["받는 사람 → 첫인사 → 전하고 싶은 말 → 끝인사 → 쓴 날짜 → 쓴 사람 차례예요.","첫인사로 받을 사람의 안부를 물어요.","쓴 사람 이름 뒤에는 ‘올림’ 같은 말을 써요."],"asset":{"type":"passage","lines":["사랑하는 할머니께","할머니, 안녕하세요? 저 석원이예요. 건강하게 잘 지내고 계시지요?","할머니, 고구마를 보내 주셔서 고맙습니다.","(간추림) 우수상을 받은 기쁜 소식을 전하고, 다음 달 생신 때 찾아뵙겠다고 했다.","또 편지 보낼게요. 안녕히 계세요.","20○○년 ○○월 ○○일","손자 지석원 올림","추신: 참, 할머니, 텃밭 일 무리하지 마세요. 편찮으시면 안 돼요."],"title":"석원이의 편지 — 『국어』 239쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#4','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C39',1,'ox','auto','석원이의 편지 끝에 있는 ‘추신’은 모든 편지에 꼭 써야 하는 부분이에요.',ARRAY['K4-2-u5-X39']::text[],false,'{"seq":4,"concept":"K4-2-u5-C39","difficulty":1,"kind":"ox","stem":"석원이의 편지 끝에 있는 ‘추신’은 모든 편지에 꼭 써야 하는 부분이에요.","answer":"X","reason_options":[{"t":"편지를 다 썼지만 보태고 싶은 내용이 있을 때에만 덧붙이기 때문에","correct":true},{"t":"편지의 짜임에는 언제나 추신이 들어가야 하기 때문에","mis":"K4-2-u5-X39"}],"mis":"K4-2-u5-X39","explanation":["석원이는 텃밭 일을 무리하지 마시라는 말을 보탰어요.","보태고 싶은 내용이 있을 때 ‘추신’이라 쓰고 덧붙여요.","그래서 X예요."],"asset":{"type":"passage","lines":["사랑하는 할머니께","할머니, 안녕하세요? 저 석원이예요. 건강하게 잘 지내고 계시지요?","할머니, 고구마를 보내 주셔서 고맙습니다.","(간추림) 우수상을 받은 기쁜 소식을 전하고, 다음 달 생신 때 찾아뵙겠다고 했다.","또 편지 보낼게요. 안녕히 계세요.","20○○년 ○○월 ○○일","손자 지석원 올림","추신: 참, 할머니, 텃밭 일 무리하지 마세요. 편찮으시면 안 돼요."],"title":"석원이의 편지 — 『국어』 239쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#5','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C61',2,'mc','auto','석원이는 할머니께 어떤 마음을 전하고 있나요?',ARRAY['K4-2-u5-X37','K4-2-u5-X63','K4-2-u5-X46']::text[],false,'{"seq":5,"concept":"K4-2-u5-C61","difficulty":2,"kind":"mc","stem":"석원이는 할머니께 어떤 마음을 전하고 있나요?","options":[{"t":"고구마를 보내 주신 데 대한 감사와, 우수상을 받은 기쁨","correct":true},{"t":"고구마가 맛이 없어 서운한 마음","mis":"K4-2-u5-X37"},{"t":"감사하는 마음 한 가지뿐","mis":"K4-2-u5-X63"},{"t":"할머니께 사과하는 마음","mis":"K4-2-u5-X46"}],"explanation":["“고구마를 보내 주셔서 고맙습니다.”에 감사가 드러나요.","우수상 소식에는 기쁨이 담겨 있어요.","편지에 담긴 마음을 한 가지로만 정하지 않아요."],"asset":{"type":"passage","lines":["할머니, 고구마를 보내 주셔서 고맙습니다.","(간추림) 할머니께서 텃밭에서 정성 들여 직접 키우셔서 고구마가 더 맛있다고 했다.","그리고 기쁜 소식이 있어요. 제가 독후감 쓰기 대회에서 우수상을 받았어요!","(간추림) 늘 아끼고 사랑해 주시는 할머니께 마음 깊이 감사하다고 했다.","(간추림) 할머니가 많이 보고 싶어서 다음 달 생신 때 찾아뵙겠다고 했다."],"title":"석원이의 편지 가운데 「전하고 싶은 말」 — 『국어』 239쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#6','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C40',2,'mc','auto','석원이의 편지에서 ‘할머니께’, ‘계시지요’, ‘보내 주셔서’, ‘생신’, ‘찾아뵐게요’, ‘올림’처럼 파란색으로 쓴 낱말은 왜 그렇게 썼나요?',ARRAY['K4-2-u5-X42','K4-2-u5-X48','K4-2-u5-X41']::text[],false,'{"seq":6,"concept":"K4-2-u5-C40","difficulty":2,"kind":"mc","stem":"석원이의 편지에서 ‘할머니께’, ‘계시지요’, ‘보내 주셔서’, ‘생신’, ‘찾아뵐게요’, ‘올림’처럼 파란색으로 쓴 낱말은 왜 그렇게 썼나요?","options":[{"t":"편지를 읽는 이가 윗사람이어서 높임 표현을 썼다","correct":true},{"t":"글씨를 예쁘게 꾸미려고 썼다","mis":"K4-2-u5-X42"},{"t":"편지가 길어 보이게 하려고 썼다","mis":"K4-2-u5-X48"},{"t":"할머니를 사랑하는 마음이 커서 높였다","mis":"K4-2-u5-X41"}],"explanation":["편지를 읽을 사람은 할머니예요.","할머니는 윗사람이라 높임 표현을 써요.","높임은 마음의 크기가 아니라 상대에 맞추는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#7','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C42',2,'mc','auto','할머니께 쓴 다른 편지예요. 읽는 사람에 대한 높임 표현이 잘못된 부분을 바르게 고른 것은 무엇인가요?',ARRAY['K4-2-u5-X40','K4-2-u5-X41']::text[],false,'{"seq":7,"concept":"K4-2-u5-C42","difficulty":2,"kind":"mc","stem":"할머니께 쓴 다른 편지예요. 읽는 사람에 대한 높임 표현이 잘못된 부분을 바르게 고른 것은 무엇인가요?","options":[{"t":"할머니에게 · 생일 · 집 · 씀","correct":true},{"t":"할머니, 사랑해요 · 고맙습니다","mis":"K4-2-u5-X40"},{"t":"석원이예요 · 썼어요","mis":"K4-2-u5-X41"}],"explanation":["웃어른께는 ‘에게’ 대신 ‘께’를 써요.","‘생일’은 ‘생신’, ‘집’은 높이는 말로 바꾸어요.","쓴 사람 이름 뒤에는 ‘씀’ 대신 ‘올림’이나 ‘드림’을 써요."],"asset":{"type":"passage","lines":["할머니에게","할머니, 저 석원이예요. 할머니에게 감사의 마음을 전하고 싶어서","이렇게 편지를 썼어요. 제 마음 아시죠? 항상 고맙습니다.","다음 주면 할머니의 생일이네요. 가족과 할머니 집으로 갈게요.","할머니, 사랑해요.","지석원 씀"],"title":"고쳐 쓸 곳이 있는 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#8','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C38',2,'blank','auto','『국어』 241쪽 6번에서 편지 쓰는 방법을 정리했어요. ㉠에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X42']::text[],false,'{"seq":8,"concept":"K4-2-u5-C38","difficulty":2,"kind":"blank","stem":"『국어』 241쪽 6번에서 편지 쓰는 방법을 정리했어요. ㉠에 알맞은 말은 무엇인가요?","options":[{"t":"짜임","correct":true},{"t":"길이","mis":"K4-2-u5-X48"},{"t":"글씨","mis":"K4-2-u5-X42"}],"explanation":["편지에는 받는 사람부터 쓴 사람까지 차례가 있어요.","그 차례를 편지의 짜임이라고 해요.","편지의 짜임에 맞게 써요."],"asset":{"type":"passage","lines":["○ 편지의 (  ㉠  )에 맞게 쓴다.","○ 읽는 이의 마음과 반응을 생각하며 쓴다.","○ 읽는 이에 따라 (  ㉡  )을/를 바르게 쓴다.","○ 전하고자 하는 마음이 잘 드러나도록 내용을 구체적으로 쓴다."],"numbered":false,"title":"읽는 이를 생각하며 마음을 전하는 편지 쓰는 방법 — 『국어』 241쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#9','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C35',2,'ox','auto','「편지의 역사」에 따르면 종이가 발명되기 전에는 편지를 쓸 수 없었어요.',ARRAY['K4-2-u5-X35']::text[],false,'{"seq":9,"concept":"K4-2-u5-C35","difficulty":2,"kind":"ox","stem":"「편지의 역사」에 따르면 종이가 발명되기 전에는 편지를 쓸 수 없었어요.","answer":"X","reason_options":[{"t":"종이가 발명되기 전에도 점토판, 파피루스, 양피지, 목간 같은 데에 편지를 썼기 때문에","correct":true},{"t":"편지는 종이가 생긴 뒤에 처음 생겼기 때문에","mis":"K4-2-u5-X35"}],"mis":"K4-2-u5-X35","explanation":["편지는 아주 오래전부터 쓰였어요.","종이가 발명되면서 편지의 이용이 크게 늘었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["(간추림) 점토판, 파피루스, 양피지, 나무를 이용한 목간 등에 편지를 쓰다가","(간추림) 종이가 발명되면서 편지의 이용이 크게 늘었다.","(간추림) 1884년 우정총국이 설립되면서 우리나라 최초의 우체통이 설치되었다.","(간추림) 전화기와 전자 우편이 생긴 뒤 편지를 쓰는 일이 점차 줄었다.","(간추림) 오늘날 편지는 다른 통신 수단이 하지 못하는 진심을 전하는 역할을 한다."],"title":"「편지의 역사」 간추림 — 『국어활동』 스스로 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_basic#10','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C43',3,'mc','auto','『국어』 241쪽 6번의 「읽는 이의 마음과 반응을 생각하며 쓴다」를 바르게 이해한 것은 무엇인가요?',ARRAY['K4-2-u5-X43','K4-2-u5-X44']::text[],false,'{"seq":10,"concept":"K4-2-u5-C43","difficulty":3,"kind":"mc","stem":"『국어』 241쪽 6번의 「읽는 이의 마음과 반응을 생각하며 쓴다」를 바르게 이해한 것은 무엇인가요?","options":[{"t":"전하려는 내 마음은 솔직하게 쓰되, 읽는 사람이 어떻게 받아들일지 생각하며 표현을 고른다","correct":true},{"t":"읽는 사람이 좋아할 만한 말만 골라 쓴다","mis":"K4-2-u5-X43"},{"t":"떠오르는 대로 바로 쓴다","mis":"K4-2-u5-X44"},{"t":"읽는 사람이 서운할까 봐 아무 말도 쓰지 않는다","mis":"K4-2-u5-X44"}],"explanation":["내 마음은 솔직하게 전해요.","읽는 사람의 입장에서 어떻게 받아들일지 생각해요.","그래서 표현을 알맞게 골라요."],"asset":{"type":"passage","lines":["○ 편지의 (  ㉠  )에 맞게 쓴다.","○ 읽는 이의 마음과 반응을 생각하며 쓴다.","○ 읽는 이에 따라 (  ㉡  )을/를 바르게 쓴다.","○ 전하고자 하는 마음이 잘 드러나도록 내용을 구체적으로 쓴다."],"numbered":false,"title":"읽는 이를 생각하며 마음을 전하는 편지 쓰는 방법 — 『국어』 241쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#1','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C40',2,'sa','auto','『국어』 241쪽 6번이에요. 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#2','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C62',2,'mc','auto','정조가 숙모에게 보낸 한글 편지를 오늘날 표현으로 풀었어요. 정조가 숙모에게 전한 마음으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X37','K4-2-u5-X46']::text[],false,'{"seq":2,"concept":"K4-2-u5-C62","difficulty":2,"kind":"mc","stem":"정조가 숙모에게 보낸 한글 편지를 오늘날 표현으로 풀었어요. 정조가 숙모에게 전한 마음으로 알맞은 것은 무엇인가요?","options":[{"t":"오래 뵙지 못해 그리웠는데 편지를 받아 든든하고 반가운 마음","correct":true},{"t":"숙모에게 서운하고 화가 난 마음","mis":"K4-2-u5-X37"},{"t":"숙모의 잘못을 꾸짖는 마음","mis":"K4-2-u5-X46"}],"explanation":["“서릿바람에 기후 평안하신지” 하고 안부를 여쭈었어요.","뵌 지 오래되어 그리웠다고 했어요.","편지를 받아 든든하고 반가운 마음을 전했어요."],"asset":{"type":"passage","lines":["숙모님 앞","서릿바람에 기후 평안하신지 문안 알고자 합니다.","(간추림) 뵌 지 오래되어 섭섭하고 그리웠는데 어제 편지를 보니 든든하고 반갑다고 했다.","원손"],"title":"정조가 숙모에게 보낸 한글 편지 (오늘날 표현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#3','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C41',3,'error','auto','석원이가 친구에게 편지를 쓴다면 어떻게 쓸지 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?',ARRAY['K4-2-u5-X41']::text[],false,'{"seq":3,"concept":"K4-2-u5-C41","difficulty":3,"kind":"error","stem":"석원이가 친구에게 편지를 쓴다면 어떻게 쓸지 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“친구에게도 ‘○○께’와 ‘석원 올림’을 써야 마음이 크게 전해져.”","correct":true,"mis_target":"K4-2-u5-X41"},{"t":"“받는 사람은 ‘○○에게’처럼 쓰면 돼.”","mis":"K4-2-u5-X41"},{"t":"“쓴 사람 이름 뒤에는 ‘씀’을 쓸 수 있어.”","mis":"K4-2-u5-X41"}],"explanation":["높임 표현은 읽는 이에 따라 달라요.","친구에게는 ‘에게’, ‘씀’처럼 써요.","높임을 쓰지 않는다고 마음이 작은 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#4','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C40',3,'mc','auto','웃어른께 드리는 편지의 문장을 높임 표현에 맞게 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u5-X64']::text[],false,'{"seq":4,"concept":"K4-2-u5-C40","difficulty":3,"kind":"mc","stem":"웃어른께 드리는 편지의 문장을 높임 표현에 맞게 바르게 고친 것은 무엇인가요?","options":[{"t":"다음 주면 할머니의 생일이네요. → 다음 주면 할머니의 생신이네요.","correct":true},{"t":"할머니 집으로 갈게요. → 할머니 집으로 갈게.","mis":"K4-2-u5-X64"},{"t":"할머니에게 → 할머니한테","mis":"K4-2-u5-X64"}],"explanation":["웃어른께는 높임 낱말을 써요.","‘생일’은 ‘생신’으로 높여요.","‘에게’는 ‘께’로, 문장 끝도 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#5','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C61',3,'ox','auto','석원이의 편지에 담긴 마음은 감사 한 가지뿐이에요.',ARRAY['K4-2-u5-X63']::text[],false,'{"seq":5,"concept":"K4-2-u5-C61","difficulty":3,"kind":"ox","stem":"석원이의 편지에 담긴 마음은 감사 한 가지뿐이에요.","answer":"X","reason_options":[{"t":"고구마를 보내 주신 데 대한 감사와 함께 우수상을 받은 기쁨, 할머니가 보고 싶은 마음도 담겨 있기 때문에","correct":true},{"t":"편지 한 통에는 마음을 한 가지만 담아야 하기 때문에","mis":"K4-2-u5-X63"}],"mis":"K4-2-u5-X63","explanation":["글쓴이가 전하려는 마음은 여러 가지일 수 있어요.","감사와 기쁨, 보고 싶은 마음이 함께 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["할머니, 고구마를 보내 주셔서 고맙습니다.","(간추림) 할머니께서 텃밭에서 정성 들여 직접 키우셔서 고구마가 더 맛있다고 했다.","그리고 기쁜 소식이 있어요. 제가 독후감 쓰기 대회에서 우수상을 받았어요!","(간추림) 늘 아끼고 사랑해 주시는 할머니께 마음 깊이 감사하다고 했다.","(간추림) 할머니가 많이 보고 싶어서 다음 달 생신 때 찾아뵙겠다고 했다."],"title":"석원이의 편지 가운데 「전하고 싶은 말」 — 『국어』 239쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#6','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C42',3,'mc','auto','고쳐 쓸 곳이 있는 편지를 석원이의 편지(『국어』 239쪽)와 견주었어요. 고쳐 쓸 곳이 있는 편지에서 빠지거나 부족한 것을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X42','K4-2-u5-X39']::text[],false,'{"seq":6,"concept":"K4-2-u5-C42","difficulty":3,"kind":"mc","stem":"고쳐 쓸 곳이 있는 편지를 석원이의 편지(『국어』 239쪽)와 견주었어요. 고쳐 쓸 곳이 있는 편지에서 빠지거나 부족한 것을 바르게 말한 것은 무엇인가요?","options":[{"t":"고마운 마음을 느낀 일이 무엇인지 알 수 없고, 첫인사와 끝인사, 쓴 날짜가 없다","correct":true},{"t":"편지가 짧고 글씨가 작다","mis":"K4-2-u5-X42"},{"t":"추신이 없어서 편지라고 할 수 없다","mis":"K4-2-u5-X39"}],"explanation":["“제 마음 아시죠?”만으로는 무엇이 고마운지 알 수 없어요.","첫인사, 끝인사, 쓴 날짜가 빠졌어요.","높임 표현도 잘못된 곳이 있어요."],"asset":{"type":"passage","lines":["할머니에게","할머니, 저 석원이예요. 할머니에게 감사의 마음을 전하고 싶어서","이렇게 편지를 썼어요. 제 마음 아시죠? 항상 고맙습니다.","다음 주면 할머니의 생일이네요. 가족과 할머니 집으로 갈게요.","할머니, 사랑해요.","지석원 씀"],"title":"고쳐 쓸 곳이 있는 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#7','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C62',3,'mc','auto','『국어활동』 72쪽 현승이의 편지예요. 누가 누구에게 어떤 마음을 전하려고 쓴 편지인가요?',ARRAY['K4-2-u5-X37']::text[],false,'{"seq":7,"concept":"K4-2-u5-C62","difficulty":3,"kind":"mc","stem":"『국어활동』 72쪽 현승이의 편지예요. 누가 누구에게 어떤 마음을 전하려고 쓴 편지인가요?","options":[{"t":"현승이가 반 친구들에게, 넘어졌을 때 일으켜 준 데 대한 고마운 마음을 전하려고 썼다","correct":true},{"t":"반 친구들이 현승이에게 응원하는 마음을 전하려고 썼다","mis":"K4-2-u5-X37"},{"t":"현승이가 선생님께 체육 대회 결과를 알리려고 썼다","mis":"K4-2-u5-X37"}],"explanation":["받는 사람은 ‘우리 반 친구들에게’, 쓴 사람은 ‘현승이가’예요.","체육 대회에서 넘어졌을 때 친구들이 일으켜 주었어요.","그 고마운 마음을 전하려고 썼어요."],"asset":{"type":"passage","lines":["우리 반 친구들에게","친구들아, 안녕? 나 현승이야.","그때 그 고마운 마음을 직접 말로 전하고 싶었지만 쑥스러워서 이렇게 편지를 쓰게 되었어.","(간추림) 체육 대회 달리기에서 긴장해 달리다가 넘어졌을 때, 친구들이 돌아와 일으켜 주었다.","(간추림) 힘껏 달리고 싶었을 텐데 나 때문에 참았을 것 같아 미안한 마음도 들었다.","같이 달려 주고 응원해 준 너희의 따뜻한 마음 잊지 않을게.","현승이가"],"title":"현승이가 반 친구들에게 쓴 편지 — 『국어활동』 72쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#8','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C62',4,'essay','teacher','이황이 손자에게 쓴 편지를 읽고, 읽는 사람과 편지를 쓴 목적을 쓰고, 이황이 전하려는 마음 한 가지와 그 마음이 드러난 표현을 찾아 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C62","difficulty":4,"kind":"essay","stem":"이황이 손자에게 쓴 편지를 읽고, 읽는 사람과 편지를 쓴 목적을 쓰고, 이황이 전하려는 마음 한 가지와 그 마음이 드러난 표현을 찾아 쓰세요.","answer_guide":{"answer":"예: 읽는 사람 — 손자 안도 / 목적 — 절에 머물며 공부하기로 한 손자에게 공부에 힘쓰라고 당부하려고 / 마음 — 손자가 보고 싶은 마음, 표현 — “네가 얼마나 보고 싶은지 모른다.”","scoring_points":["읽는 사람을 바르게 썼는가","편지를 쓴 목적을 썼는가","전하려는 마음과 그 마음이 드러난 표현을 찾아 썼는가"]},"explanation":["편지 첫 줄에서 읽는 사람을 찾아요.","무엇 때문에 썼는지 목적을 찾아요.","마음이 드러난 문장에 밑줄을 그어 보아요."],"asset":{"type":"passage","lines":["손자 안도에게","(간추림) 산속 절에 머물며 공부하기로 했다는 소식을 듣고 좋은 일이라고 했다.","세월은 물처럼 흐른단다. 그러니 허투루 보내지 말고 천 번 만 번 힘써서 공부하거라.","(간추림) 흐지부지 보내면 공부가 흩어질까 걱정스럽다고 했다.","네가 얼마나 보고 싶은지 모른다.","(간추림) 생일 선물을 가져온 마음은 고맙지만 너희 얼굴을 보는 것이 더 기쁘다고 했다.","1568년 퇴계 이황"],"title":"이황이 손자에게 쓴 편지 (평가 자료 2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#9','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C38',4,'essay','teacher','『국어』 241쪽 5번처럼 고마운 분께 마음을 전하는 편지를 써요. 받는 사람, 첫인사, 전하고 싶은 말(있었던 일과 마음), 쓴 사람을 넣어 짧게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C38","difficulty":4,"kind":"essay","stem":"『국어』 241쪽 5번처럼 고마운 분께 마음을 전하는 편지를 써요. 받는 사람, 첫인사, 전하고 싶은 말(있었던 일과 마음), 쓴 사람을 넣어 짧게 쓰세요.","answer_guide":{"answer":"예: ○○ 선생님께 / 안녕하세요. 저는 ○○입니다. / 지난번 줄넘기를 잘 못해서 속상했을 때 선생님께서 발 구르는 방법을 하나씩 알려 주셨어요. 덕분에 끝까지 넘을 수 있게 되었어요. 정말 고맙습니다. / 제자 ○○ 올림","scoring_points":["받는 사람과 첫인사를 썼는가","있었던 일과 고마운 마음을 구체적으로 썼는가","쓴 사람을 높임 표현에 맞게 썼는가"]},"explanation":["편지의 짜임에 맞게 써요.","무엇이 고마웠는지 있었던 일을 써요.","웃어른께는 ‘께’, ‘올림’처럼 높여요."],"asset":{"type":"passage","lines":["박○○ 선생님께","안녕하세요. 저는 김△△입니다.","(간추림) 작년 음악 시간에 리코더 소리를 제대로 내지 못해 속상했는데,","(간추림) 선생님께서 바른 자세와 호흡법, 텅잉 익히기를 하나씩 가르쳐 주시고","(간추림) 반복해서 연습하면 잘할 수 있다고 격려해 주셨다.","편지로 감사의 마음을 전합니다. 늘 건강하시길 바랍니다.","20○○년 ○○월 ○○일","제자 김△△ 올림"],"title":"선생님께 마음을 전하는 편지 (예시) — 『국어』 241쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L07_challenge#10','kor',4,2,'u5','L07','tb_g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C36',4,'essay','teacher','현승이는 고마운 마음을 직접 말로 전하고 싶었지만 쑥스러워서 편지를 썼어요. 말로 전하기 어려운 마음을 편지로 전하고 싶은 일을 떠올려, 편지로 전하면 좋은 점과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C36","difficulty":4,"kind":"essay","stem":"현승이는 고마운 마음을 직접 말로 전하고 싶었지만 쑥스러워서 편지를 썼어요. 말로 전하기 어려운 마음을 편지로 전하고 싶은 일을 떠올려, 편지로 전하면 좋은 점과 함께 쓰세요.","answer_guide":{"answer":"예: 다툰 뒤 먼저 사과하지 못한 짝에게 미안한 마음을 편지로 전하고 싶다. 편지로 쓰면 생각할 시간이 충분하고 고쳐 쓸 수도 있어서 진심을 더 잘 전할 수 있다.","scoring_points":["편지로 전하고 싶은 일과 마음을 썼는가","편지로 전하면 좋은 점을 썼는가","말로 전하기 어려운 까닭과 이어 썼는가"]},"explanation":["현승이는 쑥스러운 마음을 편지에 담았어요.","편지는 천천히 정리하며 쓸 수 있어요.","고쳐 쓸 수 있어 진심을 더 잘 전해요."],"asset":{"type":"passage","lines":["우리 반 친구들에게","친구들아, 안녕? 나 현승이야.","그때 그 고마운 마음을 직접 말로 전하고 싶었지만 쑥스러워서 이렇게 편지를 쓰게 되었어.","(간추림) 체육 대회 달리기에서 긴장해 달리다가 넘어졌을 때, 친구들이 돌아와 일으켜 주었다.","(간추림) 힘껏 달리고 싶었을 텐데 나 때문에 참았을 것 같아 미안한 마음도 들었다.","같이 달려 주고 응원해 준 너희의 따뜻한 마음 잊지 않을게.","현승이가"],"title":"현승이가 반 친구들에게 쓴 편지 — 『국어활동』 72쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#1','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C44',1,'mc','auto','『국어』 242쪽 (2)에서 편지 쓰기에 필요한 내용을 정리했어요. 정리한 네 가지로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":1,"concept":"K4-2-u5-C44","difficulty":1,"kind":"mc","stem":"『국어』 242쪽 (2)에서 편지 쓰기에 필요한 내용을 정리했어요. 정리한 네 가지로 알맞은 것은 무엇인가요?","options":[{"t":"마음을 전할 사람 · 있었던 일 · 전하고 싶은 마음 · 마음을 나타내는 표현","correct":true},{"t":"받는 사람 · 우편 번호 · 우표 · 봉투","mis":"K4-2-u5-X27"},{"t":"대화 상대 · 대화 방식 · 대화 주제 · 까닭","mis":"K4-2-u5-X27"}],"explanation":["누구에게 쓸지 정해요.","어떤 일이 있었고 어떤 마음인지 정리해요.","그 마음을 나타낼 표현까지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#2','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C46',1,'mc','auto','『국어』 242쪽 (1)에서 떠올린 일과 전하고 싶은 마음을 알맞게 짝 지은 것은 무엇인가요?',ARRAY['K4-2-u5-X46']::text[],false,'{"seq":2,"concept":"K4-2-u5-C46","difficulty":1,"kind":"mc","stem":"『국어』 242쪽 (1)에서 떠올린 일과 전하고 싶은 마음을 알맞게 짝 지은 것은 무엇인가요?","options":[{"t":"동생이 줄넘기 대회에서 상을 받았다 — 축하하는 마음","correct":true},{"t":"친구와 의견이 맞지 않아 다투었다 — 축하하는 마음","mis":"K4-2-u5-X46"},{"t":"편찮으신 할아버지께 병문안을 갔다 — 미안한 마음","mis":"K4-2-u5-X46"}],"explanation":["좋은 일에는 축하하는 마음을 전해요.","다툰 일에는 미안한 마음이 들었어요.","편찮으신 할아버지께는 어서 회복하시길 바라는 마음이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동생이 줄넘기 대회에서 상을 받았다. 축하해 주고 싶었다."},{"who":"친구 2","text":"친구와 의견이 맞지 않아 다투었는데 미안한 마음이 들었다."},{"who":"친구 3","text":"편찮으신 할아버지를 뵙기 위해 병문안을 갔다. 어서 건강을 회복하셨으면 좋겠다."},{"who":"친구 4","text":"소방관님들이 안전 교육을 해 주셔서 고마운 마음이 들었다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#3','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C47',1,'match','auto','편지의 처음 · 가운데 · 끝과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u5-C47","difficulty":1,"kind":"match","stem":"편지의 처음 · 가운데 · 끝과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"읽는 사람을 부르는 말과 안부를 묻는 말"},{"l":"가운데","r":"함께 겪은 일과 그 일에 대한 생각이나 느낌"},{"l":"끝","r":"읽는 사람에게 바라는 점과 끝인사, 쓴 날짜, 쓴 사람"}],"mis":"K4-2-u5-X47","explanation":["처음에는 부르는 말과 안부를 써요.","함께 겪은 일은 가운데에 써요.","쓴 날짜와 쓴 사람은 끝에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#4','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C51',1,'ox','auto','편지봉투에는 보내는 사람의 주소와 이름을 왼쪽 위에, 받는 사람의 주소와 이름을 오른쪽 아래에 써요.',ARRAY['K4-2-u5-X50']::text[],false,'{"seq":4,"concept":"K4-2-u5-C51","difficulty":1,"kind":"ox","stem":"편지봉투에는 보내는 사람의 주소와 이름을 왼쪽 위에, 받는 사람의 주소와 이름을 오른쪽 아래에 써요.","answer":"O","reason_options":[{"t":"편지봉투 쓰는 방법이 그렇게 정해져 있어야 우편물이 받는 사람에게 바르게 전해지기 때문에","correct":true},{"t":"받는 사람이 더 중요하니 왼쪽 위에 크게 써야 하기 때문에","mis":"K4-2-u5-X50"}],"mis":"K4-2-u5-X50","explanation":["『국어』 245쪽에서 편지봉투 쓰는 방법을 알아보았어요.","보내는 사람은 왼쪽 위, 받는 사람은 오른쪽 아래예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#5','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C48',2,'mc','auto','소방관님께 쓴 편지에서 전하고 싶은 말을 구체적으로 쓴 부분은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X49']::text[],false,'{"seq":5,"concept":"K4-2-u5-C48","difficulty":2,"kind":"mc","stem":"소방관님께 쓴 편지에서 전하고 싶은 말을 구체적으로 쓴 부분은 무엇인가요?","options":[{"t":"지난주 학교에 오셔서 화재 상황에서 대피하는 방법을 자세히 알려 주시고 훈련도 도와주셔서 고맙습니다.","correct":true},{"t":"정말정말 고맙습니다. 아주아주 고맙습니다.","mis":"K4-2-u5-X48"},{"t":"고마워요.","mis":"K4-2-u5-X49"}],"explanation":["구체적으로 쓴다는 것은 길게 쓰는 것이 아니에요.","언제, 무엇을 해 주셨는지 밝혔어요.","그래서 읽는 사람이 무엇이 고마운지 알 수 있어요."],"asset":{"type":"passage","lines":["받는 사람 — 소방관님께","첫인사 — 안녕하세요? 저는 ○○초등학교 4학년 손△△(이)라고 해요.","전하고 싶은 말 — (간추림) 화재 대피 방법을 알려 주시고 훈련을 도와주셔서 고맙다.","끝인사 — 소방관님, 다른 이들의 안전을 챙기듯 소방관님의 안전도","         꼭 챙기시고 늘 건강하시기를 바랄게요. 안녕히 계세요.","쓴 날짜 — 20○○년 ○○월 ○○일","쓴 사람 — 감사의 마음을 담아 손△△ 올림","추신 — 언제 어디서나 응원하겠습니다!"],"title":"소방관님께 쓴 편지 (예시) — 『국어』 243쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#6','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C49',2,'ox','auto','마음을 전하는 편지를 솔직하게 쓰려면 읽을 사람의 처지는 생각하지 않아도 돼요.',ARRAY['K4-2-u5-X44']::text[],false,'{"seq":6,"concept":"K4-2-u5-C49","difficulty":2,"kind":"ox","stem":"마음을 전하는 편지를 솔직하게 쓰려면 읽을 사람의 처지는 생각하지 않아도 돼요.","answer":"X","reason_options":[{"t":"솔직한 마음을 전하되 읽을 상대의 상황과 마음을 고려하고 배려하며 써야 하기 때문에","correct":true},{"t":"솔직함과 배려는 함께할 수 없기 때문에","mis":"K4-2-u5-X44"}],"mis":"K4-2-u5-X44","explanation":["솔직한 마음을 전해요.","읽을 상대의 상황과 마음도 생각해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#7','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C50',2,'mc','auto','『국어』 244쪽 점검에서 「전하고 싶은 마음이 잘 드러났나요?」에 「아니요」가 나왔어요. 어떻게 고쳐 쓰면 될까요?',ARRAY['K4-2-u5-X31','K4-2-u5-X32']::text[],false,'{"seq":7,"concept":"K4-2-u5-C50","difficulty":2,"kind":"mc","stem":"『국어』 244쪽 점검에서 「전하고 싶은 마음이 잘 드러났나요?」에 「아니요」가 나왔어요. 어떻게 고쳐 쓰면 될까요?","options":[{"t":"감사, 사과, 축하, 위로처럼 전하고 싶은 마음이 잘 나타나는 표현을 넣는다","correct":true},{"t":"「예」로 바꾸어 표시해 둔다","mis":"K4-2-u5-X31"},{"t":"그 물음은 넘기고 다음 물음으로 간다","mis":"K4-2-u5-X32"}],"explanation":["「아니요」가 나온 곳이 고칠 곳이에요.","마음이 잘 나타나는 표현을 넣어 고쳐 써요.","표시만 바꾸면 편지는 그대로예요."],"asset":{"type":"passage","lines":["1 편지의 짜임에 맞게 썼나요?","2 마음을 전하는 글의 내용을 자세히 썼나요?","3 전하고 싶은 마음이 잘 드러났나요?","4 읽는 이를 고려해 썼나요?","→ 「아니요」가 나오면 그 물음에 맞게 고쳐 쓰고, 「예」면 다음 물음으로 간다.","→ 마지막에는 다시 한번 읽고 부족한 부분이 있으면 고쳐 쓴다."],"numbered":false,"title":"읽는 이를 생각하며 마음을 잘 표현했는지 점검하기 — 『국어』 244쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#8','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C51',2,'blank','auto','『국어』 245쪽 편지봉투에서 받는 사람을 높여 썼어요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#9','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C52',2,'mc','auto','다 쓴 편지를 전하는 방법으로 『국어』 245쪽에서 말한 것이 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X52']::text[],false,'{"seq":9,"concept":"K4-2-u5-C52","difficulty":2,"kind":"mc","stem":"다 쓴 편지를 전하는 방법으로 『국어』 245쪽에서 말한 것이 아닌 것은 무엇인가요?","options":[{"t":"편지를 다 썼으니 서랍에 넣어 두기만 한다","correct":true},{"t":"우표를 붙여 우체통에 넣는다","mis":"K4-2-u5-X52"},{"t":"학급 친구나 가족에게는 직접 전달한다","mis":"K4-2-u5-X52"},{"t":"전자 우편을 활용한다","mis":"K4-2-u5-X52"}],"explanation":["편지는 상대에게 닿아야 마음이 전해져요.","우체통, 우체국, 직접 전달, 전자 우편 모두 전하는 방법이에요.","서랍에 두기만 하면 전해지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_basic#10','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C47',3,'error','auto','편지의 가운데 부분을 두고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?',ARRAY['K4-2-u5-X47']::text[],false,'{"seq":10,"concept":"K4-2-u5-C47","difficulty":3,"kind":"error","stem":"편지의 가운데 부분을 두고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“쓴 날짜와 쓴 사람은 가운데 부분에 써.”","correct":true,"mis_target":"K4-2-u5-X47"},{"t":"“편지를 쓴 까닭과 함께 겪은 일을 가운데에 써.”","mis":"K4-2-u5-X47"},{"t":"“읽는 사람의 입장과 마음을 헤아리는 말도 가운데에 넣을 수 있어.”","mis":"K4-2-u5-X47"}],"explanation":["가운데에는 쓴 까닭, 겪은 일, 생각이나 느낌을 써요.","읽는 사람의 마음을 헤아리는 말과 다짐도 가운데예요.","쓴 날짜와 쓴 사람은 끝에 써요."],"asset":{"type":"passage","lines":["처음 — 읽는 사람을 부르는 말 · 안부를 묻는 말 ·","        글쓴이가 어떻게 지내는지 알리는 말 · 계절이나 날씨에 대한 말","가운데 — 편지를 쓴 까닭 · 직접 말로 마음을 전하지 못하는 까닭 ·","        읽는 사람과 함께 겪은 일 · 겪은 일에 대한 생각이나 느낌 ·","        읽는 사람의 입장과 마음을 헤아리는 말 · 앞으로의 다짐","끝 — 읽는 사람에게 바라는 점 · 끝인사 · 쓴 날짜 · 쓴 사람","(덧붙이고 싶은 말은 추신으로 — 필요한 경우에만 쓴다.)"],"numbered":false,"title":"편지의 처음 · 가운데 · 끝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#1','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C51',2,'sa','auto','우편물을 쉽게 분류하려고 매긴 번호를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C51","difficulty":2,"kind":"sa","stem":"우편물을 쉽게 분류하려고 매긴 번호를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["우편 번호","우편번호"],"explanation":["편지봉투의 주소와 함께 써요.","다섯 자리를 정확하게 써야 해요.","답은 ‘우편 번호’예요."],"mis":"K4-2-u5-X51"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#2','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C45',2,'mc','auto','『국어』 242쪽 (1)에서 떠올린 일 가운데 하나를 골라 (2)에 정리했어요. 마음을 전할 사람이 ‘소방관님’이라면 어떤 일을 고른 것인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":2,"concept":"K4-2-u5-C45","difficulty":2,"kind":"mc","stem":"『국어』 242쪽 (1)에서 떠올린 일 가운데 하나를 골라 (2)에 정리했어요. 마음을 전할 사람이 ‘소방관님’이라면 어떤 일을 고른 것인가요?","options":[{"t":"소방관님들이 안전 교육을 해 주신 일","correct":true},{"t":"동생이 줄넘기 대회에서 상을 받은 일","mis":"K4-2-u5-X27"},{"t":"친구와 의견이 맞지 않아 다툰 일","mis":"K4-2-u5-X27"}],"explanation":["떠올린 일 가운데 한 가지를 골라요.","마음을 전할 사람과 있었던 일이 이어져야 해요.","소방관님께는 안전 교육에 대한 고마운 마음을 전해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동생이 줄넘기 대회에서 상을 받았다. 축하해 주고 싶었다."},{"who":"친구 2","text":"친구와 의견이 맞지 않아 다투었는데 미안한 마음이 들었다."},{"who":"친구 3","text":"편찮으신 할아버지를 뵙기 위해 병문안을 갔다. 어서 건강을 회복하셨으면 좋겠다."},{"who":"친구 4","text":"소방관님들이 안전 교육을 해 주셔서 고마운 마음이 들었다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#3','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C46',3,'mc','auto','혜정이가 지민이에게 쓴 편지예요. 혜정이가 전하려는 마음과 그 까닭을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-2-u5-X46','K4-2-u5-X37']::text[],false,'{"seq":3,"concept":"K4-2-u5-C46","difficulty":3,"kind":"mc","stem":"혜정이가 지민이에게 쓴 편지예요. 혜정이가 전하려는 마음과 그 까닭을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"고마운 마음 — 전학 와서 학예회 율동이 힘들었을 때 지민이가 알려 주고 같이 연습해 주어서","correct":true},{"t":"미안한 마음 — 학예회 연습을 같이 하지 못해서","mis":"K4-2-u5-X46"},{"t":"축하하는 마음 — 지민이가 학예회에서 상을 받아서","mis":"K4-2-u5-X37"}],"explanation":["혜정이는 지난달에 전학을 왔어요.","지민이가 쉬는 시간에 율동을 알려 주고 같이 연습해 주었어요.","그래서 “정말 고마워.”라고 했어요."],"asset":{"type":"passage","lines":["지민이에게","지민아, 안녕? 나 혜정이야.","(간추림) 지난달에 전학을 와서 학예회 노래와 율동을 익히기가 힘들었는데,","(간추림) 지민이가 쉬는 시간에 율동을 알려 주고 같이 연습해 주어 큰 도움이 되었다.","(간추림) 덕분에 자신감이 생겨 학예회 무대가 설레고 기대된다.","지민아, 정말 고마워. 앞으로도 우리 같이 재미있게 연습해서 멋진 무대 만들자.","20○○년 ○○월 ○○일","너의 친구 혜정 씀"],"title":"혜정이가 지민이에게 쓴 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#4','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C48',3,'mc','auto','혜정이의 편지가 마음을 구체적으로 전했다고 할 수 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X48']::text[],false,'{"seq":4,"concept":"K4-2-u5-C48","difficulty":3,"kind":"mc","stem":"혜정이의 편지가 마음을 구체적으로 전했다고 할 수 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"지민이가 언제, 무엇을 도와주었고 그 덕분에 어떻게 달라졌는지를 썼기 때문","correct":true},{"t":"“고마워”를 여러 번 되풀이했기 때문","mis":"K4-2-u5-X48"},{"t":"편지를 아주 길게 썼기 때문","mis":"K4-2-u5-X48"}],"explanation":["쉬는 시간에 율동을 알려 주고 같이 연습해 준 일을 썼어요.","덕분에 자신감이 생기고 무대가 기대된다고 했어요.","있었던 일과 마음이 함께 드러나요."],"asset":{"type":"passage","lines":["지민이에게","지민아, 안녕? 나 혜정이야.","(간추림) 지난달에 전학을 와서 학예회 노래와 율동을 익히기가 힘들었는데,","(간추림) 지민이가 쉬는 시간에 율동을 알려 주고 같이 연습해 주어 큰 도움이 되었다.","(간추림) 덕분에 자신감이 생겨 학예회 무대가 설레고 기대된다.","지민아, 정말 고마워. 앞으로도 우리 같이 재미있게 연습해서 멋진 무대 만들자.","20○○년 ○○월 ○○일","너의 친구 혜정 씀"],"title":"혜정이가 지민이에게 쓴 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#5','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C47',3,'mc','auto','편지의 끝 부분에 쓸 내용을 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['K4-2-u5-X38','K4-2-u5-X47']::text[],false,'{"seq":5,"concept":"K4-2-u5-C47","difficulty":3,"kind":"mc","stem":"편지의 끝 부분에 쓸 내용을 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"읽는 사람에게 바라는 점 → 끝인사 → 쓴 날짜 → 쓴 사람","correct":true},{"t":"쓴 사람 → 끝인사 → 읽는 사람에게 바라는 점 → 쓴 날짜","mis":"K4-2-u5-X38"},{"t":"끝인사 → 편지를 쓴 까닭 → 쓴 사람 → 쓴 날짜","mis":"K4-2-u5-X47"}],"explanation":["끝에는 바라는 점과 끝인사를 써요.","줄을 바꾸어 쓴 날짜를 써요.","마지막에 쓴 사람을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#6','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C52',3,'ox','auto','학급에서 ‘느린 우체통’을 만들어 편지를 모았다가 함께 정한 때에 나누어 주어도 마음을 전할 수 있어요.',ARRAY['K4-2-u5-X52']::text[],false,'{"seq":6,"concept":"K4-2-u5-C52","difficulty":3,"kind":"ox","stem":"학급에서 ‘느린 우체통’을 만들어 편지를 모았다가 함께 정한 때에 나누어 주어도 마음을 전할 수 있어요.","answer":"O","reason_options":[{"t":"편지를 직접 건네거나 우체통에 넣는 것처럼, 학급에서 모았다가 나누어 주어도 편지가 상대에게 닿기 때문에","correct":true},{"t":"편지는 쓰기만 하면 전하지 않아도 마음이 전해지기 때문에","mis":"K4-2-u5-X52"}],"mis":"K4-2-u5-X52","explanation":["다 쓴 편지는 상대에게 전해야 해요.","느린 우체통도 편지를 전하는 한 방법이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#7','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C50',3,'mc','auto','편지를 전하기 전에 학급에서 편지 낭독회를 열어요. 낭독회에서 듣는 친구들이 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X42','K4-2-u5-X48']::text[],false,'{"seq":7,"concept":"K4-2-u5-C50","difficulty":3,"kind":"mc","stem":"편지를 전하기 전에 학급에서 편지 낭독회를 열어요. 낭독회에서 듣는 친구들이 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"편지를 받는 사람의 입장이 되어 듣는다","correct":true},{"t":"틀린 글자만 찾아 크게 말한다","mis":"K4-2-u5-X42"},{"t":"편지가 가장 긴 친구를 고른다","mis":"K4-2-u5-X48"}],"explanation":["낭독하는 친구는 알맞은 속도와 목소리로 읽어요.","듣는 친구는 받는 사람의 입장이 되어요.","그러면 편지에 담긴 마음을 더 잘 느낄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#8','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C44',4,'essay','teacher','마음을 전하고 싶은 일을 하나 떠올려 『국어』 242쪽 (2)처럼 마음을 전할 사람, 있었던 일, 전하고 싶은 마음, 마음을 나타내는 표현을 정리하세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C44","difficulty":4,"kind":"essay","stem":"마음을 전하고 싶은 일을 하나 떠올려 『국어』 242쪽 (2)처럼 마음을 전할 사람, 있었던 일, 전하고 싶은 마음, 마음을 나타내는 표현을 정리하세요.","answer_guide":{"answer":"예: 마음을 전할 사람 — 우리 반 친구들 / 있었던 일 — 내가 학교에 오지 못한 동안 학급 문고를 정리하고 화분에 물을 주었다 / 전하고 싶은 마음 — 고마운 마음 / 마음을 나타내는 표현 — 정말 고마워.","scoring_points":["마음을 전할 사람을 썼는가","있었던 일과 전하고 싶은 마음을 썼는가","마음을 나타내는 표현을 썼는가"]},"explanation":["마음을 전하고 싶었던 일을 떠올려요.","네 칸을 하나씩 채워요.","마음을 나타내는 표현은 실제로 편지에 쓸 말이에요."],"asset":{"type":"passage","lines":["마음을 전할 사람 — 소방관님","있었던 일 — 소방관님들이 학교에 오셔서 안전 교육을 해 주셨다.","전하고 싶은 마음 — 고마운 마음","마음을 나타내는 표현 — 고맙습니다."],"title":"편지 쓰기 계획 (예시) — 『국어』 242쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#9','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C47',4,'essay','teacher','계획한 내용을 바탕으로 편지의 처음 · 가운데 · 끝에 각각 들어갈 문장을 한 문장씩 쓰세요. 받는 사람에 맞는 높임 표현도 생각하세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C47","difficulty":4,"kind":"essay","stem":"계획한 내용을 바탕으로 편지의 처음 · 가운데 · 끝에 각각 들어갈 문장을 한 문장씩 쓰세요. 받는 사람에 맞는 높임 표현도 생각하세요.","answer_guide":{"answer":"예: 처음 — 「할아버지, 안녕하세요? 요즘 날씨가 많이 추워졌는데 건강하시지요?」 / 가운데 — 「지난주 병문안을 갔을 때 저를 보고 웃어 주셔서 마음이 놓였어요.」 / 끝 — 「어서 건강을 회복하셨으면 좋겠어요. 안녕히 계세요.」","scoring_points":["처음에 부르는 말과 안부를 썼는가","가운데에 있었던 일과 마음을 썼는가","끝에 바라는 점과 끝인사를 쓰고 높임 표현을 맞추었는가"]},"explanation":["처음 · 가운데 · 끝에 들어갈 내용이 달라요.","받는 사람이 웃어른이면 높여요.","가운데에 있었던 일과 마음을 구체적으로 써요."],"asset":{"type":"passage","lines":["처음 — 읽는 사람을 부르는 말 · 안부를 묻는 말 ·","        글쓴이가 어떻게 지내는지 알리는 말 · 계절이나 날씨에 대한 말","가운데 — 편지를 쓴 까닭 · 직접 말로 마음을 전하지 못하는 까닭 ·","        읽는 사람과 함께 겪은 일 · 겪은 일에 대한 생각이나 느낌 ·","        읽는 사람의 입장과 마음을 헤아리는 말 · 앞으로의 다짐","끝 — 읽는 사람에게 바라는 점 · 끝인사 · 쓴 날짜 · 쓴 사람","(덧붙이고 싶은 말은 추신으로 — 필요한 경우에만 쓴다.)"],"numbered":false,"title":"편지의 처음 · 가운데 · 끝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L09_challenge#10','kor',4,2,'u5','L09','tb_g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C51',4,'essay','teacher','할아버지께 편지를 보내려고 편지봉투를 써요. 보내는 사람과 받는 사람을 어디에 어떻게 쓰는지, 우표와 우편 번호는 어떻게 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C51","difficulty":4,"kind":"essay","stem":"할아버지께 편지를 보내려고 편지봉투를 써요. 보내는 사람과 받는 사람을 어디에 어떻게 쓰는지, 우표와 우편 번호는 어떻게 하는지 쓰세요.","answer_guide":{"answer":"예: 왼쪽 위에 내 주소와 이름을, 오른쪽 아래에 할아버지의 주소와 이름을 쓰고 이름 뒤에 ‘님께’를 붙이거나 ‘귀하’를 쓴다. 우표는 오른쪽 위에 붙이고, 우편 번호 다섯 자리를 정확하게 쓴다.","scoring_points":["보내는 사람과 받는 사람의 자리를 바르게 썼는가","할아버지를 높이는 표현(님께·귀하)을 썼는가","우표와 우편 번호를 바르게 썼는가"]},"explanation":["보내는 사람은 왼쪽 위, 받는 사람은 오른쪽 아래예요.","웃어른께는 ‘님께’나 ‘귀하’를 써요.","우표는 오른쪽 위, 우편 번호는 다섯 자리예요."],"asset":{"type":"passage","lines":["보내는 사람의 주소와 이름 — 왼쪽 위 (예: 장영실 올림)","받는 사람의 주소와 이름 — 오른쪽 아래 (예: 세종 대왕 님께)","받는 사람이 친구나 아랫사람 — ‘○○○ 앞’, ‘○○○에게’","상대를 높여야 할 때 — 이름 뒤에 ‘귀하’를 붙이거나 ‘○○○ 님께’","우표 — 우편 요금을 냈다는 증표, 봉투 오른쪽 위에 붙인다.","우편 번호 — 우편물을 쉽게 분류하려고 매긴 번호, 다섯 자리를 정확하게"],"title":"편지봉투 쓰는 방법 — 『국어』 245쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#1','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C53',1,'mc','auto','『국어』 246~247쪽 「이런 활동 어때요」에서 소개한 두 활동은 무엇인가요?',ARRAY['K4-2-u5-X53']::text[],false,'{"seq":1,"concept":"K4-2-u5-C53","difficulty":1,"kind":"mc","stem":"『국어』 246~247쪽 「이런 활동 어때요」에서 소개한 두 활동은 무엇인가요?","options":[{"t":"온라인 대화 예절을 알리는 활동 하기 · 비밀 친구에게 편지 쓰기","correct":true},{"t":"토의 대회 열기 · 영상 회의 하기","mis":"K4-2-u5-X53"},{"t":"편지봉투 꾸미기 대회 · 그림말 만들기","mis":"K4-2-u5-X53"}],"explanation":["활동 1은 온라인 대화 예절을 알리는 활동이에요.","활동 2는 비밀 친구에게 편지 쓰기예요.","두 소단원에서 배운 것을 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#2','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C54',1,'mc','auto','『국어』 246쪽 예시처럼 온라인 대화 예절을 알리는 표어로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X54','K4-2-u5-X53']::text[],false,'{"seq":2,"concept":"K4-2-u5-C54","difficulty":1,"kind":"mc","stem":"『국어』 246쪽 예시처럼 온라인 대화 예절을 알리는 표어로 알맞은 것은 무엇인가요?","options":[{"t":"보이지 않아도 예절을 지켜요","correct":true},{"t":"온라인 대화를 아예 하지 맙시다","mis":"K4-2-u5-X54"},{"t":"온라인에서는 주제에 맞게 말하고, 사진은 허락을 받고, 사실을 확인하고, 상대를 존중해야 합니다","mis":"K4-2-u5-X53"}],"explanation":["표어는 짧고 기억하기 쉬워요.","무엇을 하자는 것인지 담겨 있어요.","아예 하지 말자는 말은 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#3','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C56',1,'mc','auto','비밀 친구에게 편지 쓰기를 할 때 비밀 친구는 어떻게 정하나요?',ARRAY['K4-2-u5-X56']::text[],false,'{"seq":3,"concept":"K4-2-u5-C56","difficulty":1,"kind":"mc","stem":"비밀 친구에게 편지 쓰기를 할 때 비밀 친구는 어떻게 정하나요?","options":[{"t":"학급 친구들의 이름을 쓴 쪽지 가운데에서 하나를 뽑아 정한다","correct":true},{"t":"가장 친한 친구를 골라 정한다","mis":"K4-2-u5-X56"},{"t":"편지를 받고 싶은 친구가 손을 들어 정한다","mis":"K4-2-u5-X56"}],"explanation":["『국어』 247쪽 활동 순서 ①이에요.","이름 쪽지를 하나 뽑아요.","뽑은 친구의 비밀 친구가 되어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#4','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C58',1,'mc','auto','『국어』 250쪽 대화 가의 “어항의 물이 참 맑다.”에서 ‘맑다’는 어떻게 소리 나나요?',ARRAY['K4-2-u5-X58','K4-2-u5-X59']::text[],false,'{"seq":4,"concept":"K4-2-u5-C58","difficulty":1,"kind":"mc","stem":"『국어』 250쪽 대화 가의 “어항의 물이 참 맑다.”에서 ‘맑다’는 어떻게 소리 나나요?","options":[{"t":"[막따]","correct":true},{"t":"[말따]","mis":"K4-2-u5-X58"},{"t":"[맑따]","mis":"K4-2-u5-X59"}],"explanation":["겹받침 ㄺ은 보통 [ㄱ]만 소리 나요.","‘맑다’는 [막따]로 읽어요.","두 받침을 모두 소리 내지 않아요."],"asset":{"type":"passage","lines":["[대화 가] “어항의 물이 참 맑다.”","         “내가 아침에 물을 갈았더니 맑고 깨끗해졌어.”","[대화 나] “달이 참 밝다.” “보름달이라서 밝게 빛나는구나!”"],"numbered":false,"title":"기초 다지기 1 — 『국어』 250쪽","hi":["맑다","맑고","밝다","밝게"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#5','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C55',2,'blank','auto','『국어』 246쪽 활동 순서 ②예요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#6','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C56',2,'mc','auto','비밀 친구에게 편지를 쓸 때 둘 사이에 있었던 특별한 일보다 친구의 장점을 칭찬하는 내용을 쓰라고 한 까닭은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X52']::text[],false,'{"seq":6,"concept":"K4-2-u5-C56","difficulty":2,"kind":"mc","stem":"비밀 친구에게 편지를 쓸 때 둘 사이에 있었던 특별한 일보다 친구의 장점을 칭찬하는 내용을 쓰라고 한 까닭은 무엇인가요?","options":[{"t":"둘만의 특별한 경험을 쓰면 비밀 친구가 누구인지 밝혀질 수 있기 때문","correct":true},{"t":"칭찬하는 말은 길게 쓸 수 있기 때문","mis":"K4-2-u5-X48"},{"t":"비밀 친구에게는 마음을 전하지 않아도 되기 때문","mis":"K4-2-u5-X52"}],"explanation":["비밀 친구 활동은 정한 기간 동안 이름을 밝히지 않아요.","둘만 아는 일을 쓰면 누가 썼는지 알게 돼요.","그래서 친구의 장점을 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#7','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C57',2,'mc','auto','우리 반에서 정한 활동 「매체 대 매체 놀이」에서 매체 카드 두 장을 뽑은 친구가 할 일은 무엇인가요?',ARRAY['K4-2-u5-X57','K4-2-u5-X53']::text[],false,'{"seq":7,"concept":"K4-2-u5-C57","difficulty":2,"kind":"mc","stem":"우리 반에서 정한 활동 「매체 대 매체 놀이」에서 매체 카드 두 장을 뽑은 친구가 할 일은 무엇인가요?","options":[{"t":"다른 사람이 보여 준 질문 카드의 질문에 알맞게, 뽑은 두 매체의 특성을 비교하여 대답한다","correct":true},{"t":"두 매체 가운데 어느 것이 모든 면에서 이기는지 정한다","mis":"K4-2-u5-X57"},{"t":"뽑은 매체 카드를 친구에게 그대로 읽어 준다","mis":"K4-2-u5-X53"}],"explanation":["다른 사람이 질문 카드를 한 장 뽑아 보여 줘요.","그 질문에 맞게 두 매체의 특성을 비교해 대답해요.","매체의 특성을 익히는 놀이예요."],"asset":{"type":"passage","lines":["① 매체 카드와 질문 카드를 여섯 장씩 만든다.","② 짝과 가위바위보를 하여 놀이의 순서를 정한다.","③ 매체 카드와 질문 카드를 뒤집어 책상 위에 올려놓는다.","④ 자신의 순서가 되면 매체 카드 두 장을 뽑는다.","⑤ 다른 사람은 질문 카드 한 장을 뽑아 대답할 사람에게 보여 준다.","⑥ 질문에 알맞게 자신이 뽑은 매체 두 개의 특성을 비교하여 대답한다.","⑦ 카드를 섞어 놀이를 반복한다.","⑧ 같은 질문 카드가 나오면 앞사람과 다른 대답을 한다."],"numbered":false,"title":"우리 반에서 정한 활동 — 매체 대 매체 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#8','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C60',2,'mc','auto','『국어』 250쪽 2번에서 “수업 끝나고 축구 ㅇㅋ?”를 대화 예절을 생각하며 고쳐 쓴 것은 무엇인가요?',ARRAY['K4-2-u5-X61']::text[],false,'{"seq":8,"concept":"K4-2-u5-C60","difficulty":2,"kind":"mc","stem":"『국어』 250쪽 2번에서 “수업 끝나고 축구 ㅇㅋ?”를 대화 예절을 생각하며 고쳐 쓴 것은 무엇인가요?","options":[{"t":"“수업 끝나고 같이 축구 할래?”","correct":true},{"t":"“수업 끝나고 축구 ㅇㅋㅇㅋ?”","mis":"K4-2-u5-X61"},{"t":"“축구.”","mis":"K4-2-u5-X61"}],"explanation":["줄임말은 뜻을 모르는 사람이 있을 수 있어요.","상대를 존중하는 말로 바꾸어요.","“같이 축구 할래?”처럼 묻는 뜻이 분명하게 써요."],"asset":{"type":"passage","lines":["오늘 날씨 ㄹㅇ 좋다. → 오늘 날씨 정말 좋다.","시험을 망쳤어. ㅠㅠㅠㅠㅠ → 시험을 망쳤어. 속상해.","수업 끝나고 축구 ㅇㅋ? → (          )","바빠서 이만. ㅂㅇ. → (          )"],"title":"온라인 대화에서 볼 수 있는 표현 고쳐 쓰기 — 『국어』 250쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#9','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C64',2,'mc','auto','『국어』 251쪽에서 겹받침 ㄼ이 들어간 낱말을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u5-X68']::text[],false,'{"seq":9,"concept":"K4-2-u5-C64","difficulty":2,"kind":"mc","stem":"『국어』 251쪽에서 겹받침 ㄼ이 들어간 낱말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"짧디짧다","correct":true},{"t":"짤디짤다","mis":"K4-2-u5-X68"},{"t":"짭디짭다","mis":"K4-2-u5-X68"}],"explanation":["받침 자리에 ㄹ과 ㅂ을 함께 써요.","‘짧다’의 받침은 ㄼ이에요.","‘짧디짧다’로 바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_basic#10','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C58',3,'mc','auto','겹받침 ㄺ 다음에 자음자 ㄱ이 올 때를 생각하며, “물이 참 맑기도 하구나.”의 ‘맑기도’를 바르게 읽은 것은 무엇인가요?',ARRAY['K4-2-u5-X58','K4-2-u5-X59']::text[],false,'{"seq":10,"concept":"K4-2-u5-C58","difficulty":3,"kind":"mc","stem":"겹받침 ㄺ 다음에 자음자 ㄱ이 올 때를 생각하며, “물이 참 맑기도 하구나.”의 ‘맑기도’를 바르게 읽은 것은 무엇인가요?","options":[{"t":"[말끼도]","correct":true},{"t":"[막끼도]","mis":"K4-2-u5-X58"},{"t":"[맑끼도]","mis":"K4-2-u5-X59"}],"explanation":["ㄺ 다음에 ㄱ이 오면 ㄺ이 [ㄹ]로 소리 나요.","‘맑고’가 [말꼬]인 것과 같아요.","‘맑기도’는 [말끼도]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#1','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C58',2,'sa','auto','“보름달이라서 밝게 빛나는구나!”에서 ‘밝게’는 어떻게 소리 나나요? 대괄호 안에 들어갈 소리를 쓰세요. [    ]','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C58","difficulty":2,"kind":"sa","stem":"“보름달이라서 밝게 빛나는구나!”에서 ‘밝게’는 어떻게 소리 나나요? 대괄호 안에 들어갈 소리를 쓰세요. [    ]","answer":["발께"],"explanation":["ㄺ 다음에 자음자 ㄱ이 왔어요.","이때 ㄺ은 [ㄹ]로 소리 나요.","‘밝게’는 [발께]예요."],"asset":{"type":"passage","lines":["[대화 가] “어항의 물이 참 맑다.”","         “내가 아침에 물을 갈았더니 맑고 깨끗해졌어.”","[대화 나] “달이 참 밝다.” “보름달이라서 밝게 빛나는구나!”"],"numbered":false,"title":"기초 다지기 1 — 『국어』 250쪽","hi":["맑다","맑고","밝다","밝게"]},"mis":"K4-2-u5-X58"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#2','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C53',2,'mc','auto','우리 반에서 정한 활동 「학급 친구에게 편지 쓰기」의 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X53']::text[],false,'{"seq":2,"concept":"K4-2-u5-C53","difficulty":2,"kind":"mc","stem":"우리 반에서 정한 활동 「학급 친구에게 편지 쓰기」의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"알리고 싶은 소식 떠올리기 → 소식을 글로 쓰기 → 교실 알림판에 붙이기 → 친구의 소식을 읽고 마음을 편지로 쓰기","correct":true},{"t":"친구의 소식을 읽고 편지 쓰기 → 소식 떠올리기 → 알림판에 붙이기 → 소식을 글로 쓰기","mis":"K4-2-u5-X53"},{"t":"알림판에 붙이기 → 소식 떠올리기 → 편지 쓰기 → 소식을 글로 쓰기","mis":"K4-2-u5-X53"}],"explanation":["먼저 학급 친구들에게 알리고 싶은 소식을 떠올려요.","글로 써서 교실 알림판에 붙여요.","친구의 소식을 읽고 전하고 싶은 마음을 편지로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#3','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C57',3,'mc','auto','「매체 대 매체 놀이」에서 매체 카드 ‘편지’와 ‘온라인 대화’를 뽑고, 질문 카드 「생각을 얼마나 빠르게 전달할 수 있나요?」를 받았어요. 알맞은 대답은 무엇인가요?',ARRAY['K4-2-u5-X57','K4-2-u5-X35']::text[],false,'{"seq":3,"concept":"K4-2-u5-C57","difficulty":3,"kind":"mc","stem":"「매체 대 매체 놀이」에서 매체 카드 ‘편지’와 ‘온라인 대화’를 뽑고, 질문 카드 「생각을 얼마나 빠르게 전달할 수 있나요?」를 받았어요. 알맞은 대답은 무엇인가요?","options":[{"t":"온라인 대화는 내용을 빠르게 전할 수 있고, 편지는 시간이 걸리지만 천천히 생각하며 쓸 수 있다","correct":true},{"t":"편지가 모든 면에서 온라인 대화보다 낫다","mis":"K4-2-u5-X57"},{"t":"온라인 대화는 옛날 매체라 편지보다 느리다","mis":"K4-2-u5-X35"}],"explanation":["질문에 맞게 두 매체를 견주어요.","메시지 같은 온라인 대화는 빠르게 전해져요.","편지는 생각할 시간이 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#4','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C54',3,'mc','auto','『국어』 246쪽 표어 「그림말, 줄임말 대신 진심 담은 예쁜 말」이 알리려는 온라인 대화 예절로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X61','K4-2-u5-X54']::text[],false,'{"seq":4,"concept":"K4-2-u5-C54","difficulty":3,"kind":"mc","stem":"『국어』 246쪽 표어 「그림말, 줄임말 대신 진심 담은 예쁜 말」이 알리려는 온라인 대화 예절로 알맞은 것은 무엇인가요?","options":[{"t":"뜻을 알기 어려운 그림말이나 줄임말보다 마음이 잘 전해지는 바르고 고운 말을 쓰자","correct":true},{"t":"그림말과 줄임말은 많이 쓸수록 좋다","mis":"K4-2-u5-X61"},{"t":"온라인 대화를 하지 말고 편지만 쓰자","mis":"K4-2-u5-X54"}],"explanation":["줄임말은 뜻을 모르는 사람이 오해할 수 있어요.","진심이 담긴 예쁜 말을 쓰자는 표어예요.","한 줄에 한 가지 예절을 담았어요."],"asset":{"type":"passage","lines":["보이지 않아도 예절을 지켜요","대화는 친절하게 댓글은 신중하게","따뜻한 댓글 행복한 인터넷 세상","손끝으로 피어나는 아름다운 문자 대화","그림말, 줄임말 대신 진심 담은 예쁜 말"],"title":"온라인 대화 예절을 알리는 표어 (예시) — 『국어』 246쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#5','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C55',3,'mc','auto','온라인 대화 예절을 알리는 활동을 실천하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X55']::text[],false,'{"seq":5,"concept":"K4-2-u5-C55","difficulty":3,"kind":"mc","stem":"온라인 대화 예절을 알리는 활동을 실천하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"팻말을 만들어 등하교 시간이나 쉬는 시간에 구호를 외치거나, 교내 알림판에 표어를 붙인다","correct":true},{"t":"표어를 공책에 적어 혼자 간직한다","mis":"K4-2-u5-X55"},{"t":"표어를 모둠 친구끼리만 말한다","mis":"K4-2-u5-X55"}],"explanation":["알림 활동은 여러 사람이 보고 들어야 해요.","팻말과 구호, 알림판을 쓸 수 있어요.","시간과 장소를 정해 실천해요."],"asset":{"type":"passage","lines":["① 온라인 대화를 할 때 지켜야 할 예절을 알리는 표어 떠올리기","② 알리는 활동을 언제 어디에서 누구와 어떤 방법으로 할지 계획하기","③ 시간과 장소를 정해 알림 활동 실천하기"],"numbered":false,"title":"이런 활동 어때요 1 — 『국어』 246쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#6','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C60',3,'mc','auto','“바빠서 이만. ㅂㅇ.”를 대화 예절을 생각하며 고쳐 쓴 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X34','K4-2-u5-X61']::text[],false,'{"seq":6,"concept":"K4-2-u5-C60","difficulty":3,"kind":"mc","stem":"“바빠서 이만. ㅂㅇ.”를 대화 예절을 생각하며 고쳐 쓴 것으로 알맞은 것은 무엇인가요?","options":[{"t":"“할 일이 있어서 먼저 나갈게. 안녕.”","correct":true},{"t":"(아무 말 없이 대화방을 나간다)","mis":"K4-2-u5-X34"},{"t":"“ㅂㅇㅂㅇ.”","mis":"K4-2-u5-X61"}],"explanation":["먼저 나가는 까닭을 알려요.","줄임말 대신 알아들을 수 있는 인사를 해요.","말없이 나가면 상대가 서운해요."],"asset":{"type":"passage","lines":["오늘 날씨 ㄹㅇ 좋다. → 오늘 날씨 정말 좋다.","시험을 망쳤어. ㅠㅠㅠㅠㅠ → 시험을 망쳤어. 속상해.","수업 끝나고 축구 ㅇㅋ? → (          )","바빠서 이만. ㅂㅇ. → (          )"],"title":"온라인 대화에서 볼 수 있는 표현 고쳐 쓰기 — 『국어』 250쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#7','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C58',3,'ox','auto','“가을 산에 붉지 않은 단풍이 드물다.”에서 ‘붉지’는 겹받침 ㄺ 다음에 ㄱ이 오지 않으므로 [북찌]로 읽어요.',ARRAY['K4-2-u5-X58']::text[],false,'{"seq":7,"concept":"K4-2-u5-C58","difficulty":3,"kind":"ox","stem":"“가을 산에 붉지 않은 단풍이 드물다.”에서 ‘붉지’는 겹받침 ㄺ 다음에 ㄱ이 오지 않으므로 [북찌]로 읽어요.","answer":"O","reason_options":[{"t":"ㄺ은 보통 [ㄱ]만 소리 나고, 뒤에 자음자 ㄱ이 올 때에만 [ㄹ]로 소리 나기 때문에","correct":true},{"t":"겹받침 ㄺ은 언제나 [ㄹ]로 소리 나기 때문에","mis":"K4-2-u5-X58"}],"mis":"K4-2-u5-X58","explanation":["‘붉지’는 ㄺ 다음에 ㅈ이 와요.","그래서 ㄺ은 [ㄱ]만 소리 나요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#8','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C56',4,'essay','teacher','비밀 친구에게 편지를 쓰려고 해요. 『국어』 247쪽 예시처럼 친구의 장점을 칭찬하는 내용을 넣어, 받는 사람과 쓴 사람까지 짧은 편지를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C56","difficulty":4,"kind":"essay","stem":"비밀 친구에게 편지를 쓰려고 해요. 『국어』 247쪽 예시처럼 친구의 장점을 칭찬하는 내용을 넣어, 받는 사람과 쓴 사람까지 짧은 편지를 쓰세요.","answer_guide":{"answer":"예: 나의 비밀 친구에게 / 안녕? 친구야. 너는 모둠 활동을 할 때 친구들의 의견을 끝까지 들어 주어서 멋지다고 생각했어. 지금은 내가 누구인지 밝힐 수 없지만 앞으로 더 즐겁게 지내자. / 너의 비밀 친구가","scoring_points":["받는 사람과 쓴 사람을 비밀 친구 편지에 맞게 썼는가","친구의 장점을 칭찬하는 내용을 썼는가","내가 누구인지 드러나는 특별한 일을 쓰지 않았는가"]},"explanation":["받는 사람은 ‘나의 비밀 친구에게’로 써요.","친구의 좋은 점을 칭찬해요.","쓴 사람은 ‘너의 비밀 친구가’로 써요."],"asset":{"type":"passage","lines":["나의 비밀 친구에게","안녕? 친구야.","(간추림) 4학년 첫날 환하게 웃으며 인사하던 모습을 본 뒤로 친해지고 싶었다.","(간추림) 운동을 잘하고 수업 시간에 자신 있게 발표하는 모습이 멋지다고 했다.","지금은 내가 누구인지 밝힐 수 없지만 나도 너에게 좋은 친구가 되고 싶어.","20○○년 ○○월 ○○일","너의 비밀 친구가"],"title":"비밀 친구에게 쓴 편지 (예시) — 『국어』 247쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#9','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C54',4,'essay','teacher','온라인 대화 예절 가운데 하나를 골라 알리는 표어를 짓고, 그 표어를 언제 어디에서 누구에게 어떤 방법으로 알릴지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C54","difficulty":4,"kind":"essay","stem":"온라인 대화 예절 가운데 하나를 골라 알리는 표어를 짓고, 그 표어를 언제 어디에서 누구에게 어떤 방법으로 알릴지 쓰세요.","answer_guide":{"answer":"예: 표어 — 「올리기 전에 한 번 더, 사실인지 확인해요」 / 다음 주 등교 시간에 학교 정문 앞에서 우리 모둠 친구들과 함께 팻말을 들고 구호를 외친다.","scoring_points":["예절 하나를 담은 짧은 표어를 지었는가","언제 · 어디에서 · 누구와를 정했는가","어떤 방법으로 알릴지 썼는가"]},"explanation":["표어는 짧게, 한 가지 예절을 담아요.","알릴 때와 곳을 정해요.","팻말, 구호, 알림판 같은 방법을 골라요."],"asset":{"type":"passage","lines":["① 온라인 대화를 할 때 지켜야 할 예절을 알리는 표어 떠올리기","② 알리는 활동을 언제 어디에서 누구와 어떤 방법으로 할지 계획하기","③ 시간과 장소를 정해 알림 활동 실천하기"],"numbered":false,"title":"이런 활동 어때요 1 — 『국어』 246쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_L11_challenge#10','kor',4,2,'u5','L11','tb_g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C57',4,'essay','teacher','「매체 대 매체 놀이」의 질문 카드 「글자, 사진, 도표, 그림, 동영상 가운데에서 무엇으로 생각을 전달하는 것이 효과적인가요?」에 맞게, 온라인 대화와 편지를 비교하여 대답하세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C57","difficulty":4,"kind":"essay","stem":"「매체 대 매체 놀이」의 질문 카드 「글자, 사진, 도표, 그림, 동영상 가운데에서 무엇으로 생각을 전달하는 것이 효과적인가요?」에 맞게, 온라인 대화와 편지를 비교하여 대답하세요.","answer_guide":{"answer":"예: 온라인 대화에서는 그림이나 음성, 지도, 동영상 같은 자료를 함께 보낼 수 있어 소통하려는 내용을 더 효과적으로 전할 수 있다. 편지는 글자로 마음을 차분히 정리해 전하기에 알맞다.","scoring_points":["질문 카드에 맞게 대답했는가","온라인 대화의 특성을 썼는가","편지의 특성을 견주어 썼는가"]},"explanation":["질문이 무엇을 묻는지 먼저 봐요.","온라인 대화는 여러 자료를 함께 쓸 수 있어요.","편지는 글로 마음을 정리해 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#1','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C1',1,'mc','auto','『국어』 249쪽 「정리하기」의 스스로 확인하기 네 물음은 이 단원의 어떤 두 가지 공부를 살펴보나요?',ARRAY['K4-2-u5-X01']::text[],false,'{"seq":1,"concept":"K4-2-u5-C1","difficulty":1,"kind":"mc","stem":"『국어』 249쪽 「정리하기」의 스스로 확인하기 네 물음은 이 단원의 어떤 두 가지 공부를 살펴보나요?","options":[{"t":"온라인 대화 예절을 지키며 대화하기 · 읽는 이를 생각하며 편지 쓰기","correct":true},{"t":"토의하기 · 광고 만들기","mis":"K4-2-u5-X01"},{"t":"그림말 만들기 · 편지봉투 꾸미기","mis":"K4-2-u5-X01"}],"explanation":["앞의 두 물음은 온라인 대화 예절이에요.","뒤의 두 물음은 편지 쓰기예요.","두 소단원을 스스로 확인해요."],"asset":{"type":"passage","lines":["온라인 대화에서 지켜야 할 예절을 알 수 있나요? ○○○","예절을 지키며 온라인 대화를 할 수 있나요? ○○○","마음을 잘 나타낼 수 있는 표현을 사용해 편지를 쓸 수 있나요? ○○○","읽는 이의 마음이 어떠할지 짐작하며 편지를 쓸 수 있나요? ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"스스로 확인하기 — 『국어』 249쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#2','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C2',1,'mc','auto','손 편지와 휴대 전화 메시지로 마음을 전할 때 다른 점을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X02','K4-2-u5-X03','K4-2-u5-X36']::text[],false,'{"seq":2,"concept":"K4-2-u5-C2","difficulty":1,"kind":"mc","stem":"손 편지와 휴대 전화 메시지로 마음을 전할 때 다른 점을 바르게 말한 것은 무엇인가요?","options":[{"t":"손 편지는 보내는 사람의 예의와 정성을 보여 주고, 메시지는 내용을 빠르게 전하며 그림말로 감정을 나타낼 수 있다","correct":true},{"t":"메시지로 전한 마음은 진짜 마음이 아니다","mis":"K4-2-u5-X02"},{"t":"손 편지에는 예절이 필요하지만 메시지에는 필요 없다","mis":"K4-2-u5-X03"},{"t":"손 편지가 메시지보다 더 빠르게 닿는다","mis":"K4-2-u5-X36"}],"explanation":["손 편지는 정성과 예의를 보여 줄 수 있어요.","메시지는 빠르고 그림말로 감정도 나타내요.","두 방법 모두 같은 마음을 전할 수 있어요."],"asset":{"type":"passage","lines":["소중한 친구에게","안녕? 규리야.","이번 주 토요일이 내 생일이어서 친구들을 초대하려고 해.","(간추림) 생일잔치에 와 준다면 정말 기쁠 거라며 토요일 1시에","(간추림) 우리 집에 올 수 있는지 알려 달라고 했다.","20○○년 ○○월 ○○일 미나가"],"title":"미나가 규리에게 쓴 손 편지 — 『국어』 225쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#3','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C8',1,'mc','auto','『국어』 228쪽에서 예로 든 온라인 대화의 종류가 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X10']::text[],false,'{"seq":3,"concept":"K4-2-u5-C8","difficulty":1,"kind":"mc","stem":"『국어』 228쪽에서 예로 든 온라인 대화의 종류가 아닌 것은 무엇인가요?","options":[{"t":"혼자 쓰는 일기","correct":true},{"t":"온라인 대화방","mis":"K4-2-u5-X10"},{"t":"영상 통화","mis":"K4-2-u5-X10"},{"t":"영상 회의","mis":"K4-2-u5-X10"}],"explanation":["온라인 대화방, 쪽지, 영상 통화, 영상 회의는 온라인 대화예요.","모두 상대와 디지털 기기로 주고받아요.","혼자 쓰는 일기는 대화가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#4','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C22',1,'mc','auto','『국어』 233쪽에서 정한 예절에 따라, 온라인 대화방에 상대를 초대할 때 할 일은 무엇인가요?',ARRAY['K4-2-u5-X21','K4-2-u5-X23']::text[],false,'{"seq":4,"concept":"K4-2-u5-C22","difficulty":1,"kind":"mc","stem":"『국어』 233쪽에서 정한 예절에 따라, 온라인 대화방에 상대를 초대할 때 할 일은 무엇인가요?","options":[{"t":"상대의 의사를 확인한다","correct":true},{"t":"묻지 않고 여러 번 초대한다","mis":"K4-2-u5-X21"},{"t":"초대한 뒤 답할 때까지 계속 말을 건다","mis":"K4-2-u5-X23"}],"explanation":["묻지 않고 초대하면 상대가 속상해요.","먼저 들어올지 물어봐요.","상대의 뜻을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#5','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C38',1,'mc','auto','편지의 짜임 가운데 편지를 쓴 까닭을 밝히고 전하고자 하는 마음을 표현하는 부분은 무엇인가요?',ARRAY['K4-2-u5-X38','K4-2-u5-X39']::text[],false,'{"seq":5,"concept":"K4-2-u5-C38","difficulty":1,"kind":"mc","stem":"편지의 짜임 가운데 편지를 쓴 까닭을 밝히고 전하고자 하는 마음을 표현하는 부분은 무엇인가요?","options":[{"t":"전하고 싶은 말","correct":true},{"t":"첫인사","mis":"K4-2-u5-X38"},{"t":"추신","mis":"K4-2-u5-X39"},{"t":"쓴 날짜","mis":"K4-2-u5-X38"}],"explanation":["첫인사는 안부를 묻는 부분이에요.","전하고 싶은 말에 쓴 까닭과 마음을 써요.","추신은 보탤 말이 있을 때만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#6','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C40',1,'mc','auto','웃어른께 편지를 쓸 때 쓴 사람의 이름 뒤에 붙이는 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X40','K4-2-u5-X51']::text[],false,'{"seq":6,"concept":"K4-2-u5-C40","difficulty":1,"kind":"mc","stem":"웃어른께 편지를 쓸 때 쓴 사람의 이름 뒤에 붙이는 말로 알맞은 것은 무엇인가요?","options":[{"t":"올림","correct":true},{"t":"씀","mis":"K4-2-u5-X40"},{"t":"에게","mis":"K4-2-u5-X51"}],"explanation":["석원이는 할머니께 ‘손자 지석원 올림’이라고 썼어요.","웃어른께는 ‘올림’이나 ‘드림’을 써요.","친구에게는 ‘씀’을 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#7','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C58',1,'mc','auto','“달이 참 밝다.”에서 ‘밝다’의 바른 소리는 무엇인가요?',ARRAY['K4-2-u5-X58','K4-2-u5-X59']::text[],false,'{"seq":7,"concept":"K4-2-u5-C58","difficulty":1,"kind":"mc","stem":"“달이 참 밝다.”에서 ‘밝다’의 바른 소리는 무엇인가요?","options":[{"t":"[박따]","correct":true},{"t":"[발따]","mis":"K4-2-u5-X58"},{"t":"[밝따]","mis":"K4-2-u5-X59"}],"explanation":["겹받침 ㄺ은 보통 [ㄱ]만 소리 나요.","‘밝다’ 뒤에는 ㄷ이 와요.","그래서 [박따]예요."],"asset":{"type":"passage","lines":["[대화 가] “어항의 물이 참 맑다.”","         “내가 아침에 물을 갈았더니 맑고 깨끗해졌어.”","[대화 나] “달이 참 밝다.” “보름달이라서 밝게 빛나는구나!”"],"numbered":false,"title":"기초 다지기 1 — 『국어』 250쪽","hi":["맑다","맑고","밝다","밝게"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#8','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C56',1,'mc','auto','비밀 친구 활동을 마치는 마지막 날에 하는 일은 무엇인가요?',ARRAY['K4-2-u5-X52','K4-2-u5-X56']::text[],false,'{"seq":8,"concept":"K4-2-u5-C56","difficulty":1,"kind":"mc","stem":"비밀 친구 활동을 마치는 마지막 날에 하는 일은 무엇인가요?","options":[{"t":"각자 자신이 누구의 비밀 친구였는지 밝힌다","correct":true},{"t":"받은 편지를 모두 돌려준다","mis":"K4-2-u5-X52"},{"t":"비밀 친구를 끝까지 밝히지 않는다","mis":"K4-2-u5-X56"}],"explanation":["비밀 친구 활동은 일주일쯤 기간을 정해 해요.","그동안은 이름을 밝히지 않아요.","마지막 날에 누구의 비밀 친구였는지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#9','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C65',2,'mc','auto','광고 나에서 악성 댓글을 ‘말’로 해 보라고 한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X19']::text[],false,'{"seq":9,"concept":"K4-2-u5-C65","difficulty":2,"kind":"mc","stem":"광고 나에서 악성 댓글을 ‘말’로 해 보라고 한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"얼굴을 마주 보거나 이름을 밝히면 하기 어려운 비난이나 욕설을 온라인에서는 쉽게 쓴다는 것을 돌아보게 하려고","correct":true},{"t":"댓글보다 말이 더 빠르기 때문에","mis":"K4-2-u5-X19"},{"t":"마이크를 쓰면 목소리가 커지기 때문에","mis":"K4-2-u5-X19"}],"explanation":["온라인에서는 얼굴을 마주 보지 않고 이름을 밝히지 않을 수 있어요.","그래서 악성 댓글을 쉽게 써요.","직접 말로 해 보면 얼마나 부끄러운 말인지 알 수 있어요."],"asset":{"type":"passage","lines":["[광고 가] 윗글이 맑아야 아랫글이 맑다","[광고 나] 당신이 쓴 악성 댓글 ‘말’로 해 보시겠습니까?","         (마이크에 ‘bsf9****’처럼 일부를 가린 아이디가 적혀 있다.)","         생각이 달라서 비난 한 줄 / 스트레스 때문에 욕설 한 줄","         무심코 쓴 당신의 댓글 한 줄 입에 달기 부끄럽지 않으신가요?"],"numbered":false,"title":"공익 광고 두 편 — 『국어』 230쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#10','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C31',2,'mc','auto','『국어활동』 71쪽 현지네 반 대화방에서 친구 3에게 필요한 대화 예절은 무엇인가요?',ARRAY['K4-2-u5-X21','K4-2-u5-X20']::text[],false,'{"seq":10,"concept":"K4-2-u5-C31","difficulty":2,"kind":"mc","stem":"『국어활동』 71쪽 현지네 반 대화방에서 친구 3에게 필요한 대화 예절은 무엇인가요?","options":[{"t":"상대에게 불쾌감을 주지 않도록 주의하고, 대화를 마치고 나가기 전에 양해를 구한다","correct":true},{"t":"대화방에 초대할 때 먼저 묻는다","mis":"K4-2-u5-X21"},{"t":"사진은 허락을 받고 올린다","mis":"K4-2-u5-X20"}],"explanation":["친구 3은 “대충 하자니까. 너희끼리 가!”라고 했어요.","그리고 말없이 대화방을 나갔어요.","불쾌감을 주지 않고 양해를 구해야 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"(간식 그림말만 잇따라 보냄)"},{"who":"친구 2","text":"도서관에 같이 갈 수 있는 사람 있어?"},{"who":"현지","text":"나랑 가자! 언제 갈까?"},{"who":"친구 4","text":"수업 끝나고 가자."},{"who":"친구 3","text":"대충 하자니까. 너희끼리 가!"},{"who":"알림","text":"친구 3 님이 나갔습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#11','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C28',2,'mc','auto','『국어』 235쪽 계획표의 「온라인 대화 방식」 칸에 나온 것이 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":11,"concept":"K4-2-u5-C28","difficulty":2,"kind":"mc","stem":"『국어』 235쪽 계획표의 「온라인 대화 방식」 칸에 나온 것이 아닌 것은 무엇인가요?","options":[{"t":"손 편지","correct":true},{"t":"누리 소통망","mis":"K4-2-u5-X27"},{"t":"영상 통화","mis":"K4-2-u5-X27"},{"t":"전자 우편","mis":"K4-2-u5-X27"}],"explanation":["온라인 대화 방식에는 누리 소통망, 영상 통화, 전자 우편이 있어요.","온라인 게시판, 온라인 대화방도 있어요.","손 편지는 온라인 대화가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#12','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C61',2,'mc','auto','석원이가 할머니께 전한 기쁜 소식은 무엇인가요?',ARRAY['K4-2-u5-X37']::text[],false,'{"seq":12,"concept":"K4-2-u5-C61","difficulty":2,"kind":"mc","stem":"석원이가 할머니께 전한 기쁜 소식은 무엇인가요?","options":[{"t":"독후감 쓰기 대회에서 우수상을 받았다","correct":true},{"t":"텃밭에 고구마를 심었다","mis":"K4-2-u5-X37"},{"t":"할머니 댁 가까이로 이사를 간다","mis":"K4-2-u5-X37"}],"explanation":["“그리고 기쁜 소식이 있어요.”라고 했어요.","독후감 쓰기 대회에서 우수상을 받았어요.","할머니께서 기뻐하실 소식이에요."],"asset":{"type":"passage","lines":["할머니, 고구마를 보내 주셔서 고맙습니다.","(간추림) 할머니께서 텃밭에서 정성 들여 직접 키우셔서 고구마가 더 맛있다고 했다.","그리고 기쁜 소식이 있어요. 제가 독후감 쓰기 대회에서 우수상을 받았어요!","(간추림) 늘 아끼고 사랑해 주시는 할머니께 마음 깊이 감사하다고 했다.","(간추림) 할머니가 많이 보고 싶어서 다음 달 생신 때 찾아뵙겠다고 했다."],"title":"석원이의 편지 가운데 「전하고 싶은 말」 — 『국어』 239쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#13','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C36',2,'mc','auto','편지 쓰기로 마음을 전할 때의 좋은 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u5-X36']::text[],false,'{"seq":13,"concept":"K4-2-u5-C36","difficulty":2,"kind":"mc","stem":"편지 쓰기로 마음을 전할 때의 좋은 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"언제나 다른 방법보다 빠르게 닿는다","correct":true},{"t":"정성을 담게 되어 상대에게 감동과 힘을 줄 수 있다","mis":"K4-2-u5-X36"},{"t":"마음을 천천히 정리하며 감정을 진솔하게 표현할 수 있다","mis":"K4-2-u5-X36"},{"t":"특별한 추억으로 기억에 남도록 할 수 있다","mis":"K4-2-u5-X36"}],"explanation":["편지는 정성을 담아 감동을 줄 수 있어요.","천천히 정리하며 진솔하게 쓸 수 있어요.","빠르게 닿는 것은 편지의 좋은 점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#14','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C44',2,'mc','auto','소방관님께 고마운 마음을 전하는 편지를 계획해요. 「마음을 나타내는 표현」 칸에 들어갈 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":14,"concept":"K4-2-u5-C44","difficulty":2,"kind":"mc","stem":"소방관님께 고마운 마음을 전하는 편지를 계획해요. 「마음을 나타내는 표현」 칸에 들어갈 말로 알맞은 것은 무엇인가요?","options":[{"t":"고맙습니다.","correct":true},{"t":"소방관님","mis":"K4-2-u5-X27"},{"t":"안전 교육","mis":"K4-2-u5-X27"}],"explanation":["‘소방관님’은 마음을 전할 사람이에요.","‘안전 교육’은 있었던 일이에요.","마음을 나타내는 표현은 ‘고맙습니다.’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#15','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C46',2,'match','auto','『국어』 242쪽 (1)의 상황과 전하고 싶은 마음을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K4-2-u5-C46","difficulty":2,"kind":"match","stem":"『국어』 242쪽 (1)의 상황과 전하고 싶은 마음을 알맞게 이으세요.","pairs":[{"l":"동생이 줄넘기 대회에서 상을 받았다","r":"축하"},{"l":"친구와 의견이 맞지 않아 다투었다","r":"사과"},{"l":"편찮으신 할아버지께 병문안을 갔다","r":"위로"},{"l":"소방관님들이 안전 교육을 해 주셨다","r":"감사"}],"mis":"K4-2-u5-X46","explanation":["좋은 일에는 축하를 전해요.","내가 잘못한 일에는 사과를 전해요.","힘든 일에는 위로를, 도움을 받으면 감사를 전해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"동생이 줄넘기 대회에서 상을 받았다. 축하해 주고 싶었다."},{"who":"친구 2","text":"친구와 의견이 맞지 않아 다투었는데 미안한 마음이 들었다."},{"who":"친구 3","text":"편찮으신 할아버지를 뵙기 위해 병문안을 갔다. 어서 건강을 회복하셨으면 좋겠다."},{"who":"친구 4","text":"소방관님들이 안전 교육을 해 주셔서 고마운 마음이 들었다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#16','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C60',2,'mc','auto','“시험을 망쳤어. ㅠㅠㅠㅠㅠ”를 『국어』 250쪽처럼 고쳐 쓴 것은 무엇인가요?',ARRAY['K4-2-u5-X61']::text[],false,'{"seq":16,"concept":"K4-2-u5-C60","difficulty":2,"kind":"mc","stem":"“시험을 망쳤어. ㅠㅠㅠㅠㅠ”를 『국어』 250쪽처럼 고쳐 쓴 것은 무엇인가요?","options":[{"t":"“시험을 망쳤어. 속상해.”","correct":true},{"t":"“시험 망침 ㅠㅠ”","mis":"K4-2-u5-X61"},{"t":"“ㅠㅠㅠㅠㅠㅠㅠㅠ”","mis":"K4-2-u5-X61"}],"explanation":["같은 글자를 되풀이하면 뜻이 흐려져요.","마음을 말로 분명하게 나타내요.","“속상해.”처럼 고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#17','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C28',3,'mc','auto','온라인 대화 관찰 기록표의 「계획하기」에서 살피는 것은 무엇인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":17,"concept":"K4-2-u5-C28","difficulty":3,"kind":"mc","stem":"온라인 대화 관찰 기록표의 「계획하기」에서 살피는 것은 무엇인가요?","options":[{"t":"온라인 대화를 할 상대를 고려하고, 좋은 점과 문제점을 생각해 매체를 골랐는가","correct":true},{"t":"상대의 허락 없이 대화를 끊지 않았는가","mis":"K4-2-u5-X27"},{"t":"바른 말, 고운 말을 썼는가","mis":"K4-2-u5-X27"}],"explanation":["계획하기는 대화를 시작하기 전의 일이에요.","상대를 생각하며 매체를 골라요.","대화를 끊지 않기, 바른 말은 참여 태도예요."],"asset":{"type":"passage","lines":["계획하기 — 상대를 고려하여 매체를 선택했는가? · 좋은 점과 문제점을 고려했는가?","온라인 대화 하기 — 상대가 흥미를 느낄 만한 내용인가? ·","        주제와 관련 있는 내용을 이야기했는가? · 사실과 다른 내용을 말하지 않았는가?","참여 태도 — 주제와 관련 없는 말이나 그림말을 반복하지 않았는가? ·","        불쾌감을 주지 않았는가? · 바른 말, 고운 말을 썼는가? ·","        상대의 허락 없이 대화를 끊지 않았는가? · 적극적으로 참여했는가?","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"온라인 대화 관찰 기록표 (평가 자료 1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#18','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C62',3,'mc','auto','이황이 손자에게 쓴 편지에서 읽는 사람은 누구이고, 편지를 쓴 목적은 무엇인가요?',ARRAY['K4-2-u5-X37']::text[],false,'{"seq":18,"concept":"K4-2-u5-C62","difficulty":3,"kind":"mc","stem":"이황이 손자에게 쓴 편지에서 읽는 사람은 누구이고, 편지를 쓴 목적은 무엇인가요?","options":[{"t":"손자 안도 — 공부에 힘쓰라고 당부하려고","correct":true},{"t":"서울 사는 두 젊은이 — 공부를 가르쳐 주겠다고 알리려고","mis":"K4-2-u5-X37"},{"t":"손자의 아내 — 생일 선물을 더 보내 달라고 하려고","mis":"K4-2-u5-X37"}],"explanation":["편지 첫 줄에 ‘손자 안도에게’라고 썼어요.","세월을 허투루 보내지 말고 힘써 공부하라고 했어요.","읽는 사람과 목적을 함께 찾아요."],"asset":{"type":"passage","lines":["손자 안도에게","(간추림) 산속 절에 머물며 공부하기로 했다는 소식을 듣고 좋은 일이라고 했다.","세월은 물처럼 흐른단다. 그러니 허투루 보내지 말고 천 번 만 번 힘써서 공부하거라.","(간추림) 흐지부지 보내면 공부가 흩어질까 걱정스럽다고 했다.","네가 얼마나 보고 싶은지 모른다.","(간추림) 생일 선물을 가져온 마음은 고맙지만 너희 얼굴을 보는 것이 더 기쁘다고 했다.","1568년 퇴계 이황"],"title":"이황이 손자에게 쓴 편지 (평가 자료 2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#19','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C62',3,'blank','auto','안창호가 아들 필립에게 쓴 편지예요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#20','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C42',3,'mc','auto','고쳐 쓸 곳이 있는 편지에서 “제 마음 아시죠? 항상 고맙습니다.”를 고칠 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X49']::text[],false,'{"seq":20,"concept":"K4-2-u5-C42","difficulty":3,"kind":"mc","stem":"고쳐 쓸 곳이 있는 편지에서 “제 마음 아시죠? 항상 고맙습니다.”를 고칠 점으로 알맞은 것은 무엇인가요?","options":[{"t":"무엇이 고마웠는지 알 수 있게 있었던 일을 구체적으로 쓴다","correct":true},{"t":"“항상”을 “항상항상”으로 바꾼다","mis":"K4-2-u5-X48"},{"t":"그대로 두어도 마음이 다 전해진다","mis":"K4-2-u5-X49"}],"explanation":["“제 마음 아시죠?”만으로는 무엇이 고마운지 알 수 없어요.","고마운 마음을 느낀 일을 밝혀요.","같은 말을 되풀이한다고 구체적이 되지 않아요."],"asset":{"type":"passage","lines":["할머니에게","할머니, 저 석원이예요. 할머니에게 감사의 마음을 전하고 싶어서","이렇게 편지를 썼어요. 제 마음 아시죠? 항상 고맙습니다.","다음 주면 할머니의 생일이네요. 가족과 할머니 집으로 갈게요.","할머니, 사랑해요.","지석원 씀"],"title":"고쳐 쓸 곳이 있는 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#21','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C63',3,'blank','auto','토의 순서예요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#22','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C20',3,'mc','auto','채팅방에서 언어폭력에 속하는 행동으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X67','K4-2-u5-X34']::text[],false,'{"seq":22,"concept":"K4-2-u5-C20","difficulty":3,"kind":"mc","stem":"채팅방에서 언어폭력에 속하는 행동으로 알맞은 것은 무엇인가요?","options":[{"t":"한 명을 소외시키고 따로 채팅방을 만들어 흉보기","correct":true},{"t":"친구의 말에 공감하는 그림말을 알맞게 보내기","mis":"K4-2-u5-X67"},{"t":"대화를 마치기 전에 양해를 구하고 나가기","mis":"K4-2-u5-X34"}],"explanation":["소문 퍼뜨리기, 여럿이 욕하기, 소외시키기는 언어폭력이에요.","친구의 경계선을 넘고 피해를 주는 일이에요.","공감하는 그림말과 양해 구하기는 예절이에요."],"asset":{"type":"passage","lines":["(간추림) 채팅방에서 친구에 대한 안 좋은 소문을 퍼뜨리는 것,","(간추림) 한 명을 초대한 뒤 여러 명이 번갈아서 욕하고 괴롭히는 것,","(간추림) 한 명을 소외시키고 따로 채팅방을 만들어 흉보는 것은 언어폭력이다.","(간추림) 이런 일을 당했다면 대화 내용이 있는 화면을 캡처하고","(간추림) 부모님이나 선생님께 바로 도움을 구한다."],"title":"온라인 채팅방 대화법 — 언어폭력 조심하기 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#23','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C33',4,'essay','teacher','『국어』 237쪽 점검표의 네 물음 가운데 자신이 가장 지키기 어렵다고 생각하는 것을 하나 고르고, 그 까닭과 다음 온라인 대화에서 지킬 방법을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u5-C33","difficulty":4,"kind":"essay","stem":"『국어』 237쪽 점검표의 네 물음 가운데 자신이 가장 지키기 어렵다고 생각하는 것을 하나 고르고, 그 까닭과 다음 온라인 대화에서 지킬 방법을 쓰세요.","answer_guide":{"answer":"예: 「자료를 공유하기 전에 자료의 내용이 사실인지 확인했나요?」 — 재미있는 이야기를 보면 빨리 알리고 싶어서 확인하지 않고 올릴 때가 있다. 다음에는 올리기 전에 믿을 만한 곳에서 한 번 더 찾아보고 올리겠다.","scoring_points":["점검표 물음 하나를 골랐는가","지키기 어려운 까닭을 썼는가","다음 대화에서 지킬 방법을 썼는가"]},"explanation":["네 물음을 하나씩 읽어 봐요.","내가 어려운 까닭을 솔직하게 써요.","다음에 어떻게 할지 방법을 정해요."],"asset":{"type":"passage","lines":["대화의 주제와 관련 없는 말이나 그림말을 반복해서 사용하지 않았나요? ○○○","상대가 보이지 않는 상황에서도 예의를 갖추어 대화했나요? ○○○","자료를 공유하기 전에 자료의 내용이 사실인지 확인했나요? ○○○","사진이나 동영상 같은 자료를 공유하기 전에 상대의 허락을 구했나요? ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"예절을 지키며 온라인 대화를 했는지 스스로 확인하기 — 『국어』 237쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#24','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C62',4,'essay','teacher','안창호가 아들에게 쓴 편지를 읽고, 읽는 사람, 편지를 쓴 목적, 아버지가 전하려는 마음과 그 마음이 드러난 표현을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u5-C62","difficulty":4,"kind":"essay","stem":"안창호가 아들에게 쓴 편지를 읽고, 읽는 사람, 편지를 쓴 목적, 아버지가 전하려는 마음과 그 마음이 드러난 표현을 쓰세요.","answer_guide":{"answer":"예: 읽는 사람 — 아들 필립 / 목적 — 다친 아들을 걱정하고, 한 학년 올라간 것을 축하하며, 좋은 사람이 되라고 당부하려고 / 마음 — 축하하고 기뻐하는 마음, 표현 — “한 학년 올라가게 된 것을 축하한다. 아버지는 무척 기쁘구나.”","scoring_points":["읽는 사람을 썼는가","편지를 쓴 목적을 썼는가","전하려는 마음과 그 마음이 드러난 표현을 찾아 썼는가"]},"explanation":["받는 사람을 먼저 찾아요.","무엇 때문에 썼는지 목적을 정리해요.","마음이 드러난 문장을 찾아 그대로 옮겨요."],"asset":{"type":"passage","lines":["사랑하는 아들 필립","(간추림) 넘어져 팔을 다쳤다는 소식에 매우 걱정되니 팔이 나으면 바로 알리라고 했다.","한 학년 올라가게 된 것을 축하한다. 아버지는 무척 기쁘구나.","(간추림) 좋은 사람이 되려면 진실하고 깨끗해야 하며,","(간추림) 좋은 친구를 가려 사귀고 좋은 책을 골라 꾸준히 읽으라고 했다.","1920년 8월 3일 홍콩에서","아버지가"],"title":"안창호가 아들에게 쓴 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_a#25','kor',4,2,'u5','','tb_g4_2_kor_u5_review_a','unit_review','K4-2-u5-C4',4,'essay','teacher','이 단원에서 배운 온라인 대화와 편지를 견주어, 각각 어떤 상황에 알맞은지 한 가지씩 쓰고 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u5-C4","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 온라인 대화와 편지를 견주어, 각각 어떤 상황에 알맞은지 한 가지씩 쓰고 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 온라인 대화 — 외국에 사는 친척과 연락할 때, 멀리 떨어져 있어도 빠르게 이야기를 주고받을 수 있기 때문이다. 편지 — 고마운 선생님께 마음을 전할 때, 천천히 생각하며 정성을 담아 쓸 수 있고 오래 기억에 남기 때문이다.","scoring_points":["온라인 대화에 알맞은 상황과 까닭을 썼는가","편지에 알맞은 상황과 까닭을 썼는가","어느 하나가 늘 더 좋다고 하지 않았는가"]},"explanation":["두 방법의 좋은 점이 달라요.","상황과 상대를 생각해요.","그 상황에 알맞은 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#1','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C1',1,'mc','auto','이 단원 「오가는 마음」의 학습 목표로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X13','K4-2-u5-X35']::text[],false,'{"seq":1,"concept":"K4-2-u5-C1","difficulty":1,"kind":"mc","stem":"이 단원 「오가는 마음」의 학습 목표로 알맞은 것은 무엇인가요?","options":[{"t":"상황에 알맞은 예절을 생각하며 마음 표현하기","correct":true},{"t":"온라인 대화를 줄이는 방법 알기","mis":"K4-2-u5-X13"},{"t":"편지의 역사 외우기","mis":"K4-2-u5-X35"}],"explanation":["온라인 대화와 편지로 마음을 주고받아요.","두 가지 모두 상황과 상대에 맞는 예절이 필요해요.","상황에 알맞은 예절을 생각하며 마음을 표현해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#2','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C3',1,'mc','auto','다음 가운데 마음을 전하는 방법이라고 할 수 없는 것은 무엇인가요?',ARRAY['K4-2-u5-X04']::text[],false,'{"seq":2,"concept":"K4-2-u5-C3","difficulty":1,"kind":"mc","stem":"다음 가운데 마음을 전하는 방법이라고 할 수 없는 것은 무엇인가요?","options":[{"t":"전하고 싶은 마음을 마음속으로만 생각한다","correct":true},{"t":"전화로 대화한다","mis":"K4-2-u5-X04"},{"t":"편지를 써서 건넨다","mis":"K4-2-u5-X04"},{"t":"영상 대화를 한다","mis":"K4-2-u5-X04"}],"explanation":["만나서 대화하기, 전화, 편지, 영상 대화 모두 마음을 전하는 방법이에요.","마음속으로만 생각하면 상대는 알 수 없어요.","마음은 표현해야 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#3','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C10',1,'blank','auto','온라인 대화와 직접 만나서 나누는 대화를 비교한 표예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u5-X11','K4-2-u5-X10']::text[],false,'{"seq":3,"concept":"K4-2-u5-C10","difficulty":1,"kind":"blank","stem":"온라인 대화와 직접 만나서 나누는 대화를 비교한 표예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"분명하지 않을 수 있다","correct":true},{"t":"언제나 분명하다","mis":"K4-2-u5-X11"},{"t":"같은 시간과 장소에 있어야 한다","mis":"K4-2-u5-X10"}],"explanation":["직접 만나서 나누는 대화는 상대가 분명해요.","온라인 대화는 상대가 누구인지 분명하지 않을 때도 있어요.","‘언제나’가 아니라 ‘~할 수 있다’예요."],"asset":{"type":"passage","lines":["구분 | 온라인 대화 | 직접 만나서 나누는 대화","디지털 기기의 사용 | 사용한다 | 사용하지 않는다","시간과 장소 | 같은 시간과 장소에 있지 않아도 된다 | 있어야 한다","대화 상대 | (          ) | 분명하다"],"title":"온라인 대화의 특성 정리 — 『국어』 229쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#4','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C21',1,'mc','auto','다른 사람의 사진이나 동영상을 대화방에 올리고 싶을 때 지켜야 할 예절은 무엇인가요?',ARRAY['K4-2-u5-X20']::text[],false,'{"seq":4,"concept":"K4-2-u5-C21","difficulty":1,"kind":"mc","stem":"다른 사람의 사진이나 동영상을 대화방에 올리고 싶을 때 지켜야 할 예절은 무엇인가요?","options":[{"t":"허락 없이 공유하지 않는다","correct":true},{"t":"재미있는 사진이면 그냥 올린다","mis":"K4-2-u5-X20"},{"t":"올린 뒤에 허락을 받는다","mis":"K4-2-u5-X20"}],"explanation":["사진에는 그 사람의 얼굴과 정보가 담겨 있어요.","올리기 전에 허락을 받아요.","허락 없이 올리면 초상권을 침해할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#5','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C38',1,'mc','auto','편지의 첫인사에 들어갈 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X38','K4-2-u5-X39']::text[],false,'{"seq":5,"concept":"K4-2-u5-C38","difficulty":1,"kind":"mc","stem":"편지의 첫인사에 들어갈 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"받을 사람의 안부를 묻는 말","correct":true},{"t":"편지를 쓴 날짜","mis":"K4-2-u5-X38"},{"t":"다 쓴 뒤 보태고 싶은 말","mis":"K4-2-u5-X39"}],"explanation":["석원이는 “건강하게 잘 지내고 계시지요?” 하고 안부를 물었어요.","계절 인사를 넣어도 좋아요.","날짜와 추신은 끝에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#6','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C51',1,'mc','auto','친구에게 보내는 편지봉투에 받는 사람을 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X41','K4-2-u5-X50']::text[],false,'{"seq":6,"concept":"K4-2-u5-C51","difficulty":1,"kind":"mc","stem":"친구에게 보내는 편지봉투에 받는 사람을 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"‘○○○ 앞’이나 ‘○○○에게’처럼 쓴다","correct":true},{"t":"‘○○○ 귀하’처럼 쓴다","mis":"K4-2-u5-X41"},{"t":"받는 사람은 쓰지 않는다","mis":"K4-2-u5-X50"}],"explanation":["받는 사람이 친구나 아랫사람이면 ‘앞’, ‘에게’를 써요.","높여야 할 때에는 ‘귀하’, ‘님께’를 써요.","받는 사람은 오른쪽 아래에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#7','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C58',1,'mc','auto','“내가 아침에 물을 갈았더니 맑고 깨끗해졌어.”에서 ‘맑고’의 바른 소리는 무엇인가요?',ARRAY['K4-2-u5-X58','K4-2-u5-X59']::text[],false,'{"seq":7,"concept":"K4-2-u5-C58","difficulty":1,"kind":"mc","stem":"“내가 아침에 물을 갈았더니 맑고 깨끗해졌어.”에서 ‘맑고’의 바른 소리는 무엇인가요?","options":[{"t":"[말꼬]","correct":true},{"t":"[막꼬]","mis":"K4-2-u5-X58"},{"t":"[맑꼬]","mis":"K4-2-u5-X59"}],"explanation":["ㄺ 다음에 자음자 ㄱ이 왔어요.","이때 ㄺ은 [ㄹ]로 소리 나요.","그래서 [말꼬]예요."],"asset":{"type":"passage","lines":["[대화 가] “어항의 물이 참 맑다.”","         “내가 아침에 물을 갈았더니 맑고 깨끗해졌어.”","[대화 나] “달이 참 밝다.” “보름달이라서 밝게 빛나는구나!”"],"numbered":false,"title":"기초 다지기 1 — 『국어』 250쪽","hi":["맑다","맑고","밝다","밝게"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#8','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C53',1,'mc','auto','『국어』 248쪽에서 우리 반이 할 활동을 정할 때 함께 살펴볼 것은 무엇인가요?',ARRAY['K4-2-u5-X53','K4-2-u5-X61']::text[],false,'{"seq":8,"concept":"K4-2-u5-C53","difficulty":1,"kind":"mc","stem":"『국어』 248쪽에서 우리 반이 할 활동을 정할 때 함께 살펴볼 것은 무엇인가요?","options":[{"t":"「이런 활동 어때요」에 소개된 활동","correct":true},{"t":"지난 단원의 시험 문제","mis":"K4-2-u5-X53"},{"t":"친구들이 좋아하는 그림말","mis":"K4-2-u5-X61"}],"explanation":["『국어』 246~247쪽에 활동 두 가지가 소개되어 있어요.","그 활동을 살펴보며 우리 반 활동을 정해요.","성취기준에 알맞은 활동을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#9','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C16',2,'mc','auto','대화 주제와 관련 없는 그림말만 잔뜩 보내면 어떤 일이 생길 수 있나요?',ARRAY['K4-2-u5-X16','K4-2-u5-X61']::text[],false,'{"seq":9,"concept":"K4-2-u5-C16","difficulty":2,"kind":"mc","stem":"대화 주제와 관련 없는 그림말만 잔뜩 보내면 어떤 일이 생길 수 있나요?","options":[{"t":"하려는 말을 정확히 알 수 없고, 성의 없어 보이기도 한다","correct":true},{"t":"대화가 더 빨리 끝나 모두 좋아한다","mis":"K4-2-u5-X16"},{"t":"그림말을 많이 쓸수록 마음이 잘 전해진다","mis":"K4-2-u5-X61"}],"explanation":["상황 가의 대화방에서는 준비물을 묻는 말에 답이 오지 않았어요.","그림말만으로는 뜻을 알기 어려워요.","그림말은 공감할 때 알맞게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#10','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C31',2,'mc','auto','『국어활동』 71쪽 2번 예시 답안처럼 현지네 반 친구의 말을 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u5-X61']::text[],false,'{"seq":10,"concept":"K4-2-u5-C31","difficulty":2,"kind":"mc","stem":"『국어활동』 71쪽 2번 예시 답안처럼 현지네 반 친구의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"“난 바쁨.” → “내일 바쁜 일이 있는데 인터넷으로 찾아봐도 될까?”","correct":true},{"t":"“대충 하자고.” → “대충 하자니까.”","mis":"K4-2-u5-X61"},{"t":"“??????????” → “???”","mis":"K4-2-u5-X61"}],"explanation":["짧게 툭 던지는 말은 상대를 서운하게 해요.","사정을 말하고 상대의 뜻을 물어요.","알아들을 수 있는 말로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#11','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C26',2,'mc','auto','『국어』 234쪽 그림 나처럼 친구들과 자료를 주고받으며 숙제하고 싶을 때 온라인 대화가 편리한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X14','K4-2-u5-X26']::text[],false,'{"seq":11,"concept":"K4-2-u5-C26","difficulty":2,"kind":"mc","stem":"『국어』 234쪽 그림 나처럼 친구들과 자료를 주고받으며 숙제하고 싶을 때 온라인 대화가 편리한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"만나지 않아도 자료를 주고받으며 함께 이야기할 수 있기 때문","correct":true},{"t":"온라인으로 하면 숙제를 하지 않아도 되기 때문","mis":"K4-2-u5-X14"},{"t":"직접 만나서 하는 대화는 이제 필요 없기 때문","mis":"K4-2-u5-X26"}],"explanation":["그림 나의 친구는 동영상이 괜찮을지 친구들에게 물어보려고 해요.","온라인으로 자료를 바로 보여 줄 수 있어요.","만나지 않아도 함께 숙제할 수 있어요."],"asset":{"type":"passage","lines":["[그림 가] 전학 간 친구와 대화하고 싶을 때 — “전학 간 학교는 어때?”","[그림 나] 친구들과 자료를 주고받으며 숙제하고 싶을 때","         — “이 동영상이 괜찮을지 친구들에게 물어봐야겠다.”","[그림 다] 독감에 걸렸을 때 — “독감은 좀 어떠니?”","         “이제 좀 괜찮아졌어요.”"],"numbered":false,"title":"온라인 대화가 편리한 상황 — 『국어』 234쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#12','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C40',2,'mc','auto','석원이의 편지에 나온 낱말 가운데 높임 표현이 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X64']::text[],false,'{"seq":12,"concept":"K4-2-u5-C40","difficulty":2,"kind":"mc","stem":"석원이의 편지에 나온 낱말 가운데 높임 표현이 아닌 것은 무엇인가요?","options":[{"t":"고구마","correct":true},{"t":"계시지요","mis":"K4-2-u5-X64"},{"t":"편찮으시면","mis":"K4-2-u5-X64"},{"t":"찾아뵐게요","mis":"K4-2-u5-X64"}],"explanation":["‘계시다’, ‘편찮으시다’, ‘찾아뵙다’는 높임 표현이에요.","할머니를 높이려고 쓴 말이에요.","‘고구마’는 높임과 상관없는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#13','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C35',2,'mc','auto','「편지의 역사」에서 우리나라 최초의 우체통은 언제 설치되었다고 했나요?',ARRAY['K4-2-u5-X35']::text[],false,'{"seq":13,"concept":"K4-2-u5-C35","difficulty":2,"kind":"mc","stem":"「편지의 역사」에서 우리나라 최초의 우체통은 언제 설치되었다고 했나요?","options":[{"t":"1884년 우정총국이 설립되면서","correct":true},{"t":"전자 우편이 개발된 뒤","mis":"K4-2-u5-X35"},{"t":"종이가 발명되기 전","mis":"K4-2-u5-X35"}],"explanation":["편지가 많아지자 체계적인 우편 업무가 필요해졌어요.","우정총국을 개설하며 근대 우편 제도가 시작되었어요.","그때 최초의 우체통도 설치되었어요."],"asset":{"type":"passage","lines":["(간추림) 점토판, 파피루스, 양피지, 나무를 이용한 목간 등에 편지를 쓰다가","(간추림) 종이가 발명되면서 편지의 이용이 크게 늘었다.","(간추림) 1884년 우정총국이 설립되면서 우리나라 최초의 우체통이 설치되었다.","(간추림) 전화기와 전자 우편이 생긴 뒤 편지를 쓰는 일이 점차 줄었다.","(간추림) 오늘날 편지는 다른 통신 수단이 하지 못하는 진심을 전하는 역할을 한다."],"title":"「편지의 역사」 간추림 — 『국어활동』 스스로 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#14','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C47',2,'mc','auto','편지의 가운데 부분에 들어갈 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X47','K4-2-u5-X38']::text[],false,'{"seq":14,"concept":"K4-2-u5-C47","difficulty":2,"kind":"mc","stem":"편지의 가운데 부분에 들어갈 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"읽는 사람과 함께 겪은 일과 그 일에 대한 생각이나 느낌","correct":true},{"t":"읽는 사람을 부르는 말","mis":"K4-2-u5-X47"},{"t":"쓴 날짜와 쓴 사람","mis":"K4-2-u5-X38"}],"explanation":["부르는 말은 처음에 써요.","가운데에는 쓴 까닭, 겪은 일, 느낌을 써요.","쓴 날짜와 쓴 사람은 끝에 써요."],"asset":{"type":"passage","lines":["처음 — 읽는 사람을 부르는 말 · 안부를 묻는 말 ·","        글쓴이가 어떻게 지내는지 알리는 말 · 계절이나 날씨에 대한 말","가운데 — 편지를 쓴 까닭 · 직접 말로 마음을 전하지 못하는 까닭 ·","        읽는 사람과 함께 겪은 일 · 겪은 일에 대한 생각이나 느낌 ·","        읽는 사람의 입장과 마음을 헤아리는 말 · 앞으로의 다짐","끝 — 읽는 사람에게 바라는 점 · 끝인사 · 쓴 날짜 · 쓴 사람","(덧붙이고 싶은 말은 추신으로 — 필요한 경우에만 쓴다.)"],"numbered":false,"title":"편지의 처음 · 가운데 · 끝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#15','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C48',2,'mc','auto','『국어』 241쪽 「전하고자 하는 마음이 잘 드러나도록 내용을 구체적으로 쓴다」를 바르게 이해한 것은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X49']::text[],false,'{"seq":15,"concept":"K4-2-u5-C48","difficulty":2,"kind":"mc","stem":"『국어』 241쪽 「전하고자 하는 마음이 잘 드러나도록 내용을 구체적으로 쓴다」를 바르게 이해한 것은 무엇인가요?","options":[{"t":"무슨 일이 있었고 그때 어떤 마음이었는지를 읽는 사람이 알 수 있게 쓴다","correct":true},{"t":"같은 말을 여러 번 되풀이해 길게 쓴다","mis":"K4-2-u5-X48"},{"t":"“고마워.” 한마디만 쓴다","mis":"K4-2-u5-X49"}],"explanation":["구체적으로 쓴다는 것은 길게 쓴다는 뜻이 아니에요.","있었던 일과 마음을 함께 써요.","읽는 사람이 그 일을 떠올릴 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#16','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C60',2,'blank','auto','“오늘 날씨 ㄹㅇ 좋다.”를 대화 예절을 생각하며 고쳐 썼어요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#17','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C31',3,'mc','auto','온라인 대화를 평가할 때 먼저 살펴야 할 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X62']::text[],false,'{"seq":17,"concept":"K4-2-u5-C31","difficulty":3,"kind":"mc","stem":"온라인 대화를 평가할 때 먼저 살펴야 할 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"대화로 주고받은 내용보다 온라인 대화 예절을 지키며 참여했는지","correct":true},{"t":"누가 가장 재미있는 이야기를 했는지","mis":"K4-2-u5-X62"},{"t":"누가 가장 많은 글을 올렸는지","mis":"K4-2-u5-X62"}],"explanation":["온라인 대화로 소통하는 내용보다 예절을 먼저 평가해요.","정답이 정해진 평가가 아니에요.","예절을 지키며 적극적으로 참여했는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#18','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C62',3,'mc','auto','이황이 “네가 얼마나 보고 싶은지 모른다.”라고 쓴 부분에서 드러나는 마음은 무엇인가요?',ARRAY['K4-2-u5-X46']::text[],false,'{"seq":18,"concept":"K4-2-u5-C62","difficulty":3,"kind":"mc","stem":"이황이 “네가 얼마나 보고 싶은지 모른다.”라고 쓴 부분에서 드러나는 마음은 무엇인가요?","options":[{"t":"손자를 그리워하는 마음","correct":true},{"t":"손자에게 화가 난 마음","mis":"K4-2-u5-X46"},{"t":"손자를 부러워하는 마음","mis":"K4-2-u5-X46"}],"explanation":["보고 싶다는 말에 마음이 드러나요.","멀리 있어 오고 가기 쉽지 않아 안타깝다고 했어요.","손자를 그리워하는 마음이에요."],"asset":{"type":"passage","lines":["손자 안도에게","(간추림) 산속 절에 머물며 공부하기로 했다는 소식을 듣고 좋은 일이라고 했다.","세월은 물처럼 흐른단다. 그러니 허투루 보내지 말고 천 번 만 번 힘써서 공부하거라.","(간추림) 흐지부지 보내면 공부가 흩어질까 걱정스럽다고 했다.","네가 얼마나 보고 싶은지 모른다.","(간추림) 생일 선물을 가져온 마음은 고맙지만 너희 얼굴을 보는 것이 더 기쁘다고 했다.","1568년 퇴계 이황"],"title":"이황이 손자에게 쓴 편지 (평가 자료 2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#19','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C46',3,'mc','auto','안창호의 편지에 담긴 마음을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-2-u5-X46','K4-2-u5-X63']::text[],false,'{"seq":19,"concept":"K4-2-u5-C46","difficulty":3,"kind":"mc","stem":"안창호의 편지에 담긴 마음을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"팔을 다쳤다는 소식 — 걱정 / 한 학년 올라간 일 — 축하와 기쁨","correct":true},{"t":"팔을 다쳤다는 소식 — 기쁨 / 한 학년 올라간 일 — 걱정","mis":"K4-2-u5-X46"},{"t":"편지에는 축하하는 마음 한 가지만 있다","mis":"K4-2-u5-X63"}],"explanation":["다쳤다는 소식에 “매우 걱정되는구나.”라고 했어요.","한 학년 올라간 일에는 “무척 기쁘구나.”라고 했어요.","한 편지에 여러 마음이 담길 수 있어요."],"asset":{"type":"passage","lines":["사랑하는 아들 필립","(간추림) 넘어져 팔을 다쳤다는 소식에 매우 걱정되니 팔이 나으면 바로 알리라고 했다.","한 학년 올라가게 된 것을 축하한다. 아버지는 무척 기쁘구나.","(간추림) 좋은 사람이 되려면 진실하고 깨끗해야 하며,","(간추림) 좋은 친구를 가려 사귀고 좋은 책을 골라 꾸준히 읽으라고 했다.","1920년 8월 3일 홍콩에서","아버지가"],"title":"안창호가 아들에게 쓴 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#20','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C40',3,'mc','auto','고쳐 쓸 곳이 있는 편지의 “가족과 할머니 집으로 갈게요.”를 읽는 이에 맞게 고친 것은 무엇인가요?',ARRAY['K4-2-u5-X64']::text[],false,'{"seq":20,"concept":"K4-2-u5-C40","difficulty":3,"kind":"mc","stem":"고쳐 쓸 곳이 있는 편지의 “가족과 할머니 집으로 갈게요.”를 읽는 이에 맞게 고친 것은 무엇인가요?","options":[{"t":"“가족과 할머니 댁으로 찾아뵐게요.”","correct":true},{"t":"“가족과 할머니 집으로 갈게.”","mis":"K4-2-u5-X64"},{"t":"“가족과 할머니한테 갈게요.”","mis":"K4-2-u5-X64"}],"explanation":["웃어른의 집은 높여서 말해요.","‘가다’ 대신 ‘찾아뵙다’를 써요.","석원이도 “찾아뵐게요.”라고 썼어요."],"asset":{"type":"passage","lines":["할머니에게","할머니, 저 석원이예요. 할머니에게 감사의 마음을 전하고 싶어서","이렇게 편지를 썼어요. 제 마음 아시죠? 항상 고맙습니다.","다음 주면 할머니의 생일이네요. 가족과 할머니 집으로 갈게요.","할머니, 사랑해요.","지석원 씀"],"title":"고쳐 쓸 곳이 있는 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#21','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C25',3,'mc','auto','“온라인 대화를 할 때 아무 말도 하지 말자.”라는 의견이 적절하지 않은 까닭은 무엇인가요?',ARRAY['K4-2-u5-X24','K4-2-u5-X25']::text[],false,'{"seq":21,"concept":"K4-2-u5-C25","difficulty":3,"kind":"mc","stem":"“온라인 대화를 할 때 아무 말도 하지 말자.”라는 의견이 적절하지 않은 까닭은 무엇인가요?","options":[{"t":"실천이 가능하지 않고, 온라인 대화의 장점까지 모두 잃게 되기 때문","correct":true},{"t":"짧은 의견은 언제나 적절하지 않기 때문","mis":"K4-2-u5-X24"},{"t":"다른 사람이 낸 의견이기 때문","mis":"K4-2-u5-X25"}],"explanation":["의견이 실천 가능한지 따져요.","장점이 단점보다 큰지도 생각해요.","아무 말도 하지 말자는 의견은 둘 다 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#22','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C30',3,'mc','auto','채팅방에서 언어폭력을 당했을 때 알맞게 한 것은 무엇인가요?',ARRAY['K4-2-u5-X30','K4-2-u5-X03']::text[],false,'{"seq":22,"concept":"K4-2-u5-C30","difficulty":3,"kind":"mc","stem":"채팅방에서 언어폭력을 당했을 때 알맞게 한 것은 무엇인가요?","options":[{"t":"대화 내용이 있는 화면을 캡처하고 부모님이나 선생님께 바로 도움을 구한다","correct":true},{"t":"혼자 참고 아무에게도 말하지 않는다","mis":"K4-2-u5-X30"},{"t":"똑같이 욕을 해서 갚아 준다","mis":"K4-2-u5-X03"}],"explanation":["혼자 해결하려고 하지 않아요.","대화 내용을 남겨 두어요.","어른께 바로 도움을 구해요."],"asset":{"type":"passage","lines":["(간추림) 채팅방에서 친구에 대한 안 좋은 소문을 퍼뜨리는 것,","(간추림) 한 명을 초대한 뒤 여러 명이 번갈아서 욕하고 괴롭히는 것,","(간추림) 한 명을 소외시키고 따로 채팅방을 만들어 흉보는 것은 언어폭력이다.","(간추림) 이런 일을 당했다면 대화 내용이 있는 화면을 캡처하고","(간추림) 부모님이나 선생님께 바로 도움을 구한다."],"title":"온라인 채팅방 대화법 — 언어폭력 조심하기 (간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#23','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C20',4,'essay','teacher','유나의 메시지처럼 밤늦게 답을 재촉하는 일이 왜 문제인지 쓰고, 온라인 대화 예절을 생각하며 유나의 메시지를 고쳐 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u5-C20","difficulty":4,"kind":"essay","stem":"유나의 메시지처럼 밤늦게 답을 재촉하는 일이 왜 문제인지 쓰고, 온라인 대화 예절을 생각하며 유나의 메시지를 고쳐 쓰세요.","answer_guide":{"answer":"예: 밤늦은 시간에는 상대가 쉬거나 자고 있을 수 있는데, 답이 없다고 다그치면 상대의 시간을 빼앗고 기분을 상하게 한다. 고친 메시지 — 「지후야, 늦은 시간에 미안해. 내일 숙제가 생각나지 않아서 그러는데, 내일 아침에 알려 줄 수 있니?」","scoring_points":["밤늦은 시간과 상대의 사정을 이어 문제를 썼는가","다그치지 않는 말로 고쳐 썼는가","상대를 존중하는 표현을 썼는가"]},"explanation":["온라인 대화는 시간과 장소의 제약이 적어요.","그래도 상대의 사정을 생각해야 해요.","미안함을 밝히고 공손하게 부탁해요."],"asset":{"type":"speech","turns":[{"who":"유나 (오후 10:50)","text":"내일 숙제 뭐였어? 기억이 안 나ㅠㅠ"},{"who":"유나 (오후 11:40)","text":"김지후, 너 왜 확인을 안 해?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#24','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C42',4,'essay','teacher','고쳐 쓸 곳이 있는 편지를 『국어』 241쪽 6번의 편지 쓰는 방법에 맞게 고쳐 쓰세요. 높임 표현, 고마웠던 일, 빠진 짜임을 모두 살피세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u5-C42","difficulty":4,"kind":"essay","stem":"고쳐 쓸 곳이 있는 편지를 『국어』 241쪽 6번의 편지 쓰는 방법에 맞게 고쳐 쓰세요. 높임 표현, 고마웠던 일, 빠진 짜임을 모두 살피세요.","answer_guide":{"answer":"예: 할머니께 / 할머니, 안녕하세요? 저 석원이예요. 건강하게 잘 지내고 계시지요? 지난번에 제가 아플 때 죽을 끓여 주셔서 정말 고마웠어요. 다음 주면 할머니 생신이네요. 가족과 함께 할머니 댁으로 찾아뵐게요. 안녕히 계세요. / 20○○년 ○○월 ○○일 / 손자 지석원 올림","scoring_points":["받는 사람·낱말·쓴 사람의 높임 표현을 바르게 고쳤는가","고마웠던 일을 구체적으로 썼는가","첫인사·끝인사·쓴 날짜를 채웠는가"]},"explanation":["‘에게’, ‘생일’, ‘집’, ‘씀’을 고쳐요.","무엇이 고마웠는지 있었던 일을 넣어요.","빠진 첫인사, 끝인사, 쓴 날짜를 채워요."],"asset":{"type":"passage","lines":["할머니에게","할머니, 저 석원이예요. 할머니에게 감사의 마음을 전하고 싶어서","이렇게 편지를 썼어요. 제 마음 아시죠? 항상 고맙습니다.","다음 주면 할머니의 생일이네요. 가족과 할머니 집으로 갈게요.","할머니, 사랑해요.","지석원 씀"],"title":"고쳐 쓸 곳이 있는 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_b#25','kor',4,2,'u5','','tb_g4_2_kor_u5_review_b','unit_review','K4-2-u5-C57',4,'essay','teacher','「매체 대 매체 놀이」의 질문 카드 「말하는 이와 듣는 이가 정해져 있나요? 그렇게 생각하는 까닭은 무엇인가요?」에 맞게, 편지와 온라인 게시판을 비교하여 대답하세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u5-C57","difficulty":4,"kind":"essay","stem":"「매체 대 매체 놀이」의 질문 카드 「말하는 이와 듣는 이가 정해져 있나요? 그렇게 생각하는 까닭은 무엇인가요?」에 맞게, 편지와 온라인 게시판을 비교하여 대답하세요.","answer_guide":{"answer":"예: 편지는 읽는 사람이 정해져 있어서 받는 사람을 맨 처음에 쓴다. 온라인 게시판은 여러 사람이 읽고, 이름을 밝히지 않을 수도 있어 대화 상대가 분명하지 않을 때가 있다.","scoring_points":["질문 카드에 맞게 대답했는가","편지의 특성을 까닭과 함께 썼는가","온라인 게시판의 특성을 견주어 썼는가"]},"explanation":["질문이 묻는 것을 먼저 봐요.","편지는 읽는 사람이 정해져 있어요.","게시판은 여러 사람이 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#1','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C33',1,'ox','auto','『국어』 249쪽 스스로 확인하기에서 ●만 칠한 물음이 있으면, 그 부분을 다시 살펴 공부하면 돼요.',ARRAY['K4-2-u5-X31']::text[],false,'{"seq":1,"concept":"K4-2-u5-C33","difficulty":1,"kind":"ox","stem":"『국어』 249쪽 스스로 확인하기에서 ●만 칠한 물음이 있으면, 그 부분을 다시 살펴 공부하면 돼요.","answer":"O","reason_options":[{"t":"스스로 확인하기는 잘 안 되는 부분을 찾아 다시 살피려고 하는 것이기 때문에","correct":true},{"t":"스스로 확인하기는 점수를 매겨 친구와 겨루려고 하는 것이기 때문에","mis":"K4-2-u5-X31"}],"mis":"K4-2-u5-X31","explanation":["●는 보통임이에요.","잘 안 되는 부분을 찾는 것이 목적이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["온라인 대화에서 지켜야 할 예절을 알 수 있나요? ○○○","예절을 지키며 온라인 대화를 할 수 있나요? ○○○","마음을 잘 나타낼 수 있는 표현을 사용해 편지를 쓸 수 있나요? ○○○","읽는 이의 마음이 어떠할지 짐작하며 편지를 쓸 수 있나요? ○○○","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"스스로 확인하기 — 『국어』 249쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#2','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C5',1,'mc','auto','멀리 떨어져 있는 친구의 생일을 축하하고 싶을 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u5-X06','K4-2-u5-X04']::text[],false,'{"seq":2,"concept":"K4-2-u5-C5","difficulty":1,"kind":"mc","stem":"멀리 떨어져 있는 친구의 생일을 축하하고 싶을 때 알맞은 방법은 무엇인가요?","options":[{"t":"온라인 대화로 축하하는 마음을 전한다","correct":true},{"t":"친구가 돌아올 때까지 기다렸다가 말한다","mis":"K4-2-u5-X06"},{"t":"마음속으로만 축하한다","mis":"K4-2-u5-X04"}],"explanation":["상대가 멀리 있어요.","생일 축하는 그날 전하면 좋아요.","떨어져 있어도 닿는 온라인 대화가 편리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#3','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C10',1,'ox','auto','온라인 대화는 상대와 같은 시간과 장소에 있지 않아도 할 수 있어요.',ARRAY['K4-2-u5-X10']::text[],false,'{"seq":3,"concept":"K4-2-u5-C10","difficulty":1,"kind":"ox","stem":"온라인 대화는 상대와 같은 시간과 장소에 있지 않아도 할 수 있어요.","answer":"O","reason_options":[{"t":"디지털 기기를 사용해 떨어진 곳에서도 주고받을 수 있기 때문에","correct":true},{"t":"온라인 대화는 같은 방에 있을 때에만 할 수 있기 때문에","mis":"K4-2-u5-X10"}],"mis":"K4-2-u5-X10","explanation":["그림 가처럼 한국과 미국에서도 대화해요.","디지털 기기가 있으면 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#4','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C20',1,'ox','auto','상대가 보이지 않는 온라인 대화에서는 존중하는 말을 쓰지 않아도 돼요.',ARRAY['K4-2-u5-X03']::text[],false,'{"seq":4,"concept":"K4-2-u5-C20","difficulty":1,"kind":"ox","stem":"상대가 보이지 않는 온라인 대화에서는 존중하는 말을 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"상대가 보이지 않아도 화면 너머에 사람이 있으니 존중하며 대화해야 하기 때문에","correct":true},{"t":"온라인에서는 상대가 누구인지 모르기 때문에","mis":"K4-2-u5-X03"}],"mis":"K4-2-u5-X03","explanation":["『국어』 233쪽 예절에 “상대가 보이지 않아도 존중하며 대화한다.”가 있어요.","화면 너머에도 사람이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#5','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C39',1,'mc','auto','편지를 다 썼지만 보태고 싶은 내용이 있을 때 쓰는 부분은 무엇인가요?',ARRAY['K4-2-u5-X38']::text[],false,'{"seq":5,"concept":"K4-2-u5-C39","difficulty":1,"kind":"mc","stem":"편지를 다 썼지만 보태고 싶은 내용이 있을 때 쓰는 부분은 무엇인가요?","options":[{"t":"추신","correct":true},{"t":"첫인사","mis":"K4-2-u5-X38"},{"t":"받는 사람","mis":"K4-2-u5-X38"}],"explanation":["편지를 다 쓴 뒤에 생각난 말이 있을 수 있어요.","이때 ‘추신’이라고 쓰고 덧붙여요.","필요한 경우에만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#6','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C51',1,'mc','auto','편지봉투에서 우표를 붙이는 자리는 어디인가요?',ARRAY['K4-2-u5-X50']::text[],false,'{"seq":6,"concept":"K4-2-u5-C51","difficulty":1,"kind":"mc","stem":"편지봉투에서 우표를 붙이는 자리는 어디인가요?","options":[{"t":"오른쪽 위","correct":true},{"t":"왼쪽 아래","mis":"K4-2-u5-X50"},{"t":"봉투 뒷면 가운데","mis":"K4-2-u5-X50"}],"explanation":["우표는 우편 요금을 냈다는 증표예요.","봉투의 오른쪽 위에 붙여요.","우체국이나 우체국 누리집에서 살 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#7','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C64',1,'mc','auto','겹받침 ㄼ이 들어간 낱말을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u5-X68']::text[],false,'{"seq":7,"concept":"K4-2-u5-C64","difficulty":1,"kind":"mc","stem":"겹받침 ㄼ이 들어간 낱말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"여덟","correct":true},{"t":"여덜","mis":"K4-2-u5-X68"},{"t":"여덥","mis":"K4-2-u5-X68"}],"explanation":["『국어』 251쪽 글씨 쓰기 낱말이에요.","받침 자리에 ㄹ과 ㅂ을 함께 써요.","‘여덟’이 바른 글씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#8','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C54',1,'mc','auto','온라인 대화 예절을 알리는 표어로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u5-X54']::text[],false,'{"seq":8,"concept":"K4-2-u5-C54","difficulty":1,"kind":"mc","stem":"온라인 대화 예절을 알리는 표어로 알맞지 않은 것은 무엇인가요?","options":[{"t":"온라인 대화는 무조건 하지 말자","correct":true},{"t":"대화는 친절하게 댓글은 신중하게","mis":"K4-2-u5-X54"},{"t":"따뜻한 댓글 행복한 인터넷 세상","mis":"K4-2-u5-X54"}],"explanation":["표어는 지킬 예절을 짧게 담아요.","친절한 대화, 따뜻한 댓글은 예절을 알려요.","무조건 하지 말자는 말은 예절을 알리는 표어가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#9','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C17',2,'mc','auto','상황 나에서 ‘천재 작가’가 한 행동에서 고칠 점은 무엇인가요?',ARRAY['K4-2-u5-X61','K4-2-u5-X19']::text[],false,'{"seq":9,"concept":"K4-2-u5-C17","difficulty":2,"kind":"mc","stem":"상황 나에서 ‘천재 작가’가 한 행동에서 고칠 점은 무엇인가요?","options":[{"t":"사실인지 확인하지 않은 다른 사람의 소문을 여러 사람이 읽는 게시판에 올렸다","correct":true},{"t":"웃음을 나타내는 글자를 썼다","mis":"K4-2-u5-X61"},{"t":"대화명을 재미있게 지었다","mis":"K4-2-u5-X19"}],"explanation":["‘천재 작가’는 어제 게시판에 소문을 올렸다고 했어요.","사실 여부가 확실하지 않은 이야기예요.","그 글에 나온 사람이 크게 다칠 수 있어요."],"asset":{"type":"speech","turns":[{"who":"소리 요정 (10/15 15:20)","text":"○○에 대한 소문 들었어? 난 다 알고 있음."},{"who":"한글 박사 (10/15 15:25)","text":"뭔데? 빨리 말해 봐!"},{"who":"천재 작가 (10/15 15:26)","text":"나도 알고 있지. ㅋㅋㅋ 내가 어제 게시판에 올린 그 소문이지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#10','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C31',2,'ox','auto','『국어활동』 71쪽 「더 알아보기」처럼 누리 소통망에서는 그림말로도 생각이나 마음을 표현할 수 있어요.',ARRAY['K4-2-u5-X67']::text[],false,'{"seq":10,"concept":"K4-2-u5-C31","difficulty":2,"kind":"ox","stem":"『국어활동』 71쪽 「더 알아보기」처럼 누리 소통망에서는 그림말로도 생각이나 마음을 표현할 수 있어요.","answer":"O","reason_options":[{"t":"그림말을 대화 주제에 맞게 알맞게 쓰면 마음을 효과적으로 전할 수 있기 때문에","correct":true},{"t":"그림말은 예절에 어긋나 온라인 대화에서 아예 쓰면 안 되기 때문에","mis":"K4-2-u5-X67"}],"mis":"K4-2-u5-X67","explanation":["『국어』 236쪽에서도 그림말로 마음을 효과적으로 전했다는 소감이 나왔어요.","주제와 관련 없이 되풀이하는 것이 문제예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#11','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C28',2,'mc','auto','『국어』 235쪽 (1)에서 아리랑을 주제로 하는 지역 축제에 대해 알고 싶다고 한 친구에게 알맞은 대화 상대는 누구인가요?',ARRAY['K4-2-u5-X29','K4-2-u5-X27']::text[],false,'{"seq":11,"concept":"K4-2-u5-C28","difficulty":2,"kind":"mc","stem":"『국어』 235쪽 (1)에서 아리랑을 주제로 하는 지역 축제에 대해 알고 싶다고 한 친구에게 알맞은 대화 상대는 누구인가요?","options":[{"t":"지역 축제를 잘 알고 있는 사람","correct":true},{"t":"먼저 말을 걸어온 모르는 사람","mis":"K4-2-u5-X29"},{"t":"그 축제를 전혀 모르는 같은 반 친구","mis":"K4-2-u5-X27"}],"explanation":["친구 2는 지역 축제를 잘 알고 있는 사람이 알려 줬으면 좋겠다고 했어요.","대화 주제에 맞는 상대를 골라요.","믿을 수 없는 사람과는 대화하지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"외국에 사는 친구와 함께 음식 문화에 대하여 이야기하고 싶어."},{"who":"친구 2","text":"아리랑을 주제로 하는 지역 축제에 대해 알고 싶어. 지역 축제를 잘 알고 있는 사람이 알려 줬으면 좋겠어."},{"who":"친구 3","text":"친구들과 잘하는 것을 동영상으로 촬영해서 온라인 장기자랑을 해 보고 싶어."},{"who":"친구 4","text":"나와 같은 책을 읽은 친구들과 함께 의견을 나누고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#12','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C61',2,'mc','auto','석원이가 고구마가 더 맛있다고 한 까닭은 무엇인가요?',ARRAY['K4-2-u5-X37']::text[],false,'{"seq":12,"concept":"K4-2-u5-C61","difficulty":2,"kind":"mc","stem":"석원이가 고구마가 더 맛있다고 한 까닭은 무엇인가요?","options":[{"t":"할머니께서 텃밭에서 정성 들여 직접 키우셨기 때문","correct":true},{"t":"고구마를 처음 먹어 보았기 때문","mis":"K4-2-u5-X37"},{"t":"우수상을 받아 기분이 좋았기 때문","mis":"K4-2-u5-X37"}],"explanation":["석원이는 간식으로 할머니가 보내 주신 고구마를 먹었어요.","할머니께서 텃밭에서 정성 들여 키우셨어요.","그래서 더 맛있다고 했어요."],"asset":{"type":"passage","lines":["할머니, 고구마를 보내 주셔서 고맙습니다.","(간추림) 할머니께서 텃밭에서 정성 들여 직접 키우셔서 고구마가 더 맛있다고 했다.","그리고 기쁜 소식이 있어요. 제가 독후감 쓰기 대회에서 우수상을 받았어요!","(간추림) 늘 아끼고 사랑해 주시는 할머니께 마음 깊이 감사하다고 했다.","(간추림) 할머니가 많이 보고 싶어서 다음 달 생신 때 찾아뵙겠다고 했다."],"title":"석원이의 편지 가운데 「전하고 싶은 말」 — 『국어』 239쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#13','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C35',2,'mc','auto','「편지의 역사」에서 오늘날 편지가 하는 역할로 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X36','K4-2-u5-X35']::text[],false,'{"seq":13,"concept":"K4-2-u5-C35","difficulty":2,"kind":"mc","stem":"「편지의 역사」에서 오늘날 편지가 하는 역할로 말한 것은 무엇인가요?","options":[{"t":"다른 통신 수단이 하지 못하는 진심을 전하는 역할","correct":true},{"t":"가장 빠르게 소식을 전하는 역할","mis":"K4-2-u5-X36"},{"t":"이제는 아무 역할도 하지 않음","mis":"K4-2-u5-X35"}],"explanation":["통신 기술이 발달해 편지를 쓰는 일은 줄었어요.","그래도 편지는 다른 의미를 갖게 되었어요.","진심을 전하는 역할을 해요."],"asset":{"type":"passage","lines":["(간추림) 점토판, 파피루스, 양피지, 나무를 이용한 목간 등에 편지를 쓰다가","(간추림) 종이가 발명되면서 편지의 이용이 크게 늘었다.","(간추림) 1884년 우정총국이 설립되면서 우리나라 최초의 우체통이 설치되었다.","(간추림) 전화기와 전자 우편이 생긴 뒤 편지를 쓰는 일이 점차 줄었다.","(간추림) 오늘날 편지는 다른 통신 수단이 하지 못하는 진심을 전하는 역할을 한다."],"title":"「편지의 역사」 간추림 — 『국어활동』 스스로 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#14','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C47',2,'mc','auto','정조의 한글 편지처럼 계절이나 날씨에 대한 말로 안부를 여쭙는 문장은 어느 것인가요?',ARRAY['K4-2-u5-X38','K4-2-u5-X47']::text[],false,'{"seq":14,"concept":"K4-2-u5-C47","difficulty":2,"kind":"mc","stem":"정조의 한글 편지처럼 계절이나 날씨에 대한 말로 안부를 여쭙는 문장은 어느 것인가요?","options":[{"t":"서릿바람에 기후 평안하신지 문안 알고자 합니다.","correct":true},{"t":"원손","mis":"K4-2-u5-X38"},{"t":"뵌 지 오래되어 섭섭하고 그리웠습니다.","mis":"K4-2-u5-X47"}],"explanation":["‘서릿바람’은 계절을 나타내는 말이에요.","‘평안하신지’는 안부를 여쭙는 말이에요.","계절 인사와 안부는 편지의 처음에 써요."],"asset":{"type":"passage","lines":["숙모님 앞","서릿바람에 기후 평안하신지 문안 알고자 합니다.","(간추림) 뵌 지 오래되어 섭섭하고 그리웠는데 어제 편지를 보니 든든하고 반갑다고 했다.","원손"],"title":"정조가 숙모에게 보낸 한글 편지 (오늘날 표현)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#15','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C48',2,'mc','auto','『국어』 241쪽 5번 예시 편지에서 고마운 마음을 느낀 일을 구체적으로 쓴 부분은 무엇인가요?',ARRAY['K4-2-u5-X49']::text[],false,'{"seq":15,"concept":"K4-2-u5-C48","difficulty":2,"kind":"mc","stem":"『국어』 241쪽 5번 예시 편지에서 고마운 마음을 느낀 일을 구체적으로 쓴 부분은 무엇인가요?","options":[{"t":"리코더 소리를 제대로 내지 못할 때 선생님께서 연주 자세와 호흡법, 텅잉 익히기를 하나씩 가르쳐 주셨다","correct":true},{"t":"편지로 감사의 마음을 전합니다.","mis":"K4-2-u5-X49"},{"t":"늘 건강하시길 바랍니다.","mis":"K4-2-u5-X49"}],"explanation":["무엇이 고마웠는지 있었던 일을 밝혔어요.","그때의 속상한 마음과 나아진 모습도 썼어요.","그래서 고마운 마음이 잘 전해져요."],"asset":{"type":"passage","lines":["박○○ 선생님께","안녕하세요. 저는 김△△입니다.","(간추림) 작년 음악 시간에 리코더 소리를 제대로 내지 못해 속상했는데,","(간추림) 선생님께서 바른 자세와 호흡법, 텅잉 익히기를 하나씩 가르쳐 주시고","(간추림) 반복해서 연습하면 잘할 수 있다고 격려해 주셨다.","편지로 감사의 마음을 전합니다. 늘 건강하시길 바랍니다.","20○○년 ○○월 ○○일","제자 김△△ 올림"],"title":"선생님께 마음을 전하는 편지 (예시) — 『국어』 241쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#16','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C23',2,'mc','auto','‘ㅇㅈ(인정)’, ‘ㄹㅇ(진짜)’ 같은 신조어나 줄임말을 쓸 때 조심해야 하는 까닭은 무엇인가요?',ARRAY['K4-2-u5-X61','K4-2-u5-X22']::text[],false,'{"seq":16,"concept":"K4-2-u5-C23","difficulty":2,"kind":"mc","stem":"‘ㅇㅈ(인정)’, ‘ㄹㅇ(진짜)’ 같은 신조어나 줄임말을 쓸 때 조심해야 하는 까닭은 무엇인가요?","options":[{"t":"뜻을 모르는 사람이 소외감을 느끼거나 오해할 수 있기 때문","correct":true},{"t":"줄임말은 글자 수가 적어 성의가 넘치기 때문","mis":"K4-2-u5-X61"},{"t":"상대가 뜻을 모르면 상대가 알아서 공부하면 되기 때문","mis":"K4-2-u5-X22"}],"explanation":["잘 아는 친구끼리는 재미있을 수 있어요.","뜻을 모르는 사람은 대화에서 밀려나요.","상황에 맞게 다른 사람을 배려하며 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#17','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C31',3,'mc','auto','관찰 기록표의 「온라인 대화 하기」 칸에 들어가는 기준이 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":17,"concept":"K4-2-u5-C31","difficulty":3,"kind":"mc","stem":"관찰 기록표의 「온라인 대화 하기」 칸에 들어가는 기준이 아닌 것은 무엇인가요?","options":[{"t":"적극적으로 참여했는가?","correct":true},{"t":"주제와 관련 있는 내용을 이야기했는가?","mis":"K4-2-u5-X27"},{"t":"사실과 다른 내용을 말하지 않았는가?","mis":"K4-2-u5-X27"}],"explanation":["온라인 대화 하기에서는 흥미, 주제, 사실을 살펴요.","적극적으로 참여했는지는 참여 태도에서 살펴요.","세 칸의 기준을 가려요."],"asset":{"type":"passage","lines":["계획하기 — 상대를 고려하여 매체를 선택했는가? · 좋은 점과 문제점을 고려했는가?","온라인 대화 하기 — 상대가 흥미를 느낄 만한 내용인가? ·","        주제와 관련 있는 내용을 이야기했는가? · 사실과 다른 내용을 말하지 않았는가?","참여 태도 — 주제와 관련 없는 말이나 그림말을 반복하지 않았는가? ·","        불쾌감을 주지 않았는가? · 바른 말, 고운 말을 썼는가? ·","        상대의 허락 없이 대화를 끊지 않았는가? · 적극적으로 참여했는가?","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"온라인 대화 관찰 기록표 (평가 자료 1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#18','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C62',3,'mc','auto','이황은 손자의 아내가 가져온 생일 선물을 두고 어떤 생각을 전했나요?',ARRAY['K4-2-u5-X37']::text[],false,'{"seq":18,"concept":"K4-2-u5-C62","difficulty":3,"kind":"mc","stem":"이황은 손자의 아내가 가져온 생일 선물을 두고 어떤 생각을 전했나요?","options":[{"t":"마음은 고맙지만 선물보다 너희 얼굴을 보는 것이 더 기쁘다","correct":true},{"t":"선물이 마음에 들지 않는다","mis":"K4-2-u5-X37"},{"t":"선물을 더 많이 보내라","mis":"K4-2-u5-X37"}],"explanation":["이황은 선물을 가져온 마음은 고맙다고 했어요.","그러나 선물을 받는 일이 기쁘지만은 않다고 했어요.","얼굴을 보는 것이 더 기쁘다는 마음이에요."],"asset":{"type":"passage","lines":["손자 안도에게","(간추림) 산속 절에 머물며 공부하기로 했다는 소식을 듣고 좋은 일이라고 했다.","세월은 물처럼 흐른단다. 그러니 허투루 보내지 말고 천 번 만 번 힘써서 공부하거라.","(간추림) 흐지부지 보내면 공부가 흩어질까 걱정스럽다고 했다.","네가 얼마나 보고 싶은지 모른다.","(간추림) 생일 선물을 가져온 마음은 고맙지만 너희 얼굴을 보는 것이 더 기쁘다고 했다.","1568년 퇴계 이황"],"title":"이황이 손자에게 쓴 편지 (평가 자료 2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#19','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C50',3,'mc','auto','『국어』 244쪽 점검에서 네 물음에 모두 「예」가 나왔다면 마지막에 할 일은 무엇인가요?',ARRAY['K4-2-u5-X32','K4-2-u5-X31']::text[],false,'{"seq":19,"concept":"K4-2-u5-C50","difficulty":3,"kind":"mc","stem":"『국어』 244쪽 점검에서 네 물음에 모두 「예」가 나왔다면 마지막에 할 일은 무엇인가요?","options":[{"t":"다시 한번 읽고 부족한 부분이 있으면 고쳐 쓴다","correct":true},{"t":"더 볼 것이 없으니 바로 끝낸다","mis":"K4-2-u5-X32"},{"t":"친구 편지의 점검표를 대신 채워 준다","mis":"K4-2-u5-X31"}],"explanation":["모두 「예」여도 한 번 더 읽어요.","소리 내어 천천히 읽으면 고칠 곳이 보여요.","부족한 부분은 고쳐 써요."],"asset":{"type":"passage","lines":["1 편지의 짜임에 맞게 썼나요?","2 마음을 전하는 글의 내용을 자세히 썼나요?","3 전하고 싶은 마음이 잘 드러났나요?","4 읽는 이를 고려해 썼나요?","→ 「아니요」가 나오면 그 물음에 맞게 고쳐 쓰고, 「예」면 다음 물음으로 간다.","→ 마지막에는 다시 한번 읽고 부족한 부분이 있으면 고쳐 쓴다."],"numbered":false,"title":"읽는 이를 생각하며 마음을 잘 표현했는지 점검하기 — 『국어』 244쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#20','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C42',3,'mc','auto','고쳐 쓸 곳이 있는 편지에 빠진 편지의 짜임을 바르게 모은 것은 무엇인가요?',ARRAY['K4-2-u5-X38','K4-2-u5-X39']::text[],false,'{"seq":20,"concept":"K4-2-u5-C42","difficulty":3,"kind":"mc","stem":"고쳐 쓸 곳이 있는 편지에 빠진 편지의 짜임을 바르게 모은 것은 무엇인가요?","options":[{"t":"첫인사 · 끝인사 · 쓴 날짜","correct":true},{"t":"받는 사람 · 쓴 사람","mis":"K4-2-u5-X38"},{"t":"전하고 싶은 말 · 추신","mis":"K4-2-u5-X39"}],"explanation":["‘할머니에게’는 받는 사람, ‘지석원 씀’은 쓴 사람이에요.","안부를 묻는 첫인사와 끝인사가 없어요.","쓴 날짜도 빠졌어요."],"asset":{"type":"passage","lines":["할머니에게","할머니, 저 석원이예요. 할머니에게 감사의 마음을 전하고 싶어서","이렇게 편지를 썼어요. 제 마음 아시죠? 항상 고맙습니다.","다음 주면 할머니의 생일이네요. 가족과 할머니 집으로 갈게요.","할머니, 사랑해요.","지석원 씀"],"title":"고쳐 쓸 곳이 있는 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#21','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C24',3,'mc','auto','토의 결과를 정리한 뒤 토의 평가하기에서 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X15']::text[],false,'{"seq":21,"concept":"K4-2-u5-C24","difficulty":3,"kind":"mc","stem":"토의 결과를 정리한 뒤 토의 평가하기에서 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"토의에 참여한 모습을 되돌아보며 자기 자신과 친구들을 칭찬한다","correct":true},{"t":"누구의 의견이 이겼는지 점수를 매긴다","mis":"K4-2-u5-X15"},{"t":"뽑히지 않은 의견을 낸 친구를 탓한다","mis":"K4-2-u5-X15"}],"explanation":["토의는 이기고 지는 일이 아니에요.","참여한 모습을 되돌아봐요.","나와 친구들의 좋은 점을 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#22','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C13',3,'blank','auto','「디지털 시대의 바람직한 의사소통을 위한 노력」의 첫째 노력이에요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#23','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C28',4,'essay','teacher','상황과 상대를 고려하여 온라인 대화를 계획해요. 대화할 상대, 고른 매체(방식)와 그 매체를 고른 까닭(좋은 점과 문제점), 대화할 주제를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u5-C28","difficulty":4,"kind":"essay","stem":"상황과 상대를 고려하여 온라인 대화를 계획해요. 대화할 상대, 고른 매체(방식)와 그 매체를 고른 까닭(좋은 점과 문제점), 대화할 주제를 쓰세요.","answer_guide":{"answer":"예: 대화 상대 — 다른 지역에 사는 사촌 / 매체 — 영상 통화, 얼굴을 보며 이야기할 수 있어 반갑지만 정해진 시간에 함께 들어와야 하니 미리 시간을 정한다 / 주제 — 서로의 학교 행사 소개하기","scoring_points":["대화할 상대를 썼는가","매체와 고른 까닭(좋은 점과 문제점)을 썼는가","상대가 흥미를 느낄 만한 주제를 썼는가"]},"explanation":["누구와 이야기할지 먼저 정해요.","매체의 좋은 점과 문제점을 함께 생각해요.","상대가 흥미를 느낄 주제를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#24','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C47',4,'essay','teacher','『국어』 249쪽 「생활 속으로」의 친구 3처럼 다른 지역에 사는 할머니께 그리운 마음을 담아 안부를 여쭙는 편지를 쓰려고 해요. 처음 · 가운데 · 끝에 들어갈 내용을 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u5-C47","difficulty":4,"kind":"essay","stem":"『국어』 249쪽 「생활 속으로」의 친구 3처럼 다른 지역에 사는 할머니께 그리운 마음을 담아 안부를 여쭙는 편지를 쓰려고 해요. 처음 · 가운데 · 끝에 들어갈 내용을 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 처음 — 「할머니, 안녕하세요? 날씨가 많이 쌀쌀해졌는데 건강하시지요?」 / 가운데 — 「지난여름 할머니 댁에서 함께 밤하늘을 보던 일이 자꾸 생각나서 할머니가 많이 보고 싶어요.」 / 끝 — 「다음 방학에 꼭 찾아뵐게요. 늘 건강하세요.」","scoring_points":["처음에 부르는 말과 안부를 썼는가","가운데에 그리운 마음과 함께 겪은 일을 썼는가","끝에 바라는 점과 끝인사를 높임 표현으로 썼는가"]},"explanation":["처음에는 안부를 여쭈어요.","가운데에 함께 겪은 일과 그리운 마음을 써요.","끝에는 바라는 점과 끝인사를 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"공동의 과제를 해결하려고 온라인 대화방을 이용할 때 대화 예절을 잘 지킬 거야."},{"who":"친구 2","text":"나에게 도움을 준 친구에게 고마웠던 마음이 잘 드러나게 편지를 쓸 거야."},{"who":"친구 3","text":"다른 지역에 사는 할머니께 그리운 마음을 담아서 안부를 여쭙는 편지를 쓸 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_c#25','kor',4,2,'u5','','tb_g4_2_kor_u5_review_c','unit_review','K4-2-u5-C3',4,'essay','teacher','‘말하지 않아도 알까요’ 놀이에서 친구가 원래 그리려던 그림과 이어 그린 그림이 달라졌어요. 이 놀이로 알 수 있는 점을 쓰고, 이 단원에서 배운 마음을 전하는 방법 가운데 하나를 골라 어떻게 실천할지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u5-C3","difficulty":4,"kind":"essay","stem":"‘말하지 않아도 알까요’ 놀이에서 친구가 원래 그리려던 그림과 이어 그린 그림이 달라졌어요. 이 놀이로 알 수 있는 점을 쓰고, 이 단원에서 배운 마음을 전하는 방법 가운데 하나를 골라 어떻게 실천할지 쓰세요.","answer_guide":{"answer":"예: 말하지 않으면 다른 사람은 내 마음을 정확히 알기 어려우니 마음은 표현하는 것이 중요하다. 나는 이사 간 친구에게 그리운 마음을 담아 편지를 써서 우체통에 넣겠다.","scoring_points":["마음은 표현해야 전해진다는 점을 썼는가","마음을 전하는 방법 하나를 골랐는가","어떻게 실천할지 썼는가"]},"explanation":["질문하지 않고 이어 그리면 뜻이 달라져요.","마음도 표현하지 않으면 전해지지 않아요.","배운 방법으로 실제로 전해 봐요."],"asset":{"type":"passage","lines":["① 모둠별로 모여 1분 동안 최근에 인상 깊었던 일을 각자 떠올린다.","② 30초 동안 떠올린 일을 종이에 그린 뒤 시계 방향으로 종이를 넘긴다.","③ 받은 종이를 보고 장면을 상상해 이어서 그린다. (질문하지 않는다.)","④ 자신의 종이가 돌아올 때까지 반복한다.","⑤ 자신의 종이를 받아 그림을 확인하고, 원래 그리려던 내용을 공유한다."],"numbered":false,"title":"‘말하지 않아도 알까요’ 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#1','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C34',1,'mc','auto','『국어』 249쪽 「생활 속으로」에서 소단원 1(온라인 대화 예절)에서 배운 것을 실천하겠다고 한 친구는 누구인가요?',ARRAY['K4-2-u5-X01']::text[],false,'{"seq":1,"concept":"K4-2-u5-C34","difficulty":1,"kind":"mc","stem":"『국어』 249쪽 「생활 속으로」에서 소단원 1(온라인 대화 예절)에서 배운 것을 실천하겠다고 한 친구는 누구인가요?","options":[{"t":"친구 1","correct":true},{"t":"친구 2","mis":"K4-2-u5-X01"},{"t":"친구 3","mis":"K4-2-u5-X01"}],"explanation":["친구 1은 온라인 대화방에서 대화 예절을 지키겠다고 했어요.","친구 2와 친구 3은 편지를 쓰겠다고 했어요.","편지 쓰기는 소단원 2에서 배웠어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"공동의 과제를 해결하려고 온라인 대화방을 이용할 때 대화 예절을 잘 지킬 거야."},{"who":"친구 2","text":"나에게 도움을 준 친구에게 고마웠던 마음이 잘 드러나게 편지를 쓸 거야."},{"who":"친구 3","text":"다른 지역에 사는 할머니께 그리운 마음을 담아서 안부를 여쭙는 편지를 쓸 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#2','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C4',1,'ox','auto','마음을 전하는 여러 방법 가운데 언제나 가장 좋은 방법이 하나 정해져 있어요.',ARRAY['K4-2-u5-X05']::text[],false,'{"seq":2,"concept":"K4-2-u5-C4","difficulty":1,"kind":"ox","stem":"마음을 전하는 여러 방법 가운데 언제나 가장 좋은 방법이 하나 정해져 있어요.","answer":"X","reason_options":[{"t":"방법마다 좋은 점과 불편한 점이 있어 상황과 상대에 따라 알맞은 방법을 골라야 하기 때문에","correct":true},{"t":"손 편지가 언제나 가장 정성스러운 방법이기 때문에","mis":"K4-2-u5-X05"}],"mis":"K4-2-u5-X05","explanation":["『국어』 227쪽 3번에서 상황에 따라 방법을 선택해야 한다고 했어요.","어느 방법도 늘 가장 좋지는 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#3','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C12',1,'mc','auto','온라인 대화와 직접 만나서 나누는 대화에서 똑같이 필요한 것은 무엇인가요?',ARRAY['K4-2-u5-X10','K4-2-u5-X12']::text[],false,'{"seq":3,"concept":"K4-2-u5-C12","difficulty":1,"kind":"mc","stem":"온라인 대화와 직접 만나서 나누는 대화에서 똑같이 필요한 것은 무엇인가요?","options":[{"t":"상대에 대한 존중과 배려","correct":true},{"t":"디지털 기기","mis":"K4-2-u5-X10"},{"t":"그림말","mis":"K4-2-u5-X12"}],"explanation":["디지털 기기는 온라인 대화에만 필요해요.","두 대화 모두 상대와 뜻을 주고받아요.","존중과 배려는 똑같이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#4','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C17',1,'mc','auto','게시판에 자료를 올리기 전에 확인할 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X17','K4-2-u5-X16']::text[],false,'{"seq":4,"concept":"K4-2-u5-C17","difficulty":1,"kind":"mc","stem":"게시판에 자료를 올리기 전에 확인할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"사실이 아니거나 잘못된 내용은 없는지","correct":true},{"t":"글자 수가 몇 자인지","mis":"K4-2-u5-X17"},{"t":"누가 가장 먼저 읽을지","mis":"K4-2-u5-X16"}],"explanation":["잘못된 내용은 오해를 만들어요.","인터넷에 남긴 글은 지우기 어려워요.","올리기 전에 사실인지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#5','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C38',1,'ox','auto','전하고 싶은 말을 모두 쓴 다음에는 끝인사를 하고, 줄을 바꾸어 편지를 쓴 날짜를 써요.',ARRAY['K4-2-u5-X38']::text[],false,'{"seq":5,"concept":"K4-2-u5-C38","difficulty":1,"kind":"ox","stem":"전하고 싶은 말을 모두 쓴 다음에는 끝인사를 하고, 줄을 바꾸어 편지를 쓴 날짜를 써요.","answer":"O","reason_options":[{"t":"편지의 짜임이 전하고 싶은 말 → 끝인사 → 쓴 날짜 → 쓴 사람 차례이기 때문에","correct":true},{"t":"쓴 날짜는 편지 맨 처음에 쓰기 때문에","mis":"K4-2-u5-X38"}],"mis":"K4-2-u5-X38","explanation":["『국어』 240쪽에서 편지의 짜임과 차례를 알아보았어요.","끝인사 다음 줄에 쓴 날짜를 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#6','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C40',1,'ox','auto','편지를 받는 상대가 누구인지 생각하며 알맞은 높임 표현을 써야 해요.',ARRAY['K4-2-u5-X41']::text[],false,'{"seq":6,"concept":"K4-2-u5-C40","difficulty":1,"kind":"ox","stem":"편지를 받는 상대가 누구인지 생각하며 알맞은 높임 표현을 써야 해요.","answer":"O","reason_options":[{"t":"읽는 이에 따라 높임 표현을 바르게 써야 마음이 예의 바르게 전해지기 때문에","correct":true},{"t":"높임 표현은 마음이 큰 사람에게만 쓰기 때문에","mis":"K4-2-u5-X41"}],"mis":"K4-2-u5-X41","explanation":["『국어』 241쪽 6번에서 정리한 편지 쓰는 방법이에요.","읽는 이가 누구인지에 따라 높임이 달라져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#7','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C64',1,'mc','auto','『국어』 251쪽 글씨 쓰기에 나온 낱말 가운데 받침을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-2-u5-X68']::text[],false,'{"seq":7,"concept":"K4-2-u5-C64","difficulty":1,"kind":"mc","stem":"『국어』 251쪽 글씨 쓰기에 나온 낱말 가운데 받침을 바르게 쓴 것은 무엇인가요?","options":[{"t":"넓이","correct":true},{"t":"널이","mis":"K4-2-u5-X68"},{"t":"넙이","mis":"K4-2-u5-X68"}],"explanation":["‘넓다’의 받침은 ㄼ이에요.","‘넓이’도 받침 ㄼ을 그대로 써요.","받침 하나만 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#8','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C56',1,'mc','auto','비밀 친구에게 쓴 편지는 어떻게 전하나요?',ARRAY['K4-2-u5-X56','K4-2-u5-X52']::text[],false,'{"seq":8,"concept":"K4-2-u5-C56","difficulty":1,"kind":"mc","stem":"비밀 친구에게 쓴 편지는 어떻게 전하나요?","options":[{"t":"학급 우체통으로 보낸다","correct":true},{"t":"친구에게 직접 이름을 밝히며 건넨다","mis":"K4-2-u5-X56"},{"t":"전하지 않고 내가 간직한다","mis":"K4-2-u5-X52"}],"explanation":["『국어』 247쪽 활동 순서 ③이에요.","학급 우체통을 마련해요.","이름을 밝히지 않고 편지가 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#9','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C18',2,'ox','auto','온라인 대화에서 문제가 생기는 까닭은 디지털 기기가 나쁘기 때문이에요.',ARRAY['K4-2-u5-X18']::text[],false,'{"seq":9,"concept":"K4-2-u5-C18","difficulty":2,"kind":"ox","stem":"온라인 대화에서 문제가 생기는 까닭은 디지털 기기가 나쁘기 때문이에요.","answer":"X","reason_options":[{"t":"얼굴을 마주 보지 않고 이름을 밝히지 않을 수 있는 특성 때문에 문제가 생기는 것이지 기기 탓이 아니기 때문에","correct":true},{"t":"기기만 없으면 문제가 하나도 생기지 않기 때문에","mis":"K4-2-u5-X18"}],"mis":"K4-2-u5-X18","explanation":["문제가 생기는 까닭은 온라인 대화의 특성에 있어요.","얼굴을 마주 보지 않고 이름을 드러내지 않을 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#10','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C31',2,'mc','auto','모둠 과제를 이야기하는 대화방에서 “모둠 과제가 뭐였지?” 하고 물었어요. 『국어활동』 71쪽 예시처럼 주제에 맞게 답한 것은 무엇인가요?',ARRAY['K4-2-u5-X61','K4-2-u5-X25']::text[],false,'{"seq":10,"concept":"K4-2-u5-C31","difficulty":2,"kind":"mc","stem":"모둠 과제를 이야기하는 대화방에서 “모둠 과제가 뭐였지?” 하고 물었어요. 『국어활동』 71쪽 예시처럼 주제에 맞게 답한 것은 무엇인가요?","options":[{"t":"“나는 인터넷으로 자료를 찾아볼게. 내일 도서관에서 찾은 자료와 함께 살펴보자.”","correct":true},{"t":"“??????????”","mis":"K4-2-u5-X61"},{"t":"“대충 하자고.”","mis":"K4-2-u5-X25"}],"explanation":["대화의 주제는 모둠 과제예요.","내가 할 일을 밝히고 함께할 방법을 말했어요.","주제에 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#11','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C30',2,'mc','auto','온라인 대화를 하다가 잘 모르는 사람이 사는 곳과 학교를 물어 왔어요. 알맞은 행동은 무엇인가요?',ARRAY['K4-2-u5-X29','K4-2-u5-X30']::text[],false,'{"seq":11,"concept":"K4-2-u5-C30","difficulty":2,"kind":"mc","stem":"온라인 대화를 하다가 잘 모르는 사람이 사는 곳과 학교를 물어 왔어요. 알맞은 행동은 무엇인가요?","options":[{"t":"알려 주지 않고, 부모님이나 선생님께 바로 알린다","correct":true},{"t":"예의를 지켜 사는 곳과 학교를 알려 준다","mis":"K4-2-u5-X29"},{"t":"혼자 판단해서 계속 대화한다","mis":"K4-2-u5-X30"}],"explanation":["신뢰가 가지 않는 사람과는 접촉하지 않아요.","내 정보를 알려 주지 않아요.","어른께 바로 도움을 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#12','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C40',2,'blank','auto','석원이는 할머니를 높이려고 ‘생일’ 대신 다른 낱말을 썼어요. 빈칸에 알맞은 말은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#13','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C36',2,'mc','auto','『국어』 238쪽 2번에서 친구에게 먼저 사과하고 싶은데 말로 하기 어려울 때 편지로 할 수 있다고 한 일은 무엇인가요?',ARRAY['K4-2-u5-X04']::text[],false,'{"seq":13,"concept":"K4-2-u5-C36","difficulty":2,"kind":"mc","stem":"『국어』 238쪽 2번에서 친구에게 먼저 사과하고 싶은데 말로 하기 어려울 때 편지로 할 수 있다고 한 일은 무엇인가요?","options":[{"t":"미안한 마음을 전달할 수 있다","correct":true},{"t":"사과하지 않아도 된다","mis":"K4-2-u5-X04"},{"t":"다른 친구에게 대신 말해 달라고 한다","mis":"K4-2-u5-X04"}],"explanation":["말로 하기 어려운 마음도 있어요.","편지로 쓰면 미안한 마음을 전할 수 있어요.","마음은 내가 표현해야 전해져요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"편지를 써서 상대에게 내 마음을 전하면 어떤 점이 좋을까?"},{"who":"친구 2","text":"친구에게 먼저 사과하고 싶은데 말로 하기 어려울 때 편지로 미안한 마음을 전달할 수 있어."},{"who":"친구 3","text":"마음을 담은 편지를 주고받으면 상대와 친해지고 더 사이좋게 지낼 수 있어."},{"who":"친구 4","text":"감사, 위로, 축하, 응원과 같은 마음을 직접 편지로 써서 전하면 생각할 시간이 충분하고 고쳐 쓸 수도 있어서 진심을 더 잘 전할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#14','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C45',2,'mc','auto','편지로 마음을 전하고 싶은 일로 『국어』 242쪽에 나온 예가 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X45']::text[],false,'{"seq":14,"concept":"K4-2-u5-C45","difficulty":2,"kind":"mc","stem":"편지로 마음을 전하고 싶은 일로 『국어』 242쪽에 나온 예가 아닌 것은 무엇인가요?","options":[{"t":"어제 본 텔레비전 프로그램의 줄거리","correct":true},{"t":"동생이 줄넘기 대회에서 상을 받은 일","mis":"K4-2-u5-X45"},{"t":"편찮으신 할아버지께 병문안을 간 일","mis":"K4-2-u5-X45"}],"explanation":["마음을 전하고 싶은 일은 그 사람과 마음이 오간 일이에요.","축하, 사과, 위로, 감사를 전할 일을 떠올려요.","줄거리는 마음을 전할 일이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#15','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C43',2,'mc','auto','편찮으신 할아버지께 편지를 쓸 때 읽는 이를 생각한 표현으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X44','K4-2-u5-X28']::text[],false,'{"seq":15,"concept":"K4-2-u5-C43","difficulty":2,"kind":"mc","stem":"편찮으신 할아버지께 편지를 쓸 때 읽는 이를 생각한 표현으로 알맞은 것은 무엇인가요?","options":[{"t":"“할아버지, 어서 건강을 회복하셨으면 좋겠어요.”","correct":true},{"t":"“할아버지, 저는 어제 하루 종일 신나게 놀았어요.”만 쓴다","mis":"K4-2-u5-X44"},{"t":"“할아버지, 빨리 나아.”","mis":"K4-2-u5-X28"}],"explanation":["할아버지는 편찮으신 상황이에요.","그 마음과 상황을 헤아려 써요.","웃어른이니 높임 표현도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#16','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C60',2,'ox','auto','그림말은 무조건 쓰면 안 되는 말이에요.',ARRAY['K4-2-u5-X67']::text[],false,'{"seq":16,"concept":"K4-2-u5-C60","difficulty":2,"kind":"ox","stem":"그림말은 무조건 쓰면 안 되는 말이에요.","answer":"X","reason_options":[{"t":"기쁨이나 슬픔에 공감할 때 알맞게 쓰면 마음을 부드럽게 전할 수 있고, 주제와 관련 없이 되풀이하는 것이 문제이기 때문에","correct":true},{"t":"그림말은 온라인 대화 예절에 늘 어긋나기 때문에","mis":"K4-2-u5-X67"}],"mis":"K4-2-u5-X67","explanation":["그림말로 공감하거나 부드럽게 거절할 수 있어요.","그림말만 잔뜩 쓰면 뜻을 알기 어려워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#17','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C33',3,'ox','auto','온라인 대화 관찰 기록표는 정답이 정해져 있지 않으니, 예절을 지키며 적극적으로 참여했는지를 중심으로 동료 평가와 자기 평가를 해요.',ARRAY['K4-2-u5-X62']::text[],false,'{"seq":17,"concept":"K4-2-u5-C33","difficulty":3,"kind":"ox","stem":"온라인 대화 관찰 기록표는 정답이 정해져 있지 않으니, 예절을 지키며 적극적으로 참여했는지를 중심으로 동료 평가와 자기 평가를 해요.","answer":"O","reason_options":[{"t":"이 평가는 특정 내용이나 매체를 정하지 않고, 예절을 지키며 참여하는지를 중점으로 보기 때문에","correct":true},{"t":"평가는 누가 가장 많이 말했는지로 정하기 때문에","mis":"K4-2-u5-X62"}],"mis":"K4-2-u5-X62","explanation":["특정 내용, 매체, 형식을 제한하지 않아요.","상황과 상대를 이해하고 예절을 지키는지 봐요.","그래서 O예요."],"asset":{"type":"passage","lines":["계획하기 — 상대를 고려하여 매체를 선택했는가? · 좋은 점과 문제점을 고려했는가?","온라인 대화 하기 — 상대가 흥미를 느낄 만한 내용인가? ·","        주제와 관련 있는 내용을 이야기했는가? · 사실과 다른 내용을 말하지 않았는가?","참여 태도 — 주제와 관련 없는 말이나 그림말을 반복하지 않았는가? ·","        불쾌감을 주지 않았는가? · 바른 말, 고운 말을 썼는가? ·","        상대의 허락 없이 대화를 끊지 않았는가? · 적극적으로 참여했는가?","(매우 잘함 ●●● · 잘함 ●● · 보통임 ●)"],"title":"온라인 대화 관찰 기록표 (평가 자료 1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#18','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C62',3,'error','auto','이황의 편지를 읽고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?',ARRAY['K4-2-u5-X37','K4-2-u5-X63']::text[],false,'{"seq":18,"concept":"K4-2-u5-C62","difficulty":3,"kind":"error","stem":"이황의 편지를 읽고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“이황은 손자에게 공부를 그만두라고 했어.”","correct":true,"mis_target":"K4-2-u5-X37"},{"t":"“세월이 물처럼 흐르니 허투루 보내지 말라고 했어.”","mis":"K4-2-u5-X63"},{"t":"“걱정하는 마음과 보고 싶은 마음이 함께 담겨 있어.”","mis":"K4-2-u5-X63"}],"explanation":["이황은 천 번 만 번 힘써서 공부하라고 했어요.","걱정과 그리움이 함께 담겨 있어요.","공부를 그만두라는 말은 없어요."],"asset":{"type":"passage","lines":["손자 안도에게","(간추림) 산속 절에 머물며 공부하기로 했다는 소식을 듣고 좋은 일이라고 했다.","세월은 물처럼 흐른단다. 그러니 허투루 보내지 말고 천 번 만 번 힘써서 공부하거라.","(간추림) 흐지부지 보내면 공부가 흩어질까 걱정스럽다고 했다.","네가 얼마나 보고 싶은지 모른다.","(간추림) 생일 선물을 가져온 마음은 고맙지만 너희 얼굴을 보는 것이 더 기쁘다고 했다.","1568년 퇴계 이황"],"title":"이황이 손자에게 쓴 편지 (평가 자료 2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#19','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C50',3,'mc','auto','『국어』 244쪽 점검에서 「읽는 이를 고려해 썼나요?」에 「아니요」가 나왔다면 어떻게 고쳐 쓰나요?',ARRAY['K4-2-u5-X31','K4-2-u5-X39']::text[],false,'{"seq":19,"concept":"K4-2-u5-C50","difficulty":3,"kind":"mc","stem":"『국어』 244쪽 점검에서 「읽는 이를 고려해 썼나요?」에 「아니요」가 나왔다면 어떻게 고쳐 쓰나요?","options":[{"t":"편지를 읽는 사람의 마음을 헤아리며 쓰고, 상대에 따라 높임 표현을 바르게 쓴다","correct":true},{"t":"표시를 「예」로 바꾸어 둔다","mis":"K4-2-u5-X31"},{"t":"추신을 하나 더 쓴다","mis":"K4-2-u5-X39"}],"explanation":["「아니요」가 나온 물음이 고칠 곳이에요.","읽는 사람의 마음을 헤아려요.","상대에 따라 높임 표현을 바르게 써요."],"asset":{"type":"passage","lines":["1 편지의 짜임에 맞게 썼나요?","2 마음을 전하는 글의 내용을 자세히 썼나요?","3 전하고 싶은 마음이 잘 드러났나요?","4 읽는 이를 고려해 썼나요?","→ 「아니요」가 나오면 그 물음에 맞게 고쳐 쓰고, 「예」면 다음 물음으로 간다.","→ 마지막에는 다시 한번 읽고 부족한 부분이 있으면 고쳐 쓴다."],"numbered":false,"title":"읽는 이를 생각하며 마음을 잘 표현했는지 점검하기 — 『국어』 244쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#20','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C40',3,'error','auto','고쳐 쓸 곳이 있는 편지를 고쳐 쓰려고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?',ARRAY['K4-2-u5-X40','K4-2-u5-X64']::text[],false,'{"seq":20,"concept":"K4-2-u5-C40","difficulty":3,"kind":"error","stem":"고쳐 쓸 곳이 있는 편지를 고쳐 쓰려고 친구들이 말했어요. 알맞지 않은 말은 무엇인가요?","options":[{"t":"“‘지석원 씀’은 그대로 두어도 돼. 할머니께도 ‘씀’을 쓰면 되거든.”","correct":true,"mis_target":"K4-2-u5-X40"},{"t":"“‘할머니에게’를 ‘할머니께’로 고쳐야 해.”","mis":"K4-2-u5-X40"},{"t":"“‘생일’은 ‘생신’으로 고쳐야 해.”","mis":"K4-2-u5-X64"}],"explanation":["웃어른께 쓰는 편지예요.","받는 사람, 낱말, 쓴 사람을 모두 높여요.","쓴 사람 이름 뒤에는 ‘올림’이나 ‘드림’을 써요."],"asset":{"type":"passage","lines":["할머니에게","할머니, 저 석원이예요. 할머니에게 감사의 마음을 전하고 싶어서","이렇게 편지를 썼어요. 제 마음 아시죠? 항상 고맙습니다.","다음 주면 할머니의 생일이네요. 가족과 할머니 집으로 갈게요.","할머니, 사랑해요.","지석원 씀"],"title":"고쳐 쓸 곳이 있는 편지 (참고 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#21','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C63',3,'ox','auto','토의할 때에는 의견을 마련하기 전에 먼저 의견을 결정해 두어야 해요.',ARRAY['K4-2-u5-X65']::text[],false,'{"seq":21,"concept":"K4-2-u5-C63","difficulty":3,"kind":"ox","stem":"토의할 때에는 의견을 마련하기 전에 먼저 의견을 결정해 두어야 해요.","answer":"X","reason_options":[{"t":"토의는 주제 정하기 → 의견 마련하기 → 의견 모으기 → 의견 결정하기 순서로 하기 때문에","correct":true},{"t":"결정을 먼저 해 두어야 토의가 빨리 끝나기 때문에","mis":"K4-2-u5-X65"}],"mis":"K4-2-u5-X65","explanation":["의견을 모으기 전에 결정하면 토의가 되지 않아요.","결정은 마지막에 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#22','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C14',3,'mc','auto','이 글에서 “온라인 공간에서 여러분이 남긴 글은 여러분의 얼굴이기도 합니다.”라고 한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X14','K4-2-u5-X20']::text[],false,'{"seq":22,"concept":"K4-2-u5-C14","difficulty":3,"kind":"mc","stem":"이 글에서 “온라인 공간에서 여러분이 남긴 글은 여러분의 얼굴이기도 합니다.”라고 한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"얼굴이 보이지 않아도 내가 쓴 글이 나를 보여 주니 바르고 고운 말을 써야 하기 때문","correct":true},{"t":"온라인에서는 얼굴이 안 보이니 아무 말이나 써도 되기 때문","mis":"K4-2-u5-X14"},{"t":"글에 꼭 내 얼굴 사진을 붙여야 하기 때문","mis":"K4-2-u5-X20"}],"explanation":["말과 글은 생각을 담아 전하는 그릇이에요.","내가 남긴 글로 사람들은 나를 알게 돼요.","그래서 바르고 고운 말을 써요."],"asset":{"type":"passage","lines":["첫째, 온라인 공간에서 언어는 조심스럽게 사용합니다.","(간추림) 인터넷에 남긴 글은 삭제가 힘드니 남기기 전에 꼼꼼히 읽어 본다.","둘째, 온라인 공간에서 대화를 나눌 때도 다른 사람의 이야기를 먼저 들어 주려고 애씁니다.","셋째, 바르고 고운 언어의 사용은 인터넷을 아름답고 따뜻하게 만들 수 있습니다.","(간추림) 온라인 공간에 남긴 글은 그 사람의 얼굴이기도 하다."],"title":"「디지털 시대의 바람직한 의사소통을 위한 노력」(한국정보화진흥원)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#23','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C34',4,'essay','teacher','『국어』 237쪽 「더 나아가기」처럼 온라인 대화 예절에 대한 나의 다짐을 공손한 표현으로 쓰고, 그 다짐을 정한 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u5-C34","difficulty":4,"kind":"essay","stem":"『국어』 237쪽 「더 나아가기」처럼 온라인 대화 예절에 대한 나의 다짐을 공손한 표현으로 쓰고, 그 다짐을 정한 까닭을 쓰세요.","answer_guide":{"answer":"예: 「저는 대화방에 친구를 초대할 때 먼저 들어올지 물어볼 거예요.」 — 묻지 않고 초대받았을 때 내 시간을 빼앗긴 것 같아 속상했던 적이 있기 때문이다.","scoring_points":["온라인 대화 예절 하나를 다짐으로 썼는가","공손한 표현으로 썼는가","다짐을 정한 까닭을 썼는가"]},"explanation":["담임 선생님 글에 다는 댓글이에요.","시우처럼 공손한 표현으로 써요.","왜 그 다짐을 정했는지 까닭도 써요."],"asset":{"type":"speech","turns":[{"who":"담임 선생님","text":"온라인 대화 예절에 대한 나의 다짐을 댓글로 남겨 주세요."},{"who":"시우","text":"저는 온라인 대화를 할 때 공손한 표현을 사용할 거예요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#24','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C46',4,'essay','teacher','『국어활동』 73쪽처럼 우리 반 친구들과 있었던 일을 떠올려, 마음을 전할 사람 · 있었던 일 · 전하고 싶은 마음을 정리하고 전하고 싶은 말을 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u5-C46","difficulty":4,"kind":"essay","stem":"『국어활동』 73쪽처럼 우리 반 친구들과 있었던 일을 떠올려, 마음을 전할 사람 · 있었던 일 · 전하고 싶은 마음을 정리하고 전하고 싶은 말을 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 마음을 전할 사람 — 우리 반 친구들 / 있었던 일 — 내가 학교에 오지 못한 동안 학급 문고를 정리하고 화분에 물을 주었다 / 전하고 싶은 마음 — 고마운 마음 / 「학교에 다시 와 보니 너희가 학급 문고를 정리하고 화분에 물을 주었더라. 너희의 따뜻한 마음 덕분에 힘이 났어. 정말 고마워.」","scoring_points":["마음을 전할 사람과 있었던 일을 썼는가","전하고 싶은 마음을 썼는가","있었던 일과 마음이 드러나게 전하고 싶은 말을 썼는가"]},"explanation":["함께 겪은 일을 떠올려요.","그때 어떤 마음이었는지 정리해요.","있었던 일과 마음을 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u5_review_d#25','kor',4,2,'u5','','tb_g4_2_kor_u5_review_d','unit_review','K4-2-u5-C56',4,'essay','teacher','비밀 친구 활동을 하며 편지를 쓸 때 지킬 점 두 가지를 쓰고, 그렇게 해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u5-C56","difficulty":4,"kind":"essay","stem":"비밀 친구 활동을 하며 편지를 쓸 때 지킬 점 두 가지를 쓰고, 그렇게 해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 편지의 형식을 지키며 전하려는 마음이 잘 드러나게 쓴다. 받는 친구가 내 마음을 잘 알 수 있기 때문이다. 둘째, 둘만의 특별한 경험 대신 친구의 장점을 칭찬한다. 특별한 경험을 쓰면 비밀 친구가 누구인지 밝혀질 수 있기 때문이다.","scoring_points":["지킬 점을 두 가지 썼는가","지킬 점마다 까닭을 썼는가","비밀 친구 활동의 뜻에 맞는가"]},"explanation":["편지의 형식을 지켜요.","친구의 장점을 칭찬해요.","왜 그래야 하는지 까닭을 붙여요."],"asset":{"type":"passage","lines":["나의 비밀 친구에게","안녕? 친구야.","(간추림) 4학년 첫날 환하게 웃으며 인사하던 모습을 본 뒤로 친해지고 싶었다.","(간추림) 운동을 잘하고 수업 시간에 자신 있게 발표하는 모습이 멋지다고 했다.","지금은 내가 누구인지 밝힐 수 없지만 나도 너에게 좋은 친구가 되고 싶어.","20○○년 ○○월 ○○일","너의 비밀 친구가"],"title":"비밀 친구에게 쓴 편지 (예시) — 『국어』 247쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
